[23794] = {name = "[q2]영구적인 잔자의 광휘", additional_info = "획득 시 귀속\n고유 아이템\n요구 레벨 55\n[q2]사용 효과: 2시간 동안 적대적인 주문을 반사할 확률이 3%만큼 증가합니다. 자동으로 사용자를 목표로 한 첫 번째 공격 주문을 반사합니다. 잔자의 물약은 동시에 하나만 사용할 수 있습니다.\n[q]\"잔자의 마력이 깃들어 있습니다!\""},
[23795] = {name = "[q2]영구적인 잔자의 기백", additional_info = "획득 시 귀속\n고유 아이템\n요구 레벨 55\n[q2]사용 효과: 2시간 동안 정신력을 50만큼 체력을 50만큼 증가시킵니다. 잔자의 물약은 동시에 하나만 사용할 수 있습니다.\n[q]\"잔자의 마력이 깃들어 있습니다!\""},
[23796] = {name = "[q2]영구적인 잔자의 신속", additional_info = "획득 시 귀속\n고유 아이템\n요구 레벨 55\n[q2]사용 효과: 2시간 동안 달리기 속도가 20%만큼 증가합니다. 잔자의 물약은 동시에 하나만 사용할 수 있습니다.\n[q]\"잔자의 마력이 깃들어 있습니다!\""},
[24071] = {name = "[q3]평범한 단검", additional_info = "{한손 장비} {단검}\n{공격력 82 } {속도 1.80}\n(초당 공격력 45.56)\n내구도 65 / 65\n[q]\"내부 테스트용으로 만들어진 것 같습니다.\""},
