[122270] = {name = "[q8]WoW 토큰", additional_info = "획득 시 귀속\n[q]\"경매장에서 골드로 교환할 수 있습니다. 경매장에서 골드를 WoW 토큰으로 교환한 사람은 토큰을 사용하여 자신의 계정에 게임 시간 30일을 추가할 수 있습니다. \""},
[122284] = {name = "[q8]WoW 토큰", additional_info = "획득 시 귀속\n[q]\"사용 효과: 이 월드 오브 워크래프트 계정에 게임 시간 30일을 추가합니다.<이 WoW 토큰은 환불하거나 다시 게임 내 경매장에 등록할 수 없습니다.>\""},
[172070] = {name = "고객 지원 소포", additional_info = "획득 시 귀속\n[q]\"자신의 직업 및 레벨에 맞는 아이템이 들어 있습니다. 비어 있는 가방 칸 15개가 필요합니다.\""},
