[190232] = {name = "너덜너덜한 목도리", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"천에 섬세한 무늬뿐만 아니라 글자 'M+K'도 함께 수놓아져 있습니다.\""},
[190307] = {name = "불을 붙이지 않은 횃불", additional_info = "창조 아이템\n퀘스트 아이템\n고유 아이템\n[q]\"불만 붙였다면 꽤 멋진 횃불이 되었을텐데요.\""},
