[191204] = {name = "[q2]하급 죽음의 돌", additional_info = "획득 시 귀속\n[q2]사용 효과: 하급 죽음의 돌 100개를 결합하여 상급 죽음의 돌 1개를 만듭니다."},
[191249] = {name = "[q2]상급 죽음의 돌", additional_info = "획득 시 귀속\n[q]\"선명한 녹색 돌에서 은은한 빛과 함께 형용할 수 없는 힘이 퍼져 나옵니다.\""},
[191267] = {name = "[q2]순간이동의 룬: 대기실", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 낙스라마스의 대기실로 순간이동합니다."},
[191268] = {name = "[q2]타락의 보주", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 보주를 파괴하고 30분 동안 켈투자드의 하수인으로부터 흡수하는 하급 죽음의 돌이 50%만큼 증가합니다."},
[191272] = {name = "[q3]강령술의 봉", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 낙스라마스 내에 있는 언데드 대상의 의지를 꺾어, 5분 동안 현혹시킵니다.\n3회 사용 가능"},
[191280] = {name = "[q3]버섯 포자 다발", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 공격 기술이 일정 확률로 처치 시 근처 플레이어에게 곰팡이 번식을 시전하는 포자를 소환합니다. 효과는 1시간 동안 지속됩니다.\n\n곰팡이 번식 \n1초마다 150의 자연 피해를 입힘\n 근접 공격, 원거리 공격, 주문의 치명타 및 극대화 확률이 15%만큼 증가 (효과 발동 확률: 10%, 15초 재사용 대기시간)"},
[191288] = {name = "[q4]순간이동의 룬: 서리고룡 둥지", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 낙스라마스의 서리고룡 둥지로 순간이동합니다."},
[191292] = {name = "[q3]의식용 단검", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 주변의 생명력을 흡수하며, 적중하는 대상마다 체력이 3만큼 증가합니다. 해당 효과는 최대 40번까지 중첩되며 1시간 동안 지속됩니다."},
[191312] = {name = "[q4]안전장치 성물함", additional_info = "획득 시 귀속\n고유 아이템\n지속 시간: 7 일장신구\n요구 레벨 60\n[q2]착용 효과: 죽을 수도 있는 공격을 피합니다. 이 효과가 발동되면 3초의 피해 면역 효과를 얻으며 성물함을 파괴합니다."},
[191313] = {name = "죽음의 가면", additional_info = "지속 시간: 7 일\n[q2]사용 효과: 낙스라마스 주민의 형상으로 변합니다."},
[191414] = {name = "[q3]해골 유물", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 죽은 대상의 영혼을 가두어 1시간 동안 지속되는 이로운 효과를 얻습니다."},
[191458] = {name = "[q0]파괴된 성물함", additional_info = "획득 시 귀속\n고유 아이템\n지속 시간: 7 일장신구\n요구 레벨 60\n[q]\"볼품없고 쓸모없습니다.\""},
[191459] = {name = "[q4]행운의 룬", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 켈투자드와 그의 부관들이 강령술 마력으로 강화되어 생명력과 공격력이 증가합니다. 강화된 적을 처치하면 추가 보상을 획득할 수 있습니다.\n\n 해당 효과는 중첩되며 일주일간 지속됩니다."},
[191477] = {name = "[q4]해골 말뚝대", additional_info = "획득 시 귀속\n고유 아이템\n지속 시간: 7 일\n요구 레벨 60\n[q2]사용 효과: 해골 말뚝대를 소환합니다.\n\n 파티원이 말뚝대를 사용해 해골 전투마를 획득할 수 있습니다."},
[191480] = {name = "[q4]해골 전투마", additional_info = "획득 시 귀속\n고유 아이템\n지속 시간: 1 시간\n탈것\n요구 레벨 40\n[q2]사용 효과: 해골 전투마를 소환하거나 소환 해제합니다. 이 전투마는 소환자의 명령을 따르며 낙스라마스 내에서 탈것으로 이용할 수 있습니다. 올라탄 상태에서 공격을 받으면 해골마가 겁에 질려 달아납니다. (3 초 재사용 대기시간)"},
[191481] = {name = "[q4]숙련의 휘장", additional_info = "획득 시 귀속\n장신구\n[q]\"숙련도에 대한 징표입니다.\""},
