[191613] = {name = "[q4]서적: 죽음의 돌 - 행운의 룬", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 60\n[q]\"죽음의 돌로 행운의 룬을 만드는 방법이 적힌 마법서입니다.\""},
[191614] = {name = "[q4]서적: 죽음의 돌 - 해골 말뚝대", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 60\n[q]\"죽음의 돌로 해골 말뚝대를 만드는 방법이 적힌 마법서입니다.\""},
[191656] = {name = "[q4]죽음의 정수", additional_info = "획득 시 귀속\n[q2]<열려면 마우스 오른쪽 클릭>"},
[191660] = {name = "[q3]타디우스의 번개 나사", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 화살이 목에 꽂히며 무작위로 양전하 또는 음전하를 부여하고, 피해와 치유량이 1%만큼 증가합니다.\n\n 주변 아군이 비슷한 양상을 띄면 효과가 중첩되며, 반대 양상을 띄는 아군에게 자연 피해를 입힙니다."},
[191661] = {name = "[q3]무시무시한 거미 송곳니", additional_info = "획득 시 귀속\n지속 시간: 7 일\n[q2]사용 효과: 송곳니로 자신을 찌르면 1시간 동안 이동 속도, 공격 속도, 주문 시전 시간이 15%만큼 증가합니다. (효과 발동 확률: 5%, 30초 재사용 대기시간)"},
[191664] = {name = "[q3]서적: 죽음의 돌 - 타디우스의 번개 나사", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 60\n[q]\"죽음의 돌로 타디우스의 번개 나사를 만드는 방법이 적힌 마법서입니다.\""},
[191666] = {name = "[q3]서적: 죽음의 돌 - 무시무시한 거미 송곳니", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 60\n[q]\"죽음의 돌로 무시무시한 거미 송곳니를 만드는 방법이 적힌 마법서입니다.\""},
[202251] = {name = "애완동물 간식 가방", additional_info = "획득 시 귀속\n[q2]사용 효과: 간식 가방을 열고 대상의 주머니에 욱여넣습니다. 야수가 대상에게 입히는 피해가 20만큼 증가합니다. (1 분 재사용 대기시간)"},
[202254] = {name = "[q3]재이동의 팔보호구", additional_info = "착용 시 귀속\n{손목} {가죽}\n방어도 44\n체력 +11\n지능 +13\n정신력 +8\n내구도 35 / 35\n요구 레벨 60\n[q2]착용 효과: 주문이 극대화 효과를 낼 확률이 1%만큼 증가합니다."},
[202256] = {name = "[q2]사략 해적의 화려한 권총", additional_info = "획득 시 귀속\n{원거리 장비} {총}\n{공격력 6 - 13 } {속도 1.90}\n(초당 공격력 5.00)\n내구도 35 / 35\n직업: 도적\n{[q2]착용 효과: 빠른 사격 능력을 얻습니다.\n\n\n빠르게 원거리 무기를 뽑아 적에게 발포합니다. 일반 원거리 무기 공격력}에 해당하는 피해를 입히고 6초 동안 대상의 이동 {속도를 50%만큼 감소시킵니다. 연계 점수 1점을 생성합니다.\n\n 빠른 사격은 사악한 일격으로 발동하거나 사악한 일격의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.}"},
[202641] = {name = "진흙으로 뒤덮인 공책", additional_info = "획득 시 귀속\n퀘스트 시작 아이템\n직업: 도적\n[q]\"이 책은 진흙으로 덮여 있으나, 책장에 룬이 새겨져 있고, 일종의 속어로 된 짧은 기록이 적혀 있습니다.\""},
[203723] = {name = "커티의 쪽지", additional_info = "획득 시 귀속\n직업: 도적\n[q]\"도둑들 특유의 위선적인 표현으로 쓰인 전언입니다.\"\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[203726] = {name = "[q2]커티의 룬", additional_info = "직업: 도적"},
[203745] = {name = "[q2]주문 기록: 얼음창", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n각인술\n(1) 필요\n[q2]장갑에 얼음창 룬을 새깁니다.\n\n\n적 대상에게 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 55 / 100 * ( 1 ) ]에서 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 65 / 100 * ( 1 ) ]의 냉기 피해를 입힙니다. 얼어붙은 대상에게는 400%의 피해를 입힙니다.\n\n 다른 냉기 주문으로 NPC 대상에게 피해를 입히면 대상이 시전자의 다음 얼음창으로 받는 피해가 20%만큼 증가합니다. 이 효과는 5번까지 중첩되며 혹한의 추위 특성이 필요합니다.\n[q]\"룬조각술 능력을 배웁니다.\""},
[203746] = {name = "[q2]주문 기록: 살아있는 불꽃", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n각인술\n(1) 필요\n[q2]바지에 살아있는 불꽃 룬을 새깁니다.\n\n\n대상 방향으로 이동하는 비전화염 불꽃을 소환합니다. 불꽃은 비전화염의 흔적을 남깁니다. 흔적은 주위의 적에게 1초마다 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 100 / 100]의 비전화염 피해를 입힙니다. 10초 동안 지속됩니다.\n[q]\"룬조각술 능력을 배웁니다.\""},
[203747] = {name = "[q2]주문 기록: 서리의 손가락", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n각인술\n(1) 필요\n[q2]가슴보호구 또는 로브에 서리의 손가락 룬을 새깁니다.\n\n\n빙결 효과를 일으키면 25%의 확률로 서리의 손가락 효과를 받아, 자신이 시전하는 다음 2회의 주문은 얼어붙은 대상을 공격하는 효과를 내도록 합니다. 15초 동안 지속됩니다.\n[q]\"룬조각술 능력을 배웁니다.\""},
[203748] = {name = "[q2]주문 기록: 완전 연소", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]가슴보호구에 완전 연소 룬을 새깁니다.\n\n\n모든 주문의 주문 극대화율이 15%만큼 증가하지만 비주기적인 주문이 극대화 효과를 발휘할 때 기본 마나의 1%를 추가로 소모합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203749] = {name = "[q2]주문 기록: 깨달음", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n{[q2]가슴보호구 또는 로브에 깨달음 룬을 새깁니다.\n\n\n마나가 70% 이상일 때 공격력}이 10%만큼 증가합니다. 마나가 30% 미만일 때는 주문을 시전하는 동안에도 마나 회복 {속도의 10%가 유지됩니다.}\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203750] = {name = "엘윈 보물 지도", additional_info = "획득 시 귀속\n직업: 도적\n[q2]사용 효과: 표시된 위치에서 보물을 파냅니다. (1 분 재사용 대기시간)\n[q]\"마루목 감시탑 서쪽. 늑대 소굴 뒤쪽 그루터기 근처.\""},
[203751] = {name = "[q2]주문 기록: 창음얼", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 지침서로 주문 기록을 해석하여 새로운 조각술 주문을 배웁니다."},
[203752] = {name = "[q2]주문 기록: 는살있아 꽃불", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[203753] = {name = "[q2]주문 기록: 의리서 락가손", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[203754] = {name = "대마법사 안토니다스: 자서전 원본", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"내용이 다소 제멋대로인 감이 있지만, 어쨌든 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[203755] = {name = "대마법사 테오크리투스의 연구 일지", additional_info = "고유 아이템\n[q]\"아조라의 탑에서 만들어진 연구 기록입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[203756] = {name = "[q2]아조라 수습생 기록: 1쪽", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 아조라 수습생 기록 6개를 결합하여 새로운 각인술 제작법을 만듭니다."},
[203784] = {name = "오른쪽 위 지도 조각", additional_info = "[q2]사용 효과: 다른 3개의 조각을 결합하여 완전한 지도를 만듭니다.\n[q]\"찢어진 조각입니다. 지도의 일부로 보입니다...\""},
[203785] = {name = "왼쪽 위 지도 조각", additional_info = "[q2]사용 효과: 다른 3개의 조각을 결합하여 완전한 지도를 만듭니다.\n[q]\"찢어진 조각입니다. 지도의 일부로 보입니다...\""},
[203786] = {name = "오른쪽 아래 지도 조각", additional_info = "[q2]사용 효과: 다른 3개의 조각을 결합하여 완전한 지도를 만듭니다.\n[q]\"찢어진 조각입니다. 지도의 일부로 보입니다...\""},
[203787] = {name = "왼쪽 아래 지도 조각", additional_info = "[q2]사용 효과: 다른 3개의 조각을 결합하여 완전한 지도를 만듭니다.\n[q]\"찢어진 조각입니다. 지도의 일부로 보입니다...\""},
[203960] = {name = "[q2]아조라 수습생 기록: 2쪽", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 아조라 수습생 기록 6개를 결합하여 새로운 각인술 제작법을 만듭니다."},
[203961] = {name = "[q2]아조라 수습생 기록: 3쪽", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 아조라 수습생 기록 6개를 결합하여 새로운 각인술 제작법을 만듭니다."},
[203962] = {name = "[q2]아조라 수습생 기록: 4쪽", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 아조라 수습생 기록 6개를 결합하여 새로운 각인술 제작법을 만듭니다."},
[203990] = {name = "[q2]절단의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장갑에 절단 룬을 새깁니다.\n\n\n양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 95%에 [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100]의 추가 피해를 입힙니다. 독에 걸린 대상을 가격할 시 공격력이 20%만큼 증가합니다. 연계 점수 2점이 주어집니다.\n\n 절단은 따로 명시되지 않은 이상 기습으로 발동하거나 기습의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203991] = {name = "[q2]빠른 사격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n{[q2]가슴보호구 또는 로브에 빠른 사격 룬을 새깁니다.\n\n\n빠르게 원거리 무기를 뽑아 적에게 발포합니다. 일반 원거리 무기 공격력}에 해당하는 피해를 입히고 6초 동안 대상의 이동 {속도를 50%만큼 감소시킵니다. 연계 점수 1점을 생성합니다.\n\n 빠른 사격은 사악한 일격으로 발동하거나 사악한 일격의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.}\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203992] = {name = "[q2]속임수의 룬", additional_info = "직업: 도적\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203993] = {name = "[q2]학살의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]가슴보호구 또는 로브에 어둠의 학살자 룬을 새깁니다.\n\n\n기습과 매복에 소모되는 기력이 30만큼 감소합니다. 또한 NPC 대상에게 입히는 피해가 70%만큼 증가합니다. [ 장갑 각인술 - 절단 : 절단에는 적용되지 않습니다 / 다른 룬으로 배운 능력에는 적용되지 않습니다.]\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[203994] = {name = "[q2]맹독 조합의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]가슴보호구 또는 맹독 조합 룬을 새깁니다.\n\n\n독에 여러 강화 효과를 부여합니다.\n\n 대상에게 다른 독을 부여하면 추가로 맹독을 겁니다.\n\n 무기에 독을 바르지 않은 상태일 경우, 일정 확률로 순간 효과 독을 바른 것처럼 순간 효과 독을 발동시킵니다.\n\n 맹독과 순간 효과 독은 이제 전투력의 이로운 효과를 받아 공격력이 증가합니다.\n\n 다른 도적의 맹독에 영향을 받는 대상에게도 맹독을 걸 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204174] = {name = "[q2]명중의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]바지에 미간 적중 룬을 새깁니다.\n\n\n적에게 원거리 마무리 일격을 날립니다. 연계 점수에 따라 피해를 입히며 전투력을 기반으로 증가합니다. 또한 대상을 기절시킵니다.\n\n 연계 점수 1점: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))]에서 [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60))]의 피해, 1초 동안 기절\n 연계 점수 2점: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)]에서 [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 2)]의 피해, 2초 동안 기절\n 연계 점수 3점: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)]에서 [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 3)]의 피해, 3초 동안 기절\n 연계 점수 4점: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)]에서 [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 4)]의 피해, 4초 동안 기절\n 연계 점수 5점: [53 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)]에서 [81 / 100 * ((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) + (8.740728 - 0.415787 * 60 + 0.051973 * 60 * 60) * 5)]의 피해, 5초 동안 기절\n\n 급소 가격과 재사용 대기시간을 공유합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204270] = {name = "심연의 핵", additional_info = "고유 아이템"},
[204441] = {name = "[q2]피의 광란의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]가슴보호구에 피의 광란 룬을 새깁니다.\n\n\n분쇄를 광폭 태세일 때 사용할 수 있으며, 광폭의 공격력이 100%만큼 증가합니다. 또한 피해를 입힐 때마다 전투력의 4%에 해당하는 추가 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204476] = {name = "절단된 코볼트 머리카락", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"음울한 전리품입니다. 이 물건에 관심을 보일 만한 수집가가 있을지도 모릅니다...\""},
[204477] = {name = "절단된 멀록 머리", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"음울한 전리품입니다. 이 물건에 관심을 보일 만한 수집가가 있을지도 모릅니다...\""},
[204478] = {name = "절단된 놀 머리카락", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"음울한 전리품입니다. 이 물건에 관심을 보일 만한 수집가가 있을지도 모릅니다...\""},
[204688] = {name = "괴물 사냥꾼의 첫 번째 룬 조각", additional_info = "[q2]사용 효과: 다른 2개의 조각을 결합하여 완전한 룬을 만듭니다."},
[204689] = {name = "괴물 사냥꾼의 두 번째 룬 조각", additional_info = "[q2]사용 효과: 다른 2개의 조각을 결합하여 완전한 룬을 만듭니다."},
[204690] = {name = "괴물 사냥꾼의 세 번째 룬 조각", additional_info = "[q2]사용 효과: 다른 2개의 조각을 결합하여 완전한 룬을 만듭니다."},
[204703] = {name = "[q2]압도의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장갑에 압도 룬을 새깁니다.\n\n\n방어 태세가 활성화되어 있고 방패를 착용 중일 때 방어구 가르기가 1초마다 장착한 무기 공격력의 150%에 해당하는 추가 피해를 입힙니다. 대상에게 이미 부여된 방어구 가르기 중첩 하나당 효과가 15%만큼 증가합니다. 방어 태세일 때 압도가 높은 위협 수준을 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204716] = {name = "[q2]광란의 공격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]바지에 광란의 공격 룬을 새깁니다.\n\n\n양손 무기 사용 시 공격 속도가 40%만큼 증가합니다. 또한 근접 공격 적중 시 2의 분노를 추가로 생성합니다. 치명타 및 극대화로 적중 시 4의 추가 분노를 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204795] = {name = "[q2]그림자 일격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장갑에 그림자 일격 룬을 새깁니다.\n\n\n대상의 배후로 순간이동한 후 대상에게 일격을 날려 무기 공격력의 150%에 해당하는 피해를 입힙니다. 은신 상태로 사용해야 합니다. 연계 점수 1점을 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204804] = {name = "[q3]히드락시안 팔찌", additional_info = "획득 시 귀속\n{손목} {사슬}\n방어도 95\n힘 +4\n체력 +7\n내구도 40 / 40\n요구 레벨 25"},
[204806] = {name = "[q2]승리의 돌진의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장갑에 승리의 돌진 룬을 새깁니다.\n\n\n즉시 대상을 공격하여 (1 + 전투력 * 45 / 100)의 피해를 입히고 최대 생명력의 30%에 해당하는 생명력을 회복합니다. 자신이 결정타를 가하여 적을 처치한 후 경험치나 명예 점수를 받게 된 지 20초 내에만 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204807] = {name = "[q3]심연칼날", additional_info = "획득 시 귀속\n{양손 장비} {검}\n{공격력 71 - 107 } {속도 3.60}\n(초당 공격력 24.72)\n내구도 100 / 100\n요구 레벨 25\n[q2]발동 효과: 압축된 물로 전방의 모든 적을 강타합니다.\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q]\"휘두를 때마다 부서지는 파도 소리가 울려 퍼집니다.\""},
[204809] = {name = "[q2]격노의 천둥의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]바지에 격노의 천둥 룬을 새깁니다.\n\n\n천둥벼락 사용 시 공격 간격을 추가로 6%만큼 증가시키며 태세에 상관없이 사용할 수 있습니다. 또한 100%의 추가 피해를 입히고, 위협 수준이 75%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[204864] = {name = "[q2]아조라 수습생 기록", additional_info = "획득 시 귀속\n고유 아이템 (6)\n[q2]사용 효과: 아조라 수습생 기록 6개를 결합하여 새로운 각인술 제작법을 만듭니다."},
[204905] = {name = "불길한 고서", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 소보즈를 소환합니다.\n[q]\"늑대의 턱과 놀의 피를 양의 배 속에 채워 넣은 다음 주문을 외워라.\""},
[204906] = {name = "놀의 피", additional_info = "고유 아이템\n[q]\"소환 의식에 사용되는 재료입니다.\""},
[204907] = {name = "늑대 턱뼈", additional_info = "고유 아이템\n[q]\"소환 의식에 사용되는 재료입니다.\""},
[204910] = {name = "[q0]몬스터 - 삼지창, 나가 (금색)", additional_info = "획득 시 귀속\n{양손 장비} {장창}\n{공격력 2 - 4 } {속도 3.00}\n(초당 공격력 1.00)\n내구도 20 / 20"},
[204912] = {name = "[q2]은총의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]바지에 악마의 은총 룬을 새깁니다.\n\n\n지옥 마력이 쇄도하여 소환수와 자신의 회피율이 20%만큼, 모든 공격의 치명타 및 극대화율이 20%만큼 증가합니다. 6초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205019] = {name = "오염된 영혼의 조각", additional_info = "획득 시 귀속\n고유 아이템"},
[205020] = {name = "순수한 영혼의 조각", additional_info = "획득 시 귀속\n고유 아이템"},
[205022] = {name = "[q2]영혼 착취의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]망토에 영혼 착취 룬을 새깁니다.\n\n\n영혼 흡수가 피해를 입히는 속도가 3배만큼 빨라지고 생명력 흡수로 흡수하는 생명력과 영혼 흡수로 입히는 피해가 대상에 걸려 있는 자신의 흑마법사의 암흑 효과마다 6%만큼씩 증가합니다. 추가 효과는 최대 18%까지 증가합니다. 생명력이 20% 미만인 대상에게 영혼 흡수를 시전하면 입히는 피해가 효과마다 50%만큼 증가하며, 최대 150%까지 증가합니다. 추가로 영혼 흡수가 일몰 특성을 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205181] = {name = "미확인 유물", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"난해한 마법 물품입니다. 경험 많은 흑마법사라면 실체를 알려줄 수 있을 것입니다.\""},
[205182] = {name = "무력한 유물", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 피를 제물로 바쳐 유물을 활성화합니다."},
[205183] = {name = "지옥 동력 유물", additional_info = "획득 시 귀속\n고유 아이템"},
[205184] = {name = "수습흑마법사의 기록", additional_info = "획득 시 귀속\n고유 아이템\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[205215] = {name = "[q2]술책의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]가슴보호구 또는 로브에 악마의 술책 룬을 새깁니다.\n\n\n흑마법사와 소환수의 근접 공격 및 주문 치명타 및 극대화율이 10%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205218] = {name = "[q2]발견의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n요구 레벨 5\n[q2]망토에 영혼 착취 룬을 새깁니다.\n\n\n영혼 흡수가 피해를 입히는 속도가 3배만큼 빨라지고 생명력 흡수로 흡수하는 생명력과 영혼 흡수로 입히는 피해가 대상에 걸려 있는 자신의 흑마법사의 암흑 효과마다 6%만큼씩 증가합니다. 추가 효과는 최대 18%까지 증가합니다. 생명력이 20% 미만인 대상에게 영혼 흡수를 시전하면 입히는 피해가 효과마다 50%만큼 증가하며, 최대 150%까지 증가합니다. 추가로 영혼 흡수가 일몰 특성을 발동시킵니다.\n[q]\"적 5명을 처치하여 영감 상태가 된 후 사용하면 새로운 능력을 배웁니다.\""},
[205228] = {name = "[q2]혼돈의 화살의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장갑에 혼돈의 화살 룬을 새깁니다.\n\n\n혼돈의 불꽃을 적에게 발사하여 [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 522 / 100]에서 [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 662 / 100]의 혼돈 피해를 입힙니다. 혼돈의 화살은 반드시 적중하며 저항할 수 없습니다. 혼돈의 화살에 대한 지식으로 인해 모든 화염 주문이 흡수 효과를 관통합니다. 자신보다 4 레벨 이상 높은 몬스터에게 혼돈의 화살 시전 시 높은 확률로 저항됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205230] = {name = "[q2]음산함의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장갑에 유령 출몰 룬을 새깁니다.\n\n\n적에게 유령의 영혼을 방출해 [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 251 / 100]에서 [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 295 / 100]의 피해를 입히고 15초 동안 대상에게 입히는 모든 지속 암흑 피해가 40%만큼 증가합니다. 유령 출몰이 끝나거나 무효화되면 대상에게 입힌 모든 피해만큼 생명력을 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205364] = {name = "수습흑마법사의 배낭", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]<열려면 마우스 오른쪽 클릭>"},
[205420] = {name = "[q2]심판의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n[q2]장갑에 성전사의 일격 룬을 새깁니다.\n\n\n적에게 즉시 일격을 가하여 무기 공격력의 75%에 해당하는 신성 피해를 입히고 최대 마나의 5%를 회복합니다. 대상에게 걸린 모든 심판 효과의 지속시간이 30초로 갱신됩니다.\n[q]\"적에게 문장을 10번 방출하면 새로운 능력을 배웁니다.\""},
[205683] = {name = "[q2]비난의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]바지에 비난 룬을 새깁니다.\n\n\n적을 발로 가격하여 대상이 3초 동안 같은 계열의 주문을 시전하는 것을 방해합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205685] = {name = "[q2]보호의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]가슴보호구에 보호 룬을 새깁니다.\n\n\n방패의 피해 방어량이 30%만큼 증가하고 보루 특성이 변화합니다. 보루가 근접 또는 원거리 공격을 받을 때 10%의 확률로 발동하며, 근접 치명타를 적중시키면 항상 발동합니다. 추가로 징벌 특성의 경우, 근접 또는 원거리 공격을 받았을 때 발동할 확률이 특성 점수당 2%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205863] = {name = "타락한 성서", additional_info = "직업: 성기사"},
[205864] = {name = "까맣게 탄 기록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[205897] = {name = "[q2]천상의 빛의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]망토에 천상의 빛 룬을 새깁니다.\n\n\n아군 대상을 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 355 / 100]~[(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 393 / 100]만큼 치유합니다. 대상에 대한 초과 치유량의 50%를 피해 흡수 보호막으로 전환합니다. 보호막은 15초 동안 지속됩니다. 천상의 빛을 여러 번 시전해도 보호막은 중첩되지 않습니다.\n\n 천상의 빛은 천상의 빛으로 발동하거나 천상의 빛의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205905] = {name = "[q2]헌신적인 용사의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]가슴보호구 또는 로브에 뒤틀린 믿음 룬을 새깁니다.\n\n\n정신의 채찍 및 정신 분열이 어둠의 권능: 고통에 걸린 대상에게 50%의 추가 피해를 입힙니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205932] = {name = "[q2]왕의 최후의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장갑에 어둠의 권능: 죽음 룬을 새깁니다.\n\n\n어둠의 힘으로 대상에게 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 320 / 100]에서 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 372 / 100]의 암흑 피해를 입힙니다. 만약 대상이 어둠의 권능: 죽음에 의해 죽지 않았다면 시전자는 대상에게 입힌 피해의 50%에 해당하는 피해를 입습니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[205940] = {name = "[q2]어둠의 목적의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장화에 공허의 역병 룬을 새깁니다.\n\n\n대상에게 질병을 걸어 18초에 걸쳐 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 129 / 100 * 6]의 암흑 피해를 입힙니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205942] = {name = "키메라의 직관", additional_info = "[q2]바지에 회복의 기원 룬을 새깁니다.\n\n\n대상에 마력을 불어 넣어 다음에 피해를 입거나 치유 효과를 받을 시 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100]의 생명력을 회복하도록 합니다. 생명력이 회복될 때 20미터 반경 내의 파티원 혹은 공격대원에게로 회복의 기원이 전달됩니다. 최대 5번까지 이동하며 매 이동 시마다 효과는 30초 동안 지속됩니다. 이 주문은 동시에 한 대상에게만 걸 수 있습니다."},
[205943] = {name = "훼손된 성채의 예언", additional_info = "고유 아이템\n[q2]바지에 호문쿨루스 룬을 새깁니다.\n\n\n영혼의 일부를 쪼개어 자신의 작은 복제 3개를 살아 움직이게 하여, 현재 대상을 철퇴, 검, 도끼로 공격하게 합니다. 각 공격은 적중당한 대상의 공격 속도, 전투력, 방어도를 감소시킵니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[205944] = {name = "[q2]상호의 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]바지에 회복의 기원 룬을 새깁니다.\n\n\n대상에 마력을 불어 넣어 다음에 피해를 입거나 치유 효과를 받을 시 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100]의 생명력을 회복하도록 합니다. 생명력이 회복될 때 20미터 반경 내의 파티원 혹은 공격대원에게로 회복의 기원이 전달됩니다. 최대 5번까지 이동하며 매 이동 시마다 효과는 30초 동안 지속됩니다. 이 주문은 동시에 한 대상에게만 걸 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205945] = {name = "[q2]수감된 구원자의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]바지에 나누는 고통 룬을 새깁니다.\n\n\n어둠의 권능: 고통이 주위 15미터 내에 있는 최대 2명의 추가 대상에게 영향을 줍니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205946] = {name = "[q2]지도자의 배신의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장화에 고통 억제 룬을 새깁니다.\n\n\n아군 대상이 받는 모든 피해를 즉시 40%만큼 감소시키고 8초 동안 무효화에 대한 저항력을 65%만큼 증가시킵니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205947] = {name = "[q2]훼손된 성채의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]바지에 호문쿨루스 룬을 새깁니다.\n\n\n영혼의 일부를 쪼개어 자신의 작은 복제 3개를 살아 움직이게 하여, 현재 대상을 철퇴, 검, 도끼로 공격하게 합니다. 각 공격은 적중당한 대상의 공격 속도, 전투력, 방어도를 감소시킵니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[205948] = {name = "온건의 직관", additional_info = "[q2]망토에 흡혈의 손길 룬을 새깁니다.\n\n\n대상에게 흡혈의 선물 특성을 부여해, 대상을 암흑의 기운으로 감싸 대상에게 15초에 걸쳐 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 65 / 100 * 5]의 암흑 피해를 입히고 자신이 대상에게 입히는 암흑 주문 피해의 2%만큼 모든 파티원의 마나를 회복시킵니다."},
[205949] = {name = "다변화의 직관", additional_info = "직업: 사제\n[q2]장갑에 치유의 마법진 룬을 새깁니다.\n\n\n대상 플레이어의 43.5미터 내에 있는 모든 파티원을 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]에서 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100]만큼 치유합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205950] = {name = "[q2]암영의 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장갑에 정신 불태우기 룬을 새깁니다.\n\n\n암흑 마법을 폭발시켜 적 대상과 주위의 다른 적을 공격합니다. 대상의 10미터 내에 있는 모든 적에게 6초 동안 1초마다 [70 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)]$null~[78 / 100 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60)]의 암흑 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205951] = {name = "[q2]혼란에 빠진 수행사제의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장갑에 회개 룬을 새깁니다.\n\n\n신성한 빛의 화살로 적에게 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 128 / 100]의 신성 피해를 입히거나 2초 동안 즉시 그리고 매 1초마다 아군의 생명력을 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 85 / 100]만큼 회복시킵니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205952] = {name = "으스러진 세계의 기억", additional_info = "[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[205953] = {name = "[q2]깨진 서약의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 정신의 쐐기 룬을 새깁니다.\n\n\n대상을 강타하여 [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]에서 [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]의 암흑냉기 피해를 입힙니다. 또한 다음 정신 분열의 치명타 및 극대화율이 30%만큼 증가합니다. 최대 3번까지 중첩됩니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[205961] = {name = "멀고어 새 고기", additional_info = "고유 아이템\n[q2]사용 효과: 살쾡이 서식지 근처에 미끼를 놓습니다."},
[205979] = {name = "[q2]측방 공격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]바지에 측방 강타 룬을 새깁니다.\n\n\n시전자와 야수가 즉시 근접 공격력의 100%에 해당하는 피해를 입힙니다. 이후 10초 동안 공격력이 8%만큼 증가합니다. 최대 3번까지 중첩됩니다. 야수가 일반 공격을 사용할 때 50%의 확률로 측방 강타의 재사용 대기시간이 초기화됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[205995] = {name = "땅다람쥐 사향", additional_info = "직업: 사냥꾼\n[q2]사용 효과: 야수 길들이기 능력을 땅다람쥐에게도 사용할 수 있습니다. (애완동물 친구로 획득) (10 분 재사용 대기시간)"},
[206032] = {name = "[q2]저미기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]장갑에 저미기 룬을 새깁니다.\n\n\n근접 무기를 이용한 휩쓸기 공격으로 전방의 모든 적을 공격해 무기 공격력의 65%에 해당하는 피해를 입힙니다. 주 대상에게는 50%의 추가 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206155] = {name = "[q2]명사수의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]가슴보호구 또는 로브에 사격의 명수 룬을 새깁니다.\n\n\n치명타 적중률이 5%만큼 증가하고 모든 사격 능력의 마나 소모량이 25%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206157] = {name = "시포리움 채광 폭약", additional_info = "퀘스트 아이템\n고유 아이템 (5)"},
[206159] = {name = "투자개발회사 변장", additional_info = "퀘스트 아이템\n[q]\"사실 변장이라고 보기엔 어폐가 있긴 합니다만...\""},
[206168] = {name = "[q2]키메라의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]장갑에 키메라 사격 룬을 새깁니다.\n\n\n무기 공격력의 135%에 해당하는 피해를 입힌 후 대상에 걸려 있는 쐐기를 초기화하고 다음 효과를 발동시킵니다:\n\n 독사 쐐기 - 즉시 독사 쐐기 피해량의 48%에 해당하는 피해를 입힙니다.\n\n 살무사 쐐기 - 살무사 쐐기로 소진시킨 마나량의 60%에 해당하는 마나를 즉시 돌려받습니다.\n\n 전갈 쐐기 - 대상에게 10초 동안 무장 해제를 시도합니다. 이 효과는 1분마다 1번씩만 발동됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206169] = {name = "[q2]폭발 사격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]장갑에 폭발 사격 룬을 새깁니다.\n\n\n폭발의 화살이나 탄환을 발사하여 8미터 내의 모든 적에게 [원거리 공격력 * 0.039 + 62 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]~[원거리 공격력 * 0.039 + 94 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]의 화염 피해를 입힙니다. 추가로 2초 동안 매초마다 다시 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206170] = {name = "질풍의 솔방울", additional_info = "퀘스트 아이템"},
[206175] = {name = "소나무 연고", additional_info = "퀘스트 아이템\n고유 아이템"},
[206176] = {name = "막자 사발", additional_info = "퀘스트 아이템\n고유 아이템\n[q2]사용 효과: 질풍의 솔방울 8개를 분쇄하여 맹독 무기 연고를 만듭니다. 이론상으로는 말이죠."},
[206177] = {name = "잣 버터", additional_info = "획득 시 귀속\n[q2]사용 효과: 18초에 걸쳐 총 61.2의 생명력이 회복됩니다. 음식을 먹으려면 앉아 있어야 합니다. 음식을 꾸준히 10초 이상 먹게 되면 포만감을 느끼게 되고 15분 동안 체력과 정신력이 2만큼 증가합니다."},
[206264] = {name = "[q2]영감의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]바지에 영감의 모범 룬을 새깁니다.\n\n\n고무적인 존재감이 주기적으로 주위 파티원의 공포 및 수면 효과를 무효화합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206344] = {name = "식칼", additional_info = "퀘스트 아이템\n고유 아이템\n[q2]사용 효과: 비단잉어를 손질하는 시도를 합니다."},
[206345] = {name = "생선 토막", additional_info = "퀘스트 아이템\n고유 아이템"},
[206376] = {name = "[q2]보루의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]가슴보호구 또는 로브에 방패 숙련 룬을 새깁니다.\n\n\n방패 막기에 성공할 때마다 최대 마나의 8%에 해당하는 마나를 회복하고 방어도가 방패 방어도의 30%만큼 증가합니다. 최대 5번까지 중첩됩니다. 또한 항상 방패 막기 확률이 10%만큼, 방패 막기 수치가 15%만큼 증가합니다.\n\n 추가로 충격 능력을 시전할 때마다 ( 60 * 5)|1을;를; 넘는 방어 숙련 1점당 주문 공격력이이 4만큼 증가합니다. 15초 동안 지속됩니다.\n[q]\"대지의 무기로 적을 25번 공격하면 새로운 능력을 배웁니다.\""},
[206381] = {name = "[q2]이원의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]가슴보호구 또는 로브에 과부하 룬을 새깁니다.\n\n\n번개 화살, 연쇄 번개, 연쇄 치유, 치유의 물결, 용암 폭발 주문 시전 시 60%의 확률로 마나 소비 없이 같은 대상에게 유사한 주문을 시전하여 절반의 피해를 입히거나 생명력을 회복시킵니다. 이 주문은 위협 수준을 생성하지 않습니다.\n[q]\"자연 피해를 10번 받으면 새로운 능력을 배웁니다.\""},
[206382] = {name = "[q2]폭풍우의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]장갑에 물의 보호막 룬을 새깁니다.\n\n\n3개의 물방울이 시전자의 주위에 머무르며 5초마다 최대 마나의 1%를 회복합니다. 만약 시전자가 주문이나 근접 또는 원거리 공격에 적중 당하면 시전자는 물방울로부터 최대 마나의 4%를 흡수합니다. 매번 마나를 흡수할 때마다 물방울이 하나씩 사라집니다. 물방울이 하나 사라지면 다른 물방울이 효력을 발휘하기까지 일정 시간이 필요합니다. 10분 동안 지속됩니다. 주술사의 보호막은 동시에 하나만 유지할 수 있습니다.\n[q]\"서로 다른 3개의 원소(자연, 냉기, 화염)로 플레이어가 아닌 적을 10번 공격하면 새로운 능력을 배웁니다.\""},
[206383] = {name = "[q2]리디크의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]바지에 대지의 보호막 룬을 새깁니다.\n\n\n대상을 대지의 보호막으로 감싸 피해를 입을 시 정신 집중이나 주문 시전이 지연되는 시간이 30%만큼 감소하게 하고 보호막이 걸린 대상이 공격을 받을 시 [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]의 생명력을 회복하도록 합니다. 이 효과는 몇초마다 한 번씩만 발휘됩니다. 9회 사용 가능하며 10분 동안 지속됩니다. 대지의 보호막은 한 번에 한 대상에게만 걸 수 있습니다.\n[q]\"방패로 공격을 20번 막으면 새로운 능력을 배웁니다.\""},
[206384] = {name = "[q2]천공의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q]\"대지의 무기로 적을 25번 공격하면 새로운 능력을 배웁니다.\""},
[206385] = {name = "[q2]쇄설의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]바지에 대지의 길 룬을 새깁니다.\n\n\n주무기에 대지의 무기가 활성화되어 있고 방패를 장착 중일 경우 위협 수준이 65%만큼, 생명력이 25%만큼 증가합니다. 받는 피해는 10%만큼, 근접 공격 치명타에 적중당할 확률도 6%만큼 감소합니다. 또한 대지 충격 시전 시 대상을 도발해 자신을 공격하게 하고 다른 충격 주문과 재사용 대기시간이 분리됩니다. 사정거리가 근접 공격 범위로 감소합니다. 단, 번개 화살, 연쇄 번개, 연쇄 치유, 치유의 물결, 용암 폭발 주문의 사정거리가 20미터만큼 감소합니다.\n[q]\"대지 충격으로 적 20명을 처치하면 새로운 능력을 배웁니다.\""},
[206386] = {name = "[q2]전기의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]가슴보호구 또는 로브에 방패 숙련 룬을 새깁니다.\n\n\n방패 막기에 성공할 때마다 최대 마나의 8%에 해당하는 마나를 회복하고 방어도가 방패 방어도의 30%만큼 증가합니다. 최대 5번까지 중첩됩니다. 또한 항상 방패 막기 확률이 10%만큼, 방패 막기 수치가 15%만큼 증가합니다.\n\n 추가로 충격 능력을 시전할 때마다 ( 60 * 5)|1을;를; 넘는 방어 숙련 1점당 주문 공격력이이 4만큼 증가합니다. 15초 동안 지속됩니다.\n[q]\"번개 화살로 적 10명을 처치하면 새로운 능력을 배웁니다.\""},
[206387] = {name = "[q2]카자릭 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]장갑에 용암 폭발 룬을 새깁니다.\n\n\n대상에게 녹아내리는 용암을 날려 [469 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]에서 [605 / 100 * (7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60)]의 화염 피해를 입힙니다. 대상에 화염 충격 효과가 걸려 있으면 치명타로 적중합니다.\n[q]\"용암으로 피해를 5번 받으면 새로운 능력을 배웁니다. (용암으로 받는 피해 감소)\""},
[206388] = {name = "[q2]유황 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]장갑에 용암 작열 룬을 새깁니다.\n\n\n전방 부채꼴 범위 내의 적 최대 10명을 강타하여 [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 72 / 100 + 5 / 100 * 전투력]에서 [(7.583798 + 0.471881 * 60 + 0.036599 * 60 * 60) * 108 / 100 + 5 / 100 * 전투력]의 화염 피해를 입힙니다. 이 능력은 높은 위협 수준을 생성합니다. 화염 충격의 주기적인 피해가 10%의 확률로 용암 작열의 재사용 대기시간을 초기화합니다.\n[q]\"대지 충격으로 적 10명을 처치하면 새로운 능력을 배웁니다.\""},
[206389] = {name = "[q2]유황석 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]허리띠에 불꽃 회오리 룬을 새깁니다.\n\n\n불꽃 회오리 토템 주문이 불꽃 회오리로 대체됩니다. 불꽃 회오리 시전 시 현재 활성화된 불의 토템이 자신의 위치에 피해를 발산합니다.\n[q]\"대지의 무기로 적을 25번 공격하면 새로운 능력을 배웁니다.\""},
[206390] = {name = "[q2]이흐티야 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]장갑에 물의 보호막 룬을 새깁니다.\n\n\n3개의 물방울이 시전자의 주위에 머무르며 5초마다 최대 마나의 1%를 회복합니다. 만약 시전자가 주문이나 근접 또는 원거리 공격에 적중 당하면 시전자는 물방울로부터 최대 마나의 4%를 흡수합니다. 매번 마나를 흡수할 때마다 물방울이 하나씩 사라집니다. 물방울이 하나 사라지면 다른 물방울이 효력을 발휘하기까지 일정 시간이 필요합니다. 10분 동안 지속됩니다. 주술사의 보호막은 동시에 하나만 유지할 수 있습니다.\n[q]\"대지의 무기로 적을 25번 공격하면 새로운 능력을 배웁니다.\""},
[206391] = {name = "[q2]삭망의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n요구 레벨 3\n[q2]팔보호구에 성난 해일 룬을 새깁니다.\n\n\n아군 대상의 생명력을 [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]에서 [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]만큼 치유하고, 추가로 15초에 걸쳐 [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]의 생명력을 회복시킵니다. 15초 안에 주 대상에게 연쇄 치유 시전 시 연쇄 치유의 치유량이 25%만큼 증가합니다. 추가로 이 주문은 고대의 각성을 발동시킵니다.\n[q]\"대지의 무기로 적을 25번 공격하면 새로운 능력을 배웁니다.\""},
[206466] = {name = "초원 왕관", additional_info = "[q2]사용 효과: 평원의 영혼을 깨웁니다."},
[206469] = {name = "초원꽃", additional_info = "직업: 드루이드\n[q2]사용 효과: 초원꽃 3개를 결합하여 왕관을 만듭니다."},
[206954] = {name = "[q2]곰의 분노 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n[q2]장갑에 짓이기기 룬을 새깁니다.\n\n\n대상을 짓이겨 일반 공격력의 160%에 해당하는 피해를 입히고 1분 동안 출혈 효과 및 칼날 발톱으로 받는 피해를 30%만큼 추가로 증가시킵니다. 이 능력은 할퀴기 및 후려치기와 관련된 모든 이로운 효과를 적용 및 발동시킵니다.\n\n 짓이기기(곰)를 대상에게 적중시키면 ( 60 * 5)|1을;를; 넘는 방어 숙련 1점당 전투력이 4만큼 증가합니다. 15초 동안 지속됩니다.\n[q]\"곰 변신 상태에서 50 이상의 분노를 보유한 상태로 60초 동안 유지하면 새로운 능력을 배웁니다.\""},
[206963] = {name = "[q2]자연의 잠재력의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]가슴보호구 또는 로브에 살아있는 씨앗 룬을 새깁니다.\n\n\n비주기적인 치유 주문이 극대화 효과를 발휘하면 대상에게 치유량의 50%에 해당하는 생명력을 회복시키는 살아있는 씨앗을 심습니다. 살아있는 씨앗은 다음에 대상이 피해를 받거나 비주기적인 치유를 받으면 피어납니다. 15초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206966] = {name = "사티로스풀 구근", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"침입종 식물의 묘목입니다.\""},
[206970] = {name = "[q2]생명의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]바지에 피어나는 생명 룬을 새깁니다.\n\n회복 및 피어나는 생명의 전역 재사용 대기시간이 0.5초만큼 감소하고 피어나는 생명 능력을 얻습니다.\n\n\n7초에 걸쳐 대상의 생명력을 [4 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]만큼 회복시킵니다. 피어나는 생명의 지속시간이 다하거나 무효화되면 대상은 그 즉시 [57 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]의 생명력을 회복하고 드루이드는 주문 시전에 소모한 자원의 절반을 회복합니다. 이 효과는 같은 대상에 대해 3번까지 중복될 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206975] = {name = "유물 보관함 열쇠", additional_info = "고유 아이템\n[q]\"유물 보관함을 열 수 있습니다.\""},
[206985] = {name = "[q2]우두머리의 메아리", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n요구 레벨 3\n[q2]장화에 우두머리의 영혼 룬을 새깁니다.\n\n\n대상에게 늑대 우두머리의 영혼을 주입하여 30분 동안 생성되는 모든 위협 수준을 45%만큼 증가시킵니다. 한 번에 하나의 대상에만 영향을 줍니다. 자신이 아닌 다른 대상에게 시전하면 주술사는 충직한 수하 효과를 얻어 30분 동안 물리 공격력이 5%만큼 증가하고 모든 위협 생성 수준이 30%만큼 감소합니다. 우두머리의 영혼과 충직한 수하 효과를 동시에 보유하는 것은 불가능합니다.\n[q]\"새로운 능력을 배웁니다.\""},
[206989] = {name = "[q2]태양의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장갑에 태양섬광 룬을 새깁니다.\n\n\n적을 불태워 [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]에서 [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 자연 피해를 입히고 12초에 걸쳐 [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 추가 자연 피해를 입힙니다.\n\n 추가로 곰 변신 또는 표범 변신 상태일 때 태양 섬광 능력을 얻고, 달빛 섬광이 태양 섬광 (곰) 또는 태양섬광 (표범)으로 대체됩니다. 이 주문은 달빛 섬광과 관련된 모든 이로운 효과를 적용 및 발동시킵니다.\n\n 태양섬광 (곰)\n적을 불태워 [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]에서 [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 자연 피해를 입히고 12초에 걸쳐 [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 추가 자연 피해를 입힙니다.\n\n 태양섬광 (표범)\n적을 불태워 [130 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]에서 [152 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 자연 피해를 입히고 12초에 걸쳐 [65 * 4 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 추가 자연 피해를 입힙니다. 연계 점수 1점을 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[206992] = {name = "[q2]두개골 강타의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장갑에 두개골 강타 룬을 새깁니다.\n\n\n13미터 내의 대상에게 돌진한 후 두개골을 강타하여 주문 시전을 방해하고, 2초 동안 같은 계열의 주문을 시전하지 못하게 합니다. 야성의 돌진과 재사용 대기시간을 공유합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
