[208224] = {name = "수습흑마법사의 기록", additional_info = "획득 시 귀속\n고유 아이템\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[208414] = {name = "[q2]달의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n[q2]가슴보호구 또는 로브에 스톰레이지의 격노 룬을 새깁니다.\n\n\n천벌의 마나 소모량이 100%만큼 감소합니다. 천벌로 피해를 입힐 때마다 12%의 확률로 다음 15초 동안 시전하는 치유의 손길이 변신 상태에 상관없이 즉시 시전됩니다. 생명의 나무 변신 상태일 때 천벌을 시전할 수 있습니다.\n[q]\"달빛 섬광에 영향을 받는 몬스터 6마리를 처치한 다음 사용하면 새로운 능력을 배웁니다.\""},
[208425] = {name = "[q7]반짝이는 고풍스러운 자취", additional_info = "계정 귀속\n고유 아이템\n목\n정신력 +6\n[q2]사용 효과: 귀환석 위치|1으로;로; 귀환합니다. 귀환 장소를 변경하려면 여관주인과 대화하십시오. (1 시간 재사용 대기시간)"},
[208484] = {name = "[q3]햇살", additional_info = "획득 시 귀속\n고유 아이템\n{한{손} 장비}\n{공격력 10 - 14 } {속도 1.70}\n(초당 공격력 7.06)\n체력 +11\n정신력 +34\n암흑 저항력 +17"},
