[208612] = {name = "절단된 거미 머리", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"음울한 전리품입니다. 이 물건에 관심을 보일 만한 수집가가 있을지도 모릅니다...\""},
[208682] = {name = "버려진 무쇠턱 알", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"새로운 보금자리가 필요합니다.\""},
[208687] = {name = "[q2]가르기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]바지에 가르기 룬을 새깁니다.\n\n\n대상을 갈라 출혈을 일으켜, 15초에 걸쳐 [(9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) * 20 / 100 * 5]의 피해를 입히고 대상에게 부여된 기존 가르기 중첩 하나당 무기 공격력의 20%에 해당하는 추가 피해를 입힙니다. 위협 수준이 크게 증가합니다. 한 대상에게 최대 5번까지 중첩됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208689] = {name = "[q2]야성의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n[q2]바지에 야생의 포효 룬을 새깁니다.\n\n\n마무리 일격을 날려 물리 공격력을 30%만큼 증가시킵니다. 표범 변신 상태일 때 사용할 수 있습니다. 연계 점수 당 다음 시간 동안 지속됩니다.\n 연계 점수 1점: 14초\n 연계 점수 2점: 19초\n 연계 점수 3점: 24초\n 연계 점수 4점: 29초\n 연계 점수 5점: 34초\n[q]\"인간형 적에게 출혈 피해를 20번 입힌 후, 이 우상을 사용하면 새로운 능력을 배웁니다.\""},
[208701] = {name = "[q2]야수 숙련의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n{[q2]가슴보호구 또는 로브에 야수 숙련 룬을 새깁니다.\n\n\n야수의 공격력}과 생명력이 15%만큼, 집중 회복 {속도가 50%만큼 증가합니다. 추가로 야수의 포효가 대상을 도발하여 3초 동안 야수 자신을 공격하게 만듭니다.}\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208739] = {name = "호드 전쟁 깃발", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q]\"적의 영토에 꽂으세요.\""},
[208741] = {name = "[q2]끝없는 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]투구에 끝없는 분노 룬을 새깁니다.\n\n\n모든 피해를 입힐 때 생성되는 분노가 25%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208743] = {name = "탐욕의 영혼", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사"},
[208744] = {name = "[q2]어둠의 화살의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장갑에 연발 어둠의 화살 룬을 새깁니다.\n\n\n어둠의 화살이 10미터 내에 있는 최대 5명의 추가 적을 공격합니다. 공격력은 30%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208749] = {name = "나무옹이 은닉처 열쇠", additional_info = "고유 아이템\n[q]\"손잡이에 나뭇가지가 조잡하게 새겨져 있습니다.\""},
[208750] = {name = "[q2]정신 집중의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]가슴보호구 또는 로브에 역술의 대가 룬을 새깁니다.\n\n\n생명력 흡수가 더는 정신을 집중하지 않습니다. 15초 동안 지속되며 15초의 재사용 대기시간이 적용됩니다. 또한 마나 소모량이 100%만큼 증가하며, 피해를 입힐 때마다 50%만큼 추가로 생명력을 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208753] = {name = "[q2]주문 기록: 재생", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]가슴보호구 또는 로브에 재생 룬을 새깁니다.\n\n\n대상을 3초에 걸쳐 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 55 / 100 * 3]만큼 치유하고 30초 동안 시간의 봉화를 부여합니다.\n\n 시간의 봉화\n\n대상의 시공간 위치를 기록합니다. 시전자가 입히는 모든 비전 피해의 70%가 시간의 치유로 전환되어 현재 시간의 봉화가 부여된 각 대상을 치유합니다. 대상이 자신일 경우 치유량이 50%만큼 감소합니다. 또한 여러 대상을 공격하는 비전 주문으로 피해를 입힐 경우에는 치유량이 80%만큼 감소합니다.\n[q]\"Teaches you a new Engraving ability.\""},
[208754] = {name = "[q2]주문 기록: 생재", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[208758] = {name = "[q2]대지의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]바지에 대지의 길 룬을 새깁니다.\n\n\n주무기에 대지의 무기가 활성화되어 있고 방패를 장착 중일 경우 위협 수준이 65%만큼, 생명력이 25%만큼 증가합니다. 받는 피해는 10%만큼, 근접 공격 치명타에 적중당할 확률도 6%만큼 감소합니다. 또한 대지 충격 시전 시 대상을 도발해 자신을 공격하게 하고 다른 충격 주문과 재사용 대기시간이 분리됩니다. 사정거리가 근접 공격 범위로 감소합니다. 단, 번개 화살, 연쇄 번개, 연쇄 치유, 치유의 물결, 용암 폭발 주문의 사정거리가 20미터만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208760] = {name = "공터 왕관", additional_info = "[q2]사용 효과: 평원의 영혼을 깨웁니다."},
[208764] = {name = "[q2]정신의 룬", additional_info = "고유 아이템\n직업: 사제\n[q2]허리띠에 정신의 쐐기 룬을 새깁니다.\n\n\n대상을 강타하여 [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]에서 [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]의 암흑냉기 피해를 입힙니다. 또한 다음 정신 분열의 치명타 및 극대화율이 30%만큼 증가합니다. 최대 3번까지 중첩됩니다."},
[208765] = {name = "[q2]도움의 손길", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q]\"구세주에게는 손을 펼쳐줄 것입니다.\""},
[208766] = {name = "[q2]도움의 손길", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q]\"활짝 펼쳐진 손입니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[208767] = {name = "[q2]복원의 룬", additional_info = "고유 아이템\n직업: 사제\n[q2]바지에 회복의 기원 룬을 새깁니다.\n\n\n대상에 마력을 불어 넣어 다음에 피해를 입거나 치유 효과를 받을 시 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 74 / 100]의 생명력을 회복하도록 합니다. 생명력이 회복될 때 20미터 반경 내의 파티원 혹은 공격대원에게로 회복의 기원이 전달됩니다. 최대 5번까지 이동하며 매 이동 시마다 효과는 30초 동안 지속됩니다. 이 주문은 동시에 한 대상에게만 걸 수 있습니다.\n[q]\"룬조각술 능력을 배웁니다.\""},
[208768] = {name = "해적의 성냥갑", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q]\"가연성 물질에 불을 붙이는 데 쓰입니다.\""},
[208771] = {name = "[q2]칼춤의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]바지에 칼춤 룬을 새깁니다.\n\n\n마무리 일격을 날려 무기 막기 확률을 10%만큼, ( 60 * 5)|1을;를; 넘는 방어 숙련 1점당 전투력을 4만큼 증가시킵니다. 연계 점수당 다음 시간 동안 지속됩니다.\n\n 연계 점수 1점: 14초\n 연계 점수 2점: 18초\n 연계 점수 3점: 22초\n 연계 점수 4점: 26초\n 연계 점수 5점: 30초\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208772] = {name = "[q2]사브르 베기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장갑에 사브르 베기 룬을 새깁니다.\n\n\n흉포하게 적을 베어 대상에게 무기 공격력의 100%에 해당하는 피해를 입히고, 출혈을 일으켜 12초 동안 매 2초마다 (전투력 * 5 / 100)의 피해를 입힙니다. 최대 3번까지 중첩됩니다. 중첩 하나당 사브르 베기와 사악한 일격의 공격력이 50%만큼 증가합니다. 연계 점수 1점을 생성합니다.\n\n 사브르 베기는 사악한 일격으로 발동하거나 사악한 일격의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208773] = {name = "낚시용 작살", additional_info = "획득 시 귀속\n직업: 전사 , 사냥꾼\n[q2]사용 효과: 대상에게 작살을 던집니다. 사정거리는 40미터입니다.\n[q]\"전도유망한 상어 사냥꾼의 필수품입니다.\""},
[208777] = {name = "[q2]저격수의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]바지에 저격 훈련 룬을 새깁니다.\n\n\n지난 2초 동안 가만히 있었다면 사격 능력의 치명타 적중률이 2%만큼 증가합니다. 1초마다 중첩을 얻으며, 최대 5번까지 중첩됩니다. 2번 이상 중첩되면 조준 사격이 즉시 시전됩니다. 이동 시 1초마다 중첩 1개를 잃습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208778] = {name = "[q2]속전속결의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장갑에 속전속결 룬을 새깁니다.\n\n\n즉시 양손 무기로 무모한 근접 공격을 날려 (전투력 * 30 / 100)에서 (전투력 * 40 / 100)의 물리 피해를 입힙니다. 이 능력은 영웅의 일격과 관련된 모든 이로운 효과를 적용 및 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208799] = {name = "[q2]주문 기록: 살아있는 폭탄", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]장갑에 살아있는 폭탄 룬을 새깁니다.\n\n\n대상은 살아있는 폭탄이 되어 12초에 걸쳐 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 85 / 100 * 4]의 화염 피해를 입습니다. 12초 후, 혹은 주문이 무효화되면 대상은 폭발하여 10미터 반경 내에 있는 모든 적에게 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 171 / 100]의 화염 피해를 입힙니다.\n\n 살아있는 폭탄은 불태우기로 발동하거나 불태우기를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[208800] = {name = "박스탄: 파괴 마법에 관하여", additional_info = "고유 아이템\n[q]\"저명한 고블린 마법사의 저작물입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[208823] = {name = "공물 주화", additional_info = "획득 시 귀속\n직업: 사제\n[q2]사용 효과: 주위 샘에 던지고 소원을 빕니다."},
[208828] = {name = "깨진 서약의 기억", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 정신의 쐐기 룬을 새깁니다.\n\n\n대상을 강타하여 [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]에서 [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]의 암흑냉기 피해를 입힙니다. 또한 다음 정신 분열의 치명타 및 극대화율이 30%만큼 증가합니다. 최대 3번까지 중첩됩니다.\n[q2]사용 효과: 기억에 집중하여 새로운 주문을 배웁니다. 아제로스의 영적인 수수께끼에 관해 명상하여 정신을 맑게 정리해야 합니다."},
[208833] = {name = "사악한 파이", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q]\"사악한 기운이 감도는 빵입니다.\""},
[208838] = {name = "[q2]검은무쇠 금고", additional_info = "획득 시 귀속\n고유 아이템\n[q0]잠겨 있음\n 자물쇠 열기 (1) 필요"},
[208843] = {name = "전투 토템", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]사용 효과: 타우렌에게 결투를 신청합니다.\n[q]\"호드 구성원 사이에서는 적의의 상징으로 통합니다.\""},
[208847] = {name = "해골모양 정동석", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q]\"제대로 충격을 가하면 내용물을 확인할 수 있을 것입니다.\""},
[208848] = {name = "금이 간 해골모양 정동석", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q]\"쩍 열린 정동석입니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[208849] = {name = "[q2]축복의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n[q2]가슴보호구에 신성화된 땅 룬을 새깁니다.\n\n\n신성화가 추가로 효과 범위 내의 파티원을 입힌 피해의 200%만큼 치유합니다.\n[q]\"서로 다른 플레이어 5명에게 축복을 내리면 새로운 능력을 배웁니다.\""},
[208851] = {name = "[q2]정의의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n[q2]장갑에 집행의 손길 룬을 새깁니다.\n\n\n적을 도발하여 자신을 공격하도록 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다.\n\n 이 능력을 배웠다면 정의의 격노의 위협 수준 증가량이 80%로 증가합니다. 또한 정의의 격노가 받는 치유 효과의 25%만큼 마나를 회복시킵니다. 추가로 정의의 격노가 활성화된 동안 생명력이 35% 미만으로 떨어질 수 있는 공격을 받으면 그 공격으로 받는 피해가 20%만큼 감소합니다. 취소할 때까지 정의의 격노가 지속됩니다.\n[q]\"심판의 망치로 기절한 적 10명을 처치하면 새로운 능력을 배웁니다.\""},
[208853] = {name = "[q2]주문 기록: 두뇌 빙결", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n각인술\n(1) 필요\n[q2]장화에 두뇌 빙결 룬을 새깁니다.\n\n\n빙결 효과가 있는 냉기 주문 시전 시 20%의 확률로 다음 화염구와 비전냉기 화살, 재앙불꽃 화살, 얼음불꽃 화살 주문이 마나를 소비하지 않고 즉시 시전됩니다.\n[q]\"룬조각술 능력을 배웁니다.\""},
[208854] = {name = "[q2]반쯤 씹힌 주문 기록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다.\n[q]\"트로그 주술사들은 문자 그대로 게걸스러운 독서가랍니다.\""},
[208855] = {name = "무지개날개다랑어 미끼", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]사용 효과: 대상에게 먹이를 줍니다.\n[q]\"호수 괴물이 정말 사족을 못 쓰는 간식입니다.\""},
[208860] = {name = "놈리건의 루미: 작품 모음집", additional_info = "고유 아이템\n[q]\"저명한 노움 마법사의 저작물입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209027] = {name = "게 간식", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼 , 드루이드\n[q2]사용 효과: 대상에게 간식을 줍니다.\n[q]\"펄볼그가 새끼 모래톱게를 잡을 때 사용합니다.\""},
[209028] = {name = "[q2]주문 기록: 는살있아 탄폭", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[209029] = {name = "에밀리의 전언", additional_info = "획득 시 귀속\n직업: 도적\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[209030] = {name = "장비 은닉처 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적"},
[209031] = {name = "은밀한 편지 봉투", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]<열려면 마우스 오른쪽 클릭>"},
[209041] = {name = "마법 호박 씨앗", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]사용 효과: 호박 씨앗을 심습니다.\n[q]\"특별한 토양과 영양분을 줘야 자라납니다.\""},
[209042] = {name = "생선 뼛가루", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"고약한 냄새가 진동하지만 영양분이 풍부합니다. 훌륭한 비료입니다.\""},
[209043] = {name = "비옥한 토양 표본", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"흙에 해박한 사람이 채취했습니다.\""},
[209045] = {name = "바다의 영혼", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 흑마법사"},
[209047] = {name = "옹이진 작살", additional_info = "획득 시 귀속\n직업: 전사 , 사냥꾼\n[q2]사용 효과: 대상에게 작살을 던집니다. 사정거리는 40미터입니다.\n[q]\"가장 큰 상어의 피로만 이 무기의 갈증을 채워줄 수 있습니다.\""},
[209056] = {name = "예비용 수확자 부품", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사 , 흑마법사\n[q2]사용 효과: 예비용 수확자 부품을 정령 핵과 결합하여 시험용 기관을 만듭니다."},
[209057] = {name = "시험용 기관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사 , 흑마법사\n[q2]사용 효과: 시험용 허수아비골렘 수확기에 설치합니다."},
[209058] = {name = "정령 핵", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사 , 흑마법사\n[q2]사용 효과: 예비용 수확자 부품을 정령 핵과 결합하여 시험용 기관을 만듭니다."},
[209059] = {name = "뿔엄니멧돼지 허벅지 고기", additional_info = "고유 아이템\n직업: 사냥꾼\n[q2]사용 효과: 코요테 서식지 근처에 미끼를 놓습니다."},
[209418] = {name = "[q3]아다만타이트 거북껍질 갑옷", additional_info = "획득 시 귀속\n{가슴} {사슬}\n[q2]방어도 338\n체력 +11\n내구도 120 / 120\n요구 레벨 25"},
[209420] = {name = "[q2]아가미의 파멸", additional_info = "획득 시 귀속\n{주장비} {둔기}\n{공격력 18 - 34 } {속도 2.60}\n(초당 공격력 10.00)\n내구도 60 / 60\n직업: 전사\n요구 레벨 14\n[q]\"죽은 멀록의 영혼을 수확한다는 전설이 있는 마법 무기입니다.\""},
[209421] = {name = "[q3]아쿠아니스의 장식끈", additional_info = "획득 시 귀속\n{허리} {가죽}\n방어도 58\n민첩성 +7\n체력 +4\n정신력 +7\n내구도 35 / 35\n요구 레벨 25"},
[209422] = {name = "[q3]만조 목장식", additional_info = "획득 시 귀속\n목\n힘 +7\n민첩성 +4\n요구 레벨 25"},
[209423] = {name = "[q3]흐르는 목도리", additional_info = "획득 시 귀속\n등\n방어도 24\n지능 +6\n정신력 +6\n요구 레벨 25"},
