[209844] = {name = "달라란 소식지 23호", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"키린 토의 비전 마법 연구 자료입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209845] = {name = "마술과 비술", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"조작과 기만에 관련된 주문 모음집입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209846] = {name = "꿈꾸는 자의 비밀", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"에메랄드의 꿈을 관찰하고 그에 대한 통찰을 기록한 문서입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209847] = {name = "신비한 체계 설명서", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"고블린 기술과 관련된 문제 해결법을 조잡하게 정리해 놓은 문서입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209848] = {name = "고아즈 두루마리", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"잊힌 티탄 문자로 쓰였습니다. 어쨌든 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209849] = {name = "범죄에 맞서는 해부학", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"학자 크라스티노브가 집필한 저서입니다. 도서관 수집품으로는 좀 의문이 드는 물품입니다.\""},
[209850] = {name = "마술사 왕의 룬", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"강대한 드레노어 오우거 제국 유물입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209851] = {name = "대지의 격노", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"그림토템 부족이 철두철미하게 지키던 주술의 비밀입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[209852] = {name = "[q2]살상 명령의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]바지에 마무리 사격 룬을 새깁니다.\n\n\n부상당한 대상을 마무리하는 시도를 합니다. 원거리 공격을 가해 무기 공격력의 100%에 [587 / 100 * 100 / 100 * (2.976264 + 0.641066 * 60 + 0.022519 * 60 * 60)]의 추가 피해를 입힙니다. 마무리 사격은 최소 범위가 없습니다. 생명력이 20% 미만인 적에게 사용할 경우 마무리 사격의 재사용 대기시간이 초기화됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[209872] = {name = "용사냥꾼의 투구", additional_info = "획득 시 귀속\n고유 아이템"},
[209873] = {name = "용사냥꾼의 방패", additional_info = "획득 시 귀속\n고유 아이템"},
[209874] = {name = "용사냥꾼의 창", additional_info = "획득 시 귀속\n고유 아이템"},
[210015] = {name = "[q2]분노의 강타의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]가슴보호구에 분노의 강타 룬을 새깁니다.\n\n\n흉포한 강타를 날려 무기 공격력의 115%에 해당하는 피해를 입힙니다. 단, 격노, 광전사의 격노 또는 피의 분노가 활성화된 상태일 때만 사용할 수 있습니다. 격노, 광전사의 격노, 피의 분노가 활성화된 동안 다른 근접 능력을 사용할 때마다 분노의 강타의 남은 재사용 대기시간이 1초만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210026] = {name = "세 번째 올빼미의 상징", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"바다의 영역을 정복했습니다.\""},
[210043] = {name = "두 번째 올빼미의 상징", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"아곤의 영혼이 마침내 안식에 들었습니다.\""},
[210044] = {name = "첫 번째 올빼미의 상징", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q]\"진정한 수호자의 징표입니다.\""},
[210045] = {name = "망령잎", additional_info = "퀘스트 아이템"},
[210053] = {name = "광포한 늑대 발", additional_info = "퀘스트 아이템"},
[210055] = {name = "힐스브래드 주민의 유골", additional_info = "퀘스트 아이템"},
[210056] = {name = "깨어있는 죽음의 물약", additional_info = "퀘스트 아이템"},
[210080] = {name = "부두 공물", additional_info = "퀘스트 아이템\n고유 아이템"},
[210137] = {name = "[q2]급속 성장의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장갑에 급속 성장 룬을 새깁니다.\n\n\n7초에 걸쳐 대상 플레이어의 43.5미터 내에 있는 모든 파티원의 생명력을 [17 / 100 * 7 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]만큼 회복시킵니다. 처음엔 생명력을 빠르게 회복시키다가 시간이 지날수록 점점 느려집니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210138] = {name = "검은무쇠 군수품", additional_info = nil},
[210146] = {name = "벌목기 초충전 장치", additional_info = nil},
[210147] = {name = "벌목기 자동 회수 장치", additional_info = "[q2]사용 효과: 벌목기 잔해에서 쓸 만한 부품을 수습합니다."},
[210177] = {name = "아테릭: 비전의 신비에 관하여", additional_info = "고유 아이템\n[q]\"저명한 키린 토 대마법사의 저작물입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[210178] = {name = "[q2]설계도: 벌목기 자동 회수 장치", additional_info = "기계공학 (135) 필요"},
[210179] = {name = "[q2]주문 기록: 만탁 살화", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 주문 기록을 번역하여 새로운 룬조각술 제작법을 얻습니다. 작성자의 속기를 파악할 수 있는 참고서가 필요합니다."},
[210183] = {name = "젤토스의 뿔", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"낮고 음산한 선율을 발산합니다.\""},
[210186] = {name = "돌파용 폭탄", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 육중한 관문을 고블린의 방식대로 엽니다!"},
[210187] = {name = "투자개발회사 주문 의뢰서", additional_info = "획득 시 귀속\n고유 아이템"},
[210188] = {name = "[q0]찢어진 주문 의뢰서", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"전투 중 손상된 것으로 보입니다.\""},
[210195] = {name = "[q2]허술한 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n요구 레벨 10\n[q2]사용 효과: 달, 에메랄드의 꿈, 자연의 힘이 조화를 이루게 하여 새로운 능력을 배웁니다."},
[210209] = {name = "쌍둥이 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적"},
[210210] = {name = "[q0]그리즈 방위 산업 설립자 증서", additional_info = "[q]\"작은 글씨로 이 증서에는 어떠한 주식 가치도 없으며 합법적인 권리가 아님을 분명히 명시하고 있습니다. 이 부분만 엄지로 가리면 상인이 사줄 겁니다.\""},
[210212] = {name = "형제의 반 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 형제와 자매 반 열쇠를 결합합니다."},
[210213] = {name = "자매의 반 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 형제와 자매 반 열쇠를 결합합니다."},
[210229] = {name = "[q2]절단의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장갑에 절단 룬을 새깁니다.\n\n\n양쪽 손에 장착한 무기로 적을 즉시 공격하여 각 무기마다 무기 공격력의 95%에 [100 / 100 * (5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 95 / 100]의 추가 피해를 입힙니다. 독에 걸린 대상을 가격할 시 공격력이 20%만큼 증가합니다. 연계 점수 2점이 주어집니다.\n\n 절단은 따로 명시되지 않은 이상 기습으로 발동하거나 기습의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210250] = {name = "각인된 금반지", additional_info = "획득 시 귀속\n고유 아이템\n손가락\n[q]\"다음과 같은 각인이 새겨져 있습니다. \"두 __ 모두 __ 상태로 __ 조각상 __ 무릎을 __.\"\""},
[210251] = {name = "각인된 은반지", additional_info = "획득 시 귀속\n고유 아이템\n손가락\n[q]\"다음과 같은 각인이 새겨져 있습니다. \"__ 반지를 __ 착용한 __ 묘지 __ 앞에 __ 꿇어라.\"\""},
[210252] = {name = "[q2]독칼의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장갑에 극악무도 룬을 새깁니다.\n\n\n더는 대상의 배후에 있지 않아도 매복, 기습, 목조르기 능력을 사용할 수 있게 됩니다. 또한 기습 사용 시 15%의 확률로 다음 10초 동안 은신 상태가 아니어도 매복을 사용할 수 있게 됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210253] = {name = "[q2]부패 토템", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 원소의 정령을 불러냅니다.\n[q]\"전통적인 토템입니다. 다만... 흑마법으로 뒤틀려 갉아먹힌 상태라 정기와 교감하는 자들은 알아볼 수 없을 정도입니다.\""},
[210322] = {name = "[q2]맹독의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]바지에 독살 룬을 새깁니다.\n\n\n적에게 마무리 일격을 날립니다. 대상에 걸린 맹독에 따라 즉시 독 피해를 입힙니다. 독살 공격 후 75%의 확률로 연계 점수당 1초에 추가로 1초 동안 순간 효과 독에 감염시킵니다. 각 연계 점수당 하나의 맹독을 활성화합니다.\n 맹독 1회: Â [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) + 전투력 * 0.072]의 피해\n 맹독 2회: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 2 + 전투력 * 0.144]의 피해\n 맹독 3회: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 3 + 전투력 * 0.216]의 피해\n 맹독 4회: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 4 + 전투력 * 0.288]의 피해\n 맹독 5회: [((5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 80 / 100) * 5 + 전투력 * 0.36]의 피해\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210323] = {name = "금고 조합", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q]\"0-4-5-1\""},
[210329] = {name = "힐스브래드 보물 지도", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q]\"강을 따라 북쪽으로 올라가 알터랙 산맥을 통과하라. 그대가 찾는 물건은 쏟아지는 급류 사이에 있다.\""},
[210330] = {name = "중요 정보", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"좋은 정보는 비싼 법이죠.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[210410] = {name = "민물 무쇠턱거북 미끼", additional_info = "직업: 사냥꾼\n[q2]사용 효과: 미끼를 던집니다. (5 분 재사용 대기시간)\n[q]\"물에 던져 거물을 유인할 수 있습니다!\""},
[210499] = {name = "버섯", additional_info = "[q2]사용 효과: 섭취 후 어떤 일이 벌어져도 본인의 책임입니다."},
[210500] = {name = "[q2]별의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]바지에 별빛쇄도 룬을 새깁니다.\n\n\n쇄도하는 항성의 마력을 발사해 [248 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)]에서 [304 / 100 * (9.183105 + 0.616405 * 1 + 0.028608 * 1)]의 비전 피해를 입히고 15초 동안 다음 1회 동안 시전하는 별빛 화살의 공격력이 80%만큼 증가합니다.\n\n 별빛쇄도는 천벌 또는 별빛 화살에 이롭거나, 해당 주문이 발동시키는 특성 및 효과 대부분이 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210534] = {name = "[q2]야생의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n[q2]가슴보호구 또는 로브에 야생의 강타 룬을 새깁니다.\n\n\n표범 변신, 곰 변신 또는 광포한 곰 변신 상태일 때 100미터 내 파티원 또는 공격대원이 좀 더 매섭게 전투를 수행합니다. 근접 공격이 적중할 때마다 20%으 확률로 공격자가 재차 공격을 가해 전투력의 20%에 해당하는 추가 피해를 입힙니다. 대상이 이미 질풍의 토템의 효과를 받는 경우 효과를 발휘하지 않습니다.\n[q]\"10개의 서로 다른 야수를 치유한 후 이 우상을 사용하면 새로운 능력을 배웁니다.\""},
[210568] = {name = "노후한 성물함", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"유물에서 흉험한 기운이 뿜어져 나옵니다.\""},
[210569] = {name = "[q2]채찍질의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]가슴보호구에 채찍질 룬을 새깁니다.\n\n\n물리 피해를 받아 분노를 생성할 때, 방어구를 착용하지 않은 것처럼 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210573] = {name = "[q2]불타는 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]바지에 분노 잠식 룬을 새깁니다.\n\n\n분노가 60 이상일 때 12초 동안 격노하고 격노 상태를 요구하는 능력을 활성화합니다. 추가로 격노 상태일 때는 소용돌이 사용 시 보조 무기로도 공격합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210589] = {name = "[q2]선조의 메아리", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]바지에 고대의 인도 룬을 새깁니다.\n\n\n다음 10초 동안 입히는 피해의 25%가 치유량으로 전환되어 주위에 있는 최대 3명의 파티원을 치유합니다. 또한 치유량의 100%는 피해량으로 전환되어 가장 최근 화염 충격을 시전한 대상에게 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210596] = {name = "[q2]코브라의 일격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]가슴보호구 또는 로브에 코브라의 일격 룬을 새깁니다.\n\n\n사격 능력 및 일격 능력, 살쾡이의 이빨이 치명타로 적중하면 다음 2회 동안 사용하는 야수의 특수 공격이 치명타로 적중합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210653] = {name = "[q2]맹 고슈의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]허리띠에 맹고쉬 룬을 새깁니다.\n\n\n즉시 보조 무기로 대상을 공격해 일반 보조 무기 공격력에 해당하는 피해를 입히고 5초 동안 혹은 무기 막기에 성공할 때까지 무기 막기 확률이 100%만큼 증가합니다. 맹고쉬 사용 후 20초 동안 사악한 일격의 기력 소모량이 20만큼 감소하고 위협 수준을 50%만큼 추가로 생성하며, 충격 완화 중첩을 부여합니다. 사악한 일격과 절개가 50%의 추가 피해를 입힙니다. 연계 점수 1점을 생성합니다.\n\n 맹고쉬는 사악한 일격으로 발동하거나 사악한 일격의 효과를 변경하는 모든 특성 및 효과가 적용됩니다. 맹고쉬의 효과는 맹고쉬의 자원 소모량을 완화하거나 강화하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210654] = {name = "[q2]주문 기록: 시간 되돌리기", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]팔보호구에 시간 되돌리기 룬을 새깁니다.\n\n\n시간의 봉화가 부여된 현재 대상이 즉시 지난 5초 동안 받는 모든 피해를 흡수합니다. 5초 전에 시간의 봉화가 부여되어 있지 않았던 대상에게는 효과를 발휘하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210655] = {name = "[q2]주문 기록: 간시 시되리돌", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[210665] = {name = "휘몰아치는 분노의 티끌", additional_info = "획득 시 귀속\n고유 아이템"},
[210667] = {name = "지옥불 분노의 티끌", additional_info = "획득 시 귀속\n고유 아이템"},
[210668] = {name = "전율하는 분노의 티끌", additional_info = "획득 시 귀속\n고유 아이템"},
[210696] = {name = "[q2]부식의 파멸", additional_info = "획득 시 귀속\n{주장비} {검}\n{공격력 18 - 34 } {속도 2.60}\n(초당 공격력 10.00)\n내구도 60 / 60\n직업: 전사\n요구 레벨 14\n[q]\"피로 점철된 칼날은 더는 빛을 발산하지 않습니다. 다만 경고를 전할 뿐...\""},
[210708] = {name = "응축된 후회의 비약", additional_info = "요구 레벨 20\n[q2]사용 효과: 복용 시 필멸자의 세계에 아직 볼 일이 남아있는 존재의 시체와 대화할 수 있도록 합니다. 추가로 소화불량이 낫습니다. (3 초 재사용 대기시간)"},
[210709] = {name = "[q2]조제법: 응축된 후회의 비약", additional_info = "연금술 (90) 필요\n[q2]사용 효과: 응축된 후회의 비약 조제하는 법을 배웁니다.\n응축된 후회의 비약\n요구 레벨 20\n[q2]사용 효과: 복용 시 필멸자의 세계에 아직 볼 일이 남아있는 존재의 시체와 대화할 수 있도록 합니다. 추가로 소화불량이 낫습니다. (3 초 재사용 대기시간)\n갈래물풀 (5), 가연 약병 , 무덤이끼 (5), 영혼 가루 필요"},
[210712] = {name = "통찰의 비약", additional_info = "획득 시 귀속\n[q2]사용 효과: 제네우의 화톳불에서 환영을 봅니다."},
[210713] = {name = "괴로워하는 영혼", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 피의 공물을 바쳐 괴로워하는 영혼을 해방합니다."},
[210724] = {name = "히르제크의 지팡이", additional_info = "획득 시 귀속"},
[210741] = {name = "[q3]전자동 고철 압축기", additional_info = "획득 시 귀속\n{양손 장비} {둔기}\n{공격력 53 - 85 } {속도 2.00}\n(초당 공격력 34.50)\n힘 +22\n민첩성 +8\n내구도 100 / 100\n직업: 성기사 , 주술사 , 드루이드\n요구 레벨 40\n[q2]착용 효과: 표범, 곰, 광포한 곰 변신 상태일 때 전투력이 69만큼 증가합니다.\n[q2]사용 효과: 30초 동안 공격 속도가 50%만큼 증가합니다. 55 레벨을 넘는 캐릭터에게는 영향을 주지 않습니다. (3 분 재사용 대기시간)\n[q]\"올해 모델은 여러 부분이 개선되어 사용성이 향상되었습니다.\""},
[210746] = {name = "[q2]대지의 보호막의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]바지에 대지의 보호막 룬을 새깁니다.\n\n\n대상을 대지의 보호막으로 감싸 피해를 입을 시 정신 집중이나 주문 시전이 지연되는 시간이 30%만큼 감소하게 하고 보호막이 걸린 대상이 공격을 받을 시 [28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]의 생명력을 회복하도록 합니다. 이 효과는 몇초마다 한 번씩만 발휘됩니다. 9회 사용 가능하며 10분 동안 지속됩니다. 대지의 보호막은 한 번에 한 대상에게만 걸 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210763] = {name = "알텍의 가지", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"부서진 힘의 파편입니다. 한때 위대한 무기의 일부였던 듯합니다.\""},
[210765] = {name = "데즈의 보주", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"화염과 흑마법이 보주를 통해 휘몰아치고 있습니다. 매혹스럽지만 깊은 우려를 자아냅니다. 한때 위대한 무기의 일부였던 듯합니다.\""},
[210771] = {name = "[q2]잘못 놓인 보급품: 구리 주괴", additional_info = "획득 시 귀속\n고유 아이템: [Waylaid Shipment] (12)\n[q2]사용 효과: 구리 주괴 20개를 추가하여 화물을 완성합니다."},
[210772] = {name = "[q2]보급품 화물: 구리 주괴", additional_info = "획득 시 귀속\n고유 아이템: [Supply Shipment] (1)\n[q]\"병참장교에게 전달하면 막대한 보상을 받을 수 있습니다.\""},
[210773] = {name = "[q3]2차 대전쟁의 어깨덧옷", additional_info = "착용 시 귀속\n{어깨} {사슬}\n방어도 163\n체력 +8\n내구도 70 / 70\n요구 레벨 25\n[q2]착용 효과: 신성 계열의 주문과 효과의 공격력이 최대 11만큼 증가합니다."},
[210779] = {name = "[q2]도면: 2차 대전쟁의 어깨덧옷", additional_info = "획득 시 귀속\n대장기술 (150) 필요\n[q2]사용 효과: 2차 대전쟁의 어깨덧옷 만드는 법을 배웁니다.\n[q3]2차 대전쟁의 어깨덧옷\n착용 시 귀속\n{어깨} {사슬}\n방어도 163\n체력 +8\n내구도 70 / 70\n요구 레벨 25\n[q2]착용 효과: 신성 계열의 주문과 효과의 공격력이 최대 11만큼 증가합니다.\n청동 주괴 (20), 태마노 (2), 저급 월장석 (2), 오색 진주 (2), 은괴 (4) 필요"},
[210781] = {name = "[q3]불사조 손목띠", additional_info = "착용 시 귀속\n{손목} {천}\n방어도 21\n내구도 30 / 30\n요구 레벨 25\n[q2]착용 효과: 화염 계열의 주문과 효과의 공격력이 최대 13만큼 증가합니다."},
[210794] = {name = "[q4]변화무쌍한 은미늘 흉갑", additional_info = "획득 시 귀속\n고유 장착 아이템: [Void-Touched] (1)\n{가슴} {사슬}\n방어도 238\n힘 +12\n체력 +5\n내구도 145 / 145\n요구 레벨 25\n대장기술 (100) 필요\n[q2]착용 효과: 이 물품은 순수한 공허의 힘이 주입되어 있습니다. 착용자가 공격받으면 이 아이템이 높은 확률로 끔찍한 저주를 일으켜 15초 동안 공격자가 받는 모든 피해를 증가시킵니다. (효과 발동 확률: 25%)\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다."},
[210795] = {name = "[q4]다른 차원의 거미줄 장화", additional_info = "획득 시 귀속\n고유 장착 아이템: [Void-Touched] (1)\n{발} {천}\n방어도 35\n체력 +5\n지능 +5\n정신력 +6\n내구도 50 / 50\n요구 레벨 25\n재봉술 (100) 필요\n[q2]사용 효과: 일시적으로 다른 차원에 들어가 즉시 위협 수준을 완화하고 6초초 동안 받는 모든 피해가 30%만큼 감소합니다. (10 분 재사용 대기시간)\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 7만큼 증가합니다.\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다."},
[210811] = {name = "[q2]태고의 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]바지에 상급 늑대 정령 룬을 새깁니다.\n\n\n실내에서 늑대 정령 능력을 사용할 수 있도록 합니다. 또한 활성화된 동안 받는 모든 피해가 10%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210817] = {name = "[q2]생존의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]가슴보호구 또는 로브에 적자 생존 룬을 새깁니다.\n\n\n근접 공격 치명타에 적중당할 확률이 6%만큼, 받는 모든 피해가 10%만큼 감소합니다. 곰 변신 또는 광포한 곰 변신 상태일 때 받는 피해가 추가로 10%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210818] = {name = "[q2]고독한 늑대의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]가슴보호구 또는 로브에 고독한 늑대 룬을 새깁니다.\n\n\n활성화된 야수가 없을 때 모든 공격의 공격력이 25%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210820] = {name = "[q2]희생의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]바지에 희생의 손길 룬을 새깁니다.\n\n\n대상 파티원이나 공격대원이 받는 피해의 30%를 시전자가 대신 받습니다. 12초 동안 혹은 시전자가 최대 생명력의 100%에 해당하는 피해를 이전받을 때까지 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210822] = {name = "[q2]조화로운 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]가슴보호구 또는 로브에 우연한 행운 룬을 새깁니다.\n\n\n순간 치유로 치유 시 20초 동안 다음 하급 치유, 치유, 상급 치유, 치유의 기원의 시전 시간이 20%만큼 감소합니다. 최대 3번까지 중첩됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210823] = {name = "[q2]쌍수 무기 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]가슴보호구 또는 로브에 쌍수 무기 전문화 룬을 새깁니다.\n\n\n쌍수 무기 사용 시 주문 및 근접 공격이 적중할 확률이 5%만큼 증가합니다. 쌍수 무기를 사용하는 동안에는 폭풍의 일격이 두 무기로 적중합니다. 또한 보조 무기의 공격력이 60%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210824] = {name = "[q2]서약의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]바지에 악마의 서약 룬을 새깁니다.\n\n\n화염 및 암흑 주문의 공격력이 10%만큼 증가하고, 소환수의 공격이 치명타로 적중하면 파티원 또는 공격대원에게 45초 동안 악마의 서약 효과를 부여합니다. 악마의 서약은 주문 공격력과 치유량을 주문 공격력의 10%, 혹은 ( 60 / 2) 중 더 높은 쪽에 해당하는 수치만큼 증가시킵니다. 예속된 악마에게는 효과를 발휘하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210825] = {name = "[q2]전쟁인도자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]가슴보호구에 돌격대장 룬을 새깁니다.\n\n\n전투 중 그리고 모든 태세에서 돌진, 봉쇄, 가로막기를 사용할 수 있습니다. 또한 사용 시 모든 이동 방해 효과에서 벗어납니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210953] = {name = "보스카의 눈", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"눈은 아무런 생기도 없지만, 감시당하는 기분이 듭니다...\""},
[210955] = {name = "붉은십자군 수습마법사의 제복", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 붉은십자군의 구성원으로 변장합니다. 수상한 움직임을 보이면 변장이 들통날 수 있습니다."},
[210963] = {name = "점술가의 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적"},
[210966] = {name = "군단의 피", additional_info = "퀘스트 아이템\n고유 아이템 (10)\n[q]\"어둡고 탁합니다... 이 피는 군단의 위대한 사령관과 연관되어 있습니다.\""},
[210967] = {name = "기밀 전언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[210968] = {name = "성물함 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적"},
[210979] = {name = "[q2]그림자 밟기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]허리띠에 그림자 밟기 룬을 새깁니다.\n\n\n그림자 사이로 숨어들어 적의 배후에서 나타납니다. 3초 동안 이동 속도가 70%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[210980] = {name = "[q2]탈태의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장갑에 탈태 룬을 새깁니다.\n\n\n악마로 변신해 방어도가 500%만큼, 생명력이 15%만큼 증가하고 치명타에 적중당할 확률이 6%만큼 감소합니다. 위협 수준이 50%만큼, 생명력 전환으로 회복하는 마나가 100%만큼 증가하지만 모든 공격력이 10%만큼 감소합니다. 탈태 사용 시 몇몇 능력이 변화하고 신규 능력을 얻습니다.\n\n 불타는 고통: 즉시 시전됩니다.\n\n 어둠의 화살: 어둠의 화살: 어둠의 회전베기로 변화합니다. 암흑 근접 공격으로 주위 최대 10명의 적을 가격하지만, 6초의 재사용 대기시간이 적용됩니다.\n\n 공포: 위협으로 대체됩니다.\n\n\n적을 도발하여 자신을 공격하도록 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다.\n\n 악마의 돌진\n\n\n적에게 돌진하여 1초 동안 기절시킵니다. 전투 중에는 사용할 수 없습니다.\n\n 악마의 포효\n\n\n6초 동안 주위 모든 적이 자신에게 공격을 집중하도록 만듭니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211205] = {name = "[q2]코브 학살자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]장갑에 코브라 학살자 룬을 새깁니다.\n\n\n매 근접 공격 시 10%의 확률로 살쾡이의 이빨이 활성화됩니다. 적이 회피할 경우에는 100%의 확률로 발동합니다. 이 확률은 축적됩니다. 후속 공격을 가할 때마다 초기화되지 않으면 10%만큼 증가합니다. 살쾡이의 이빨은 전투력의 45%에 해당하는 추가 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211247] = {name = "[q2]도안: 불사조 손목띠", additional_info = "획득 시 귀속\n재봉술 (125) 필요\n[q2]사용 효과: 불사조 손목띠 만드는 법을 배웁니다.\n[q3]불사조 손목띠\n착용 시 귀속\n{손목} {천}\n방어도 21\n내구도 30 / 30\n요구 레벨 25\n[q2]착용 효과: 화염 계열의 주문과 효과의 공격력이 최대 13만큼 증가합니다.\n양모 두루마리 (6), 기름 주머니 (2), 가는 실타래 (2) 필요"},
[211263] = {name = "[q0]심판의 가슴보호대", additional_info = "획득 시 귀속\n{가슴} {판금}\n방어도 857\n힘 +17\n체력 +25\n지능 +20\n화염 저항력 +10\n자연 저항력 +10\n내구도 165 / 165\n직업: 성기사\n요구 레벨 60\n[q2]착용 효과: 방어 숙련도 +6\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 14만큼 증가합니다.\n[q2]착용 효과: 방패의 피해 방어량이 32만큼 증가합니다.\n\n[q]심판의 보루 (0/1)\n[q0]심판의 가슴보호대\n[q0](3) 세트 : 헌신의 오라가 추가로 받는 모든 주문 피해를 5%만큼 감소시킵니다.\n(5) 세트 : 심판이 대상에 대한 위협 수준을 50%만큼 추가로 생성합니다.\n(8) 세트 : 모든 주문 및 효과에 의한 피해와 치유량이 최대 47만큼 증가합니다."},
[211269] = {name = "조잡한 그림", additional_info = "획득 시 귀속\n퀘스트 시작 아이템"},
[211301] = {name = "[q2]결점 노출의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]허리띠에 결점 노출 룬을 새깁니다.\n\n\n근접 및 원거리 공격이 치명타로 적중하면 7초 동안 전투력이 현재 민첩성의 40%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
