[211385] = {name = "[q2]독사 확산의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]바지에 독사 확산 룬을 새깁니다.\n\n\n일제 사격에 적중당한 대상은 추가로 12초 동안 독사 쐐기에 걸립니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211386] = {name = "[q2]주문 기록: 비전 쇄도", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n{[q2]바지에 비전 쇄도 룬을 새깁니다.\n\n\n대상에게 쇄도하는 마력의 형태로 남은 마나를 모두 방출해 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 226 / 100]에서 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 264 / 100]의 비전 피해를 입힙니다. 남은 마나에 따라 공격력}이 최대 300%만큼 증가합니다. 이후 일반 마나 회복 {속도에 따라 마나가 회복되며 8초 동안 마나 회복 {속도가 300%만큼 증가합니다.}\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211387] = {name = "[q2]유혹하는 빛의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]장갑에 빛의 봉화 룬을 새깁니다.\n\n\n대상은 40미터 반경 내에 있는 모든 파티원과 공격대원에게 빛의 봉화가 됩니다. 해당 범위 내에 있는 파티원 또는 공격대원에게 시전하는 자신의 치유 주문은 회복시킨 생명력의 75%만큼 봉화가 된 대상의 생명력을 회복시킵니다. 동시에 오직 하나의 대상만 빛의 봉화가 될 수 있습니다. 1시간 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211390] = {name = "[q2]가벼운 상처의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]가슴보호구 또는 로브에 얕은 상처일 뿐 룬을 새깁니다.\n\n\n칼춤이 활성화된 동안 받는 물리 피해가 20%만큼 감소하며, ( 60 * 5)|1을;를; 넘는 방어 숙련 12점당 받는 피해가 추가로 1%만큼 감소합니다. 또한 회피율이 50%만큼 증가하고 근접 공격에 치명타로 적중당할 확률은 6%만큼, 공격력은 20%만큼 감소합니다. 모든 행동으로 생성되는 위협 수준이 크게 증가합니다. 교란 능력은 놀리기로 대체됩니다. 놀리기는 대상을 도발하여 자신을 공격하게 합니다.\n\n\n적을 도발하여 자신을 공격하도록 만듭니다. 이미 자신을 공격하고 있다면 아무런 효과를 발휘하지 못합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211391] = {name = "[q2]치유의 비의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]가슴보호구 또는 로브에 치유의 비 룬을 새깁니다.\n\n대상 플레이어 주위 15미터 내에 있는 대상 플레이어의 파티원 모두를 1초마다 [(29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) * 15 / 100]만큼 치유합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211392] = {name = "[q2]영원한 고통의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]바지에 영원한 고통 룬을 새깁니다.\n\n\n생명력 흡수, 영혼 흡수, 어둠의 화살, 어둠의 회전베기, 불타는 고통, 소각, 유령 출몰 시전 시 대상에게 걸린 부패의 지속시간이 최대 지속시간으로 갱신됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211393] = {name = "[q2]하나된 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장갑에 하나된 분노 룬을 새깁니다.\n\n\n쌍수 무기를 사용하는 동안 이동 속도가 10%만큼 증가합니다. 또한 이전에 자동 공격을 가한 같은 대상에게 근접 자동 공격을 사용할 때마다 공격 속도가 4%만큼 증가합니다. 최대 5번까지 중첩됩니다. 10초 동안 혹은 다른 대상에게 자동 공격을 사용할 때까지 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211419] = {name = "[q2]한 줌의 변화무쌍한 비늘", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"완전한 실체가 있는 게 아닌 듯 희미하게 일렁이는 특이한 비늘입니다. 무언가 경이로운 마법이 작용하는 게 분명합니다... 이에 관해 자세히 알려줄 사람을 만나볼 수 있다면 도움이 될 텐데 말이지요.\""},
[211420] = {name = "[q3]변화무쌍한 비늘 부적", additional_info = "획득 시 귀속\n장신구\n정신력 +5\n요구 레벨 25\n[q2]착용 효과: 착용자를 짓이기는 어둠의 효과로부터 보호합니다."},
[211421] = {name = "상자", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 강력한 빛의 근원으로 상자를 파괴하는 시도를 합니다.\n[q]\"맨손으로 상자를 만지는 순간 깊은 불안감이 엄습해 옵니다... 하지만, 생전 처음 느껴보는 창발적인 영감이 동시에 떠오르기도 합니다.\""},
[211422] = {name = "[q4]공허의 편린", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"상자가 남긴 물건이라곤 완벽할 정도로 새까만 작은 흑수정 조각 하나뿐입니다. 빛을 끌어당겨 흡수하는 듯합니다.\""},
[211423] = {name = "[q4]공허에 물든 가죽 장갑", additional_info = "획득 시 귀속\n고유 장착 아이템: [Void-Touched] (1)\n{손} {가죽}\n[q2]방어도 110\n민첩성 +6\n체력 +6\n정신력 +4\n내구도 70 / 70\n요구 레벨 25\n가죽 세공 (100) 필요\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]사용 효과: 광기에 빠져듭니다. 10초 동안 공격 속도와 위협 생성 수준이 10%만큼 증가합니다. (10 분 재사용 대기시간)"},
