[211452] = {name = "[q3]완벽한 검은심연 진주", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 25\n[q]\"고대 신의 시종 아쿠마이의 죽음을 입증하는 증거입니다. 바샤나 룬토템에게 소식을 전하면 무척이나 관심을 보일 것입니다.\""},
[211454] = {name = "이상한 물구슬", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 25"},
[211455] = {name = "[q3]매끈한 작업용 장갑", additional_info = "획득 시 귀속\n{손} {가죽}\n방어도 68\n체력 +7\n지능 +5\n내구도 35 / 35\n요구 레벨 25\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 22만큼 증가합니다.\n[q2]착용 효과: 자연 계열의 주문과 효과의 공격력이 최대 14만큼 증가합니다."},
[211456] = {name = "[q3]자발적인 희생의 단검", additional_info = "획득 시 귀속\n고유 아이템\n{주장비} {단검}\n{공격력 12 - 27 } {속도 1.50}\n(초당 공격력 13.00)\n방어도 60\n체력 +4\n지능 +3\n내구도 65 / 65\n요구 레벨 25\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 12만큼 증가합니다."},
[211457] = {name = "[q3]황혼 파수병의 요대", additional_info = "획득 시 귀속\n{허리} {사슬}\n방어도 128\n힘 +7\n체력 +9\n내구도 40 / 40\n요구 레벨 25\n[q2]착용 효과: 방어 숙련도 +4"},
[211458] = {name = "[q3]어둠 수호의 고서", additional_info = "획득 시 귀속\n보조장비\n방어도 40\n체력 +4\n지능 +3\n암흑 저항력 +5\n요구 레벨 25"},
[211460] = {name = "[q3]고대 북극의 버클러", additional_info = "획득 시 귀속\n{보조장비} {방패}\n방어도 725\n15의 피해 방어\n체력 +7\n정신력 +8\n냉기 저항력 +5\n내구도 100 / 100"},
[211461] = {name = "[q3]각인된 묘비의 홀", additional_info = "획득 시 귀속\n{원거리 장비} {마법봉}\n{암흑계 공격력 35 - 61 } {속도 1.50}\n(초당 공격력 32.00)\n정신력 +1\n암흑 저항력 +5\n내구도 65 / 65"},
[211462] = {name = "[q3]영원한 존속의 반지", additional_info = "획득 시 귀속\n손가락\n체력 +3\n정신력 +8"},
[211463] = {name = "[q3]재잘거리는 딱정벌레 팔보호구", additional_info = "획득 시 귀속\n{손목} {사슬}\n방어도 95\n민첩성 +4\n체력 +7\n내구도 40 / 40\n요구 레벨 25"},
[211464] = {name = "[q3]해진 고위성직자의 단망토", additional_info = "획득 시 귀속\n등\n방어도 24\n정신력 +9"},
[211465] = {name = "[q3]통찰의 빛구름 장화", additional_info = "획득 시 귀속\n{발} {천}\n방어도 34\n민첩성 +2\n지능 +5\n정신력 +4\n내구도 35 / 35"},
[211466] = {name = "[q3]뜰지기의 심재 요대", additional_info = "획득 시 귀속\n{허리} {가죽}\n방어도 57\n체력 +8\n정신력 +7\n내구도 30 / 30"},
[211467] = {name = "[q3]무쇠 주먹의 고리", additional_info = "획득 시 귀속\n손가락\n힘 +4\n민첩성 +7"},
[211468] = {name = "[q3]너덜거리는 밤나무 어깨보호대", additional_info = "획득 시 귀속\n{어깨} {천}\n방어도 30\n체력 +2\n지능 +6\n내구도 40 / 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 5만큼 증가합니다."},
[211471] = {name = "폭포수 열쇠", additional_info = "고유 아이템"},
[211472] = {name = "[q2]추방의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n[q2]바지에 오라 숙련 룬을 새깁니다.\n\n\n집중의 오라를 받는 모든 대상이 침묵과 주문 방해 효과에 면역이 되고 다른 모든 오라의 효과가 100%만큼 증가합니다. 6초 동안 지속됩니다.\n[q]\"적 5명에게 언데드 퇴치를 시전한 후, 퇴마술로 처치 시 새로운 능력을 배웁니다.\""},
[211476] = {name = "[q2]불의 자취의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]가슴보호구 또는 로브에 불꽃의 호수 룬을 새깁니다.\n\n\n불의 비가 더는 정신을 집중시키지 않지만 재사용 대기시간이 8초만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211477] = {name = "[q2]소각의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]팔보호구에 소각 룬을 새깁니다.\n\n\n적을 불태워 [222 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)]에서 [258 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60)]의 피해를 입히고 다음 15초 동안 모든 화염 공격력이 40%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211482] = {name = "뾰족창부족의 공물", additional_info = "획득 시 귀속\n고유 아이템"},
[211487] = {name = "[q2]파괴 폭탄", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 전방의 지면에 잠시 후 터지는 폭탄을 놓습니다.\n[q]\"잿더미와 잔해를 정리하는 데나 쓸모 있어 보입니다.\""},
[211488] = {name = "[q2]복수자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]바지에 응징의 방패 룬을 새깁니다.\n\n\n적에게 신성한 방패를 날려 [366 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * 주문력 + 0.091 * 전투력]에서 [448 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100 + 0.091 * 주문력 + 0.091 * 전투력]의 신성 피해를 입히고 멍해지도록 만듭니다. 주위 적을 연쇄적으로 가격하며 최대 3명의 대상을 공격합니다. 5초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211490] = {name = "[q2]천 갈래 빛의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장갑에 치유의 마법진 룬을 새깁니다.\n\n\n대상 플레이어의 43.5미터 내에 있는 모든 파티원을 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 130 / 100]에서 [(38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) * 144 / 100]만큼 치유합니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[211491] = {name = "[q4]무한한 멀록 가죽 가방", additional_info = "획득 시 귀속\n고유 아이템\n14칸 가방"},
[211492] = {name = "[q4]켈리스의 가방", additional_info = "획득 시 귀속\n16칸 영혼의 가방\n직업: 흑마법사"},
[211498] = {name = "[q3]훈련생의 파수꾼 밤호랑이", additional_info = "획득 시 귀속\n탈것\n아무 얼라이언스 종족 요구\n요구 레벨 25\n[q2]사용 효과: 훈련생의 파수꾼 밤호랑이를 소환합니다. 잿빛 골짜기에서만 사용할 수 있습니다. (3 초 재사용 대기시간)"},
[211499] = {name = "[q3]훈련생의 척후 늑대", additional_info = "획득 시 귀속\n탈것\n아무 호드 종족 요구\n요구 레벨 25\n[q2]사용 효과: 훈련생의 척후 늑대를 소환합니다. 잿빛 골짜기에서만 사용할 수 있습니다. (3 초 재사용 대기시간)"},
[211500] = {name = "[q3]탄력 있는 천 머리띠", additional_info = "획득 시 귀속\n고유 아이템\n{머리} {천}\n방어도 50\n내구도 50 / 50\n요구 레벨 20\n[q2]착용 효과: 전쟁노래 협곡에서 받는 모든 피해와 치명타에 적중당할 확률이 5%만큼 감소합니다."},
[211501] = {name = "[q4]힘의 가슴보호대", additional_info = "획득 시 귀속\n{가슴} {판금}\n방어도 749\n힘 +27\n체력 +18\n화염 저항력 +10\n내구도 165 / 165\n직업: 전사\n요구 레벨 60\n[q2]착용 효과: 치명타를 적중시킬 확률이 1%만큼 증가합니다.\n[q2]착용 효과: 무기의 적중률이 1%만큼 증가합니다."},
[211502] = {name = "[q4]공허에 물든 가죽 건틀릿", additional_info = "획득 시 귀속\n고유 장착 아이템: [Void-Touched] (1)\n{손} {가죽}\n방어도 70\n체력 +5\n지능 +7\n정신력 +6\n내구도 70 / 70\n요구 레벨 25\n가죽 세공 (100) 필요\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]사용 효과: 광기에 빠져듭니다. 10초 동안 주문 공격력과 위협 생성 수준이 10%만큼 증가합니다. (10 분 재사용 대기시간)"},
