[211940] = {name = "[q3]에크사브의 부족 수호자", additional_info = "획득 시 귀속\n{양손 장비} {장창}\n{공격력 155 - 231 } {속도 3.70}\n(초당 공격력 52.16)\n내구도 100 / 100\n요구 레벨 59\n[q2]착용 효과: 4분 동안 주위 파티원의 방어도가 40만큼 상승합니다. 오라는 성기사마다 동시에 하나만 유지할 수 있습니다."},
[211941] = {name = "[q3]바람술사 창", additional_info = "획득 시 귀속\n{양손 장비} {장창}\n{공격력 147 - 223 } {속도 3.60}\n(초당 공격력 51.39)\n내구도 100 / 100\n요구 레벨 58\n[q2]발동 효과: 정면의 적을 바람과 불, 여러 가지 신비한 힘으로 공격합니다."},
[211944] = {name = "[q3]토자라의 업보", additional_info = "획득 시 귀속\n{양손 장비} {장창}\n{공격력 158 - 234 } {속도 3.50}\n(초당 공격력 56.00)\n내구도 100 / 100\n요구 레벨 58\n[q2]발동 효과: 불의 파도가 시전자 주위로 뿜어져 나와 모든 적을 불길로 감싸 208 에서 249의 화염 피해를 입히고 6초 동안 멍해지게 만듭니다."},
[211953] = {name = "[q2]비전 회복의 두루마리 (1 레벨)", additional_info = "획득 시 귀속\n직업: 마법사\n요구 레벨 20\n[q2]사용 효과: 매 5초마다 8의 마나가 회복됩니다."},
[211954] = {name = "[q2]비전 정확도의 두루마리 (1 레벨)", additional_info = "획득 시 귀속\n직업: 마법사\n요구 레벨 20\n[q2]사용 효과: 주문의 적중률이 1%만큼 증가합니다."},
[211955] = {name = "[q2]비전 보호 - 화염의 두루마리 (1 레벨)", additional_info = "획득 시 귀속\n직업: 마법사\n요구 레벨 20\n[q2]사용 효과: 30분 동안 화염 저항력이 20만큼 증가합니다."},
[211956] = {name = "[q2]비전 보호 - 냉기의 두루마리 (1 레벨)", additional_info = "획득 시 귀속\n직업: 마법사\n요구 레벨 20\n[q2]사용 효과: 30분 동안 냉기 저항력이 20만큼 증가합니다."},
[211957] = {name = "[q2]신비의 마법 강화의 두루마리 (1 레벨)", additional_info = "획득 시 귀속\n직업: 마법사\n요구 레벨 20\n[q2]사용 효과: 주문의 극대화 확률이 1%만큼 증가합니다."},
[212160] = {name = "시간축복 재배열기", additional_info = "디스커버리 시즌\n[q2]사용 효과: 시간의 결을 조작하여 용사냥, 혈투의 전장, 줄구룹, 악령의 숲에서 얻은 이로운 효과를 재배열합니다. (5 분 재사용 대기시간)"},
[212225] = {name = "[q3]끝없는 영혼 그릇", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 다음 영혼의 조각을 소모하는 주문 시전 시 영혼의 조각을 소모하지 않습니다. (5 분 재사용 대기시간)"},
[212230] = {name = "[q3]설계도: 영혼 그릇", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과: 영혼 그릇 만드는 법을 배웁니다.\n[q3]영혼 그릇\n[q]\"악마의 영혼을 가두어 힘을 착취합니다.\"\n음영석 (4), 검은 황산 , 악마의 구슬 필요"},
[212548] = {name = "[q2]일월식의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]허리띠에 일월식 룬을 새깁니다.\n\n\n별빛 화살이 다음 2회 동안 시전하는 천벌의 치명타 및 극대화율을 30%만큼 증가시킵니다. 또한 천벌은 다음 별빛 화살의 시전 시간을 1.0초만큼 감소시킵니다. 두 효과는 최대 4번까지 중첩됩니다. 두 주문을 시전할 때 피해를 받을 경우 70%의 확률로 시전 시간을 잃지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212549] = {name = "[q2]덫사냥꾼의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]장화에 덫 발사 룬을 새깁니다.\n\n\n빙결의 덫, 제물의 덫, 폭발의 덫을 35미터 반경 내 임의의 위치에 놓을 수 있습니다. 화염 기반 덫과 냉기 기반 덫의 공유 재사용 대기시간이 분리됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212551] = {name = "[q2]전쟁의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]장화에 전쟁의 기술 룬을 새깁니다.\n\n\n근접 치명타를 적중시켰을 때 퇴마술의 남은 재사용 대기시간이 2초만큼, 마나 소모량이 80%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212552] = {name = "[q2]정신 이상의 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 정신의 쐐기 룬을 새깁니다.\n\n\n대상을 강타하여 [122 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]에서 [142 * (9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) / 100]의 암흑냉기 피해를 입힙니다. 또한 다음 정신 분열의 치명타 및 극대화율이 30%만큼 증가합니다. 최대 3번까지 중첩됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212559] = {name = "[q2]독 묻은 칼의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]허리띠에 독 칼 룬을 새깁니다.\n\n\n즉시 보조 무기를 던져 대상에게 일반 보조 무기 공격력에 해당하는 피해를 입히고 100%의 확률로 보조 무기에 바른 독에 중독시킵니다. 연계 점수 1점을 생성합니다. 대상에게 부여된 맹독 중첩 하나당 5의 기력을 돌려받습니다.\n\n 독 칼은 사악한 일격으로 발동하거나 사악한 일격의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212560] = {name = "[q2]고대의 각성의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]장화에 고대의 각성 룬을 새깁니다.\n\n\n치유의 물결 또는 하급 치유의 물결 주문이 극대화 효과를 발휘하면 고대의 영혼이 소환되어 40미터 내에 있으며 백분율 생명력이 가장 낮은 파티원의 생명력을 치유된 생명력의 30%만큼 회복시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212561] = {name = "[q2]불타는 어둠의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]허리띠에 어둠과 불길 룬을 새깁니다.\n\n\n화염 및 암흑 주문이 치명타 및 극대화 효과를 발휘하면 10초 동안 화염 및 암흑 공격력이 10%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212562] = {name = "[q2]치유의 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장화에 분노의 재생력 룬을 새깁니다.\n\n\n10초에 걸쳐 최대 생명력의 30%를 회복합니다. 격노, 광전사의 격노, 피의 분노가 활성화됐을 때만 사용할 수 있습니다. 기절한 상태에서 사용 가능합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[212568] = {name = "[q3]늑대머리 노획품", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n요구 레벨 40\n[q2]사용 효과: 투구 칸 아이템에 영구적으로 마법을 부여해 표범 또는 곰 변신 시 20의 기력 또는 5의 분노를 생성하도록 합니다."},
