[212994] = {name = "[q3]폭풍추격자의 손목띠", additional_info = "획득 시 귀속\n{손목} {가죽}\n방어도 53\n힘 +8\n민첩성 +7\n체력 +5\n내구도 35 / 35\n직업: 주술사\n요구 레벨 35"},
[212996] = {name = "[q3]번개부름이의 손목띠", additional_info = "획득 시 귀속\n{손목} {가죽}\n방어도 53\n체력 +5\n지능 +7\n내구도 35 / 35\n직업: 주술사\n요구 레벨 35\n[q2]착용 효과: 주문의 적중률이 1%만큼 증가합니다."},
[212997] = {name = "[q3]파도소환사의 손목띠", additional_info = "획득 시 귀속\n{손목} {가죽}\n방어도 53\n체력 +5\n지능 +7\n내구도 35 / 35\n직업: 주술사\n요구 레벨 35\n[q2]착용 효과: 매 5초마다 3의 마나가 회복됩니다."},
[213074] = {name = "[q2]육성의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]허리띠에 육성 룬을 새깁니다.\n\n\n아군 대상의 생명력을 [161 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]~[189 / 100 * (38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60)]만큼 회복시킵니다. 회복, 재생, 피어나는 생명, 급속 성장 효과가 걸려 있는 대상은 회복되는 생명력이 20%만큼 증가합니다. 이 주문은 치유의 손길 또는 재생과 관련된 모든 이로운 효과를 적용 및 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213086] = {name = "[q2]폭풍의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]허리띠에 소용돌이치는 무기 룬을 새깁니다.\n\n\n근접 공격으로 피해를 입히면 일정 확률로 다음 번개 화살, 연쇄 번개, 하급 치유의 물결 또는 용암 폭발 주문의 시전 시간과 마나 소모량이 20%만큼 감소합니다. 주 무기에 질풍의 무기가 부여되어 있다면 발동 확률이 50%만큼, 양손 무기을 사용 중일 경우에는 추가로 50%만큼 증가합니다. 5번까지 중복됩니다. 30초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213087] = {name = "[q3]수호병의 망토", additional_info = "획득 시 귀속\n고유 아이템\n등\n방어도 24\n힘 +4\n민첩성 +4\n체력 +4\n지능 +4\n정신력 +4\n요구 레벨 25"},
[213088] = {name = "[q3]수호병의 망토", additional_info = "획득 시 귀속\n고유 아이템\n등\n방어도 24\n힘 +4\n민첩성 +4\n체력 +4\n지능 +4\n정신력 +4\n요구 레벨 25"},
[213090] = {name = "[q2]결속의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]허리띠에 흑마법서: 결속 룬을 새깁니다.\n\n\n자신이나 소환된 악마가 피해를 입힐 때 10%의 확률로 15초 동안 서로의 공격력을 10%만큼 증가시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213093] = {name = "[q2]마력의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]허리띠에 마력의 쇄도 룬을 새깁니다.\n\n\n화염 충격으로 피해를 입힐 때마다 5%의 확률로 용암 폭발 및 연쇄 번개의 재사용 대기시간이 초기화되고 다음 10초 안에 시전하는 용암 폭발 또는 연쇄 번개가 즉시 시전됩니다. 성난 해일로 치유할 때마다 5%의 확률로 다음 10초 안에 시전하는 연쇄 치유가 즉시 시전됩니다. 추가로 5초마다 지능의 15%에 해당하는 마나를 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213094] = {name = "[q2]불꽃 회오리의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]허리띠에 불꽃 회오리 룬을 새깁니다.\n\n\n불꽃 회오리 토템 주문이 불꽃 회오리로 대체됩니다. 불꽃 회오리 시전 시 현재 활성화된 불의 토템이 자신의 위치에 피해를 발산합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213096] = {name = "[q2]미끼의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]장화에 미끼 토템 룬을 새깁니다.\n\n\n10초 동안 대상의 발밑에 5의 생명력을 지닌 미끼 토템을 소환합니다. 다음에 대상이 받는 근접 또는 원거리 공격이 토템에게로 이전됩니다. 추가로 토템이 대상을 10초 동안 이동 방해 효과에 면역으로 만듭니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213098] = {name = "[q2]환기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]허리띠에 환기 룬을 새깁니다.\n\n\n부패, 제물, 고통의 저주, 불안정한 고통, 암흑불길, 생명력 착취를 걸면 대상에게 해당 주문의 주기적인 피해 한 주기와 같은 피해를 즉시 입힙니다. 또한, 해당 주문의 남은 지속시간이 6초 미만일 때 갱신 시 대상에게 주문의 남은 주기적인 피해에 해당하는 피해를 즉시 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213100] = {name = "[q2]금지된 지식의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장화에 악마의 지식 룬을 새깁니다.\n\n\n주문 공격력과 치유량이 악마 소환수의 총 체력과 지능을 합한 수치의 3%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213101] = {name = "[q2]암흑불길의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장화에 암흑불길 룬을 새깁니다.\n\n\n적을 불태워 [173 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100 * ( ( ( 1 ) ) ) ]의 암흑불길 피해를 입히고 추가로 15초에 걸쳐 [64 * 5 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100]의 추가 암흑불길 피해를 입힙니다.\n\n 암흑불길은 제물 또는 고통, 파괴, 화염, 암흑 주문을 변경하거나 상호작용하는 모든 효과를 발동시키고 그 이로운 효과를 받지만, 각각의 흑마법사는 대상에게 제물 또는 암흑불길 중 하나만 걸 수 있습니다. 추가로 암흑불길이 어둠의 화살 연마 특성을 발동시키며 추가로 26회 충전되게 합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213102] = {name = "[q2]악심의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장화에 악인의 춤 룬을 새깁니다.\n\n\n적에게 치명타 및 극대화 피해를 입힐 때마다 시전자와 악마 소환수가 주문 극대화율의 70%에 해당하는 회피 확률을 얻으며, 시전자와 소환수 모두 최대 마나의 2%를 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213103] = {name = "[q2]피 분출의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]허리띠에 피 분출 룬을 새깁니다.\n\n\n영웅의 일격, 피의 갈증, 소용돌이 사용 시 30%의 확률로 15초 안에 사용하는 다음 격돌이 즉시 시전되고 두 근접 무기를 모두 사용하며, 분노를 소모하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213104] = {name = "[q2]무자비한 정밀함의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]허리띠에 정확한 시간 감각 룬을 새깁니다.\n\n\n격돌이 즉시 시전되지만 6초의 재사용 대기시간이 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213105] = {name = "[q3]쇼마겟돈", additional_info = "획득 시 귀속\n{한손 장비} {둔기}\n{공격력 50 - 93 } {속도 2.60}\n(초당 공격력 27.50)\n내구도 90 / 90\n직업: 전사\n요구 레벨 40\n[q2]사용 효과: 공격 속도가 4%만큼 증가합니다. 또한 근접 공격 시 일정 확률로 7의 추가 화염 피해를 입힙니다. (2 분 재사용 대기시간)"},
[213109] = {name = "[q2]집중된 분노의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]허리띠에 분노 집중 룬을 새깁니다.\n\n\n공격 기술에 소비되는 분노가 3만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213110] = {name = "[q2]사령관의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장화에 재집결의 함성 룬을 새깁니다.\n\n\n재집결의 함성을 내질러 10초 동안 40미터 내의 모든 파티원과 공격대원의 최대 생명력을 15%만큼 증가시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213111] = {name = "[q2]개입의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장화에 가로막기 룬을 새깁니다.\n\n\n빠른 속도로 대상 파티원에게 달려가 파티원에게 적중할 다음 근접 또는 원거리 공격을 대신 맞고 전체 위협 수준을 10%만큼 감소시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213112] = {name = "[q2]주문 기록: 화살 탄막", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]허리띠에 화살 탄막 룬을 새깁니다.\n\n\n비전 작렬 시전 시 40%의 확률로, 화염구 및 얼음 화살 시전 시 20%의 확률로 다음 신비한 화살 주문의 정신 집중 시간이 50%만큼 감소하고 마나 소비량이 100%만큼 감소하며 매 0.5초마다 화살을 발사합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213117] = {name = "[q2]광폭화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]허리띠에 광폭화 룬을 새깁니다.\n\n\n활성화되면 짓이기기 (곰) 및 가르기 기술이 최대 3명의 대상을 공격하며, 가르기가 분노를 소모하지 않고, 짓이기기 (곰)의 재사용 대기시간이 발생하지 않습니다. 또한 표범 변신 상태에서 기술 사용 시 소모되는 기력이 50%만큼 감소합니다. 15초 동안 지속됩니다. 곰 변신, 표범 변신, 광포한 곰 변신 상태일 때 활성화할 수 있습니다.\n\n 광포화되면 즉시 공포 효과에서 벗어나고 효과가 지속되는 동안 공포에 면역이 됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213118] = {name = "[q2]밀림의 왕의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장화에 정글의 왕 룬을 새깁니다.\n\n\n호랑이의 분노가 모든 공격력을 고정 수치 대신 15%만큼 증가시킵니다. 또한 사용 즉시 60의 기력을 회복합니다. 더는 전역 재사용 대기시간이 적용되지 않으며 30초의 재사용 대기시간이 적용됩니다. 추가로 호랑이의 분노가 표범 변신 상태가 아닐 때도 지속되지만 곰 변신 또는 광포한 곰 변신에 진입하면 취소됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213119] = {name = "[q2]본능의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장화에 생존 본능 룬을 새깁니다.\n\n\n활성화 시 20초 동안 최대 생명력이 30%만큼, 물리 계열이 아닌 모든 치유량이 20%만큼 증가합니다. 이 효과가 만료되면 임시 생명력은 사라집니다. 달빛야수 변신을 제외한 모든 변신 상태에서 사용할 수 있습니다.\n\n 추가로 곰 변신 또는 광포한 곰 변신 상태로 회피할 때마다 5의 분노를 생성합니다. 표범 변신 상태로 회피할 때는 10의 기력을 회복하며, 그 외의 변신 상태일 때는 최대 마나의 1%를 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213120] = {name = "[q2]꿈꾸는 자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]장화에 꿈결 룬을 새깁니다.\n\n\n비주기적인 공격 주문이 치명타 및 극대화 효과를 발휘하거나 별빛쇄도로 피해를 입히면 8초 동안 주문을 시전할 때 마나 회복 속도가 50%만큼, 12초 동안 플레이어가 아닌 대상에게 입히는 비전 및 자연 피해가 20%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213121] = {name = "[q2]보존된 호랑가시나무", additional_info = "요구 레벨 25\n[q2]사용 효과: 자신의 탈것을 축제 분위기에 맞게 바꿉니다. (1 분 재사용 대기시간)"},
[213122] = {name = "[q2]고정 사격의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]허리띠에 고정 사격 룬을 새깁니다.\n\n\n안정적인 사격으로 원거리 무기 공격력의 100%에 해당하는 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213123] = {name = "[q2]노출의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]허리띠에 결점 노출 룬을 새깁니다.\n\n\n근접 및 원거리 공격이 치명타로 적중하면 7초 동안 전투력이 현재 민첩성의 40%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213124] = {name = "[q2]근접 전투의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]허리띠에 근접 전투 전문가 룬을 새깁니다.\n\n\n랩터의 일격이 즉시 시전됩니다. 또한 살쾡이의 이빨 및 랩터의 일격으로 공격할 때마다 40%의 확률로 살쾡이의 이빨과 랩터의 일격이 재사용 대기시간이 초기화됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213125] = {name = "[q2]사기 고취의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]장화에 비룡의 일격 룬을 새깁니다.\n\n\n비룡 쐐기를 비룡의 일격으로 대체합니다. 비룡의 일격은 무기 공격력의 140%에 해당하는 피해를 입히고 출혈을 일으켜 지속적으로 피해를 입힙니다.\n\n 비룡의 일격은 비룡 쐐기 특성이 필요하며 생존 마법책에서 비룡 쐐기 능력을 대체합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213126] = {name = "[q2]싸움꾼의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]장화에 쌍수 무기 전문화 룬을 새깁니다.\n\n\n보조 무기의 공격력이 60%만큼 증가합니다. 또한 쌍수 무기 사용 시 랩터의 일격이 두 무기를 모두 사용하여 적중합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213127] = {name = "[q2]주문 기록: 기냉전비 살화", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석하여 새로운 각인술 주문을 배웁니다."},
[213128] = {name = "[q2]경건의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]허리띠에 유연한 보호 룬을 새깁니다.\n\n\n신의 가호의 지속시간 동안 행동을 취할 수 있으며 지속시간이 50%만큼 증가하지만, 면역 상태가 되는 대신 받는 피해가 50%만큼 감소합니다. 추가로 신성한 방패를 활성화하면 ( 60 * 5)|1을;를; 넘는 방어 숙련 1점당 전투력이 4만큼 추가로 증가합니다. 15초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213129] = {name = "[q2]빛의 은총의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]허리띠에 수호의 빛 룬을 새깁니다.\n\n\n근접 무기로 피해를 입히면 1분 동안 전투력의 30%만큼 주문 공격력이 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213130] = {name = "[q2]주입의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]허리띠에 빛 주입 룬을 새깁니다.\n\n\n신성 충격의 공격력 및 치유량이 50%만큼 증가하고 재사용 대기시간이 6초로 감소합니다. 또한 신성 충격이 치명타 및 극대화 효과를 발휘하면 소모한 마나를 돌려받고 재사용 대기시간이 3초만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213131] = {name = "[q2]성스러운 보호막의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]장화에 성스러운 보호막 룬을 새깁니다.\n\n\n대상이 피해를 받을 때마다 [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100]의 피해를 흡수하고 최대 6초 동안 빛의 섬광 주문이 극대화 효과를 발휘할 확률을 50%만큼 증가시키는 성스러운 보호막 효과를 얻습니다. 추가로 빛의 섬광 시전 시 성스러운 보호막이 부여된 대상을 12초에 걸쳐 100%만큼 추가로 치유합니다. 이 효과는 최대 6초마다 한 번씩만 발동됩니다. 1분 동안 지속됩니다. 이 주문은 동시에 하나의 대상에만 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213132] = {name = "[q2]수호자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]장화에 빛의 인도 룬을 새깁니다.\n\n\n근접 무기로 대상을 공격할 때마다 15초 동안 3초마다 최대 마나의 5%를 회복합니다. 하지만 마나를 회복하는 동안 치유 주문의 치유 효과가 50%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213136] = {name = "[q2]잠행의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장화에 잠행의 대가 룬을 새깁니다.\n\n\n은신 중에 가한 공격과 은신이 풀린 후 6초 동안에 가한 공격은 10%의 추가 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213137] = {name = "[q2]공격자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장화에 습격 룬을 새깁니다.\n\n\n매복과 기습이 적중하면 대상을 혼란스럽게 만들어 8초 동안 적의 근접 공격 간격을 10%만큼 늘리고 이동 속도를 50%만큼 감소시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213138] = {name = "[q2]왼손잡이의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]장화에 충격 완화 룬을 새깁니다.\n\n\n회피 또는 무기 막기를 할 때마다 생명력이 5%만큼 증가합니다. 최대 5번까지 중첩됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213139] = {name = "[q2]암살자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]허리띠에 표창 투척 룬을 새깁니다.\n\n\n적에게 표창을 던져 전투력의 50%에 해당하는 피해를 입히고, 주위 적 최대 4명을 추가로 가격합니다. 적중당한 대상 하나당 연계 점수 1점을 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213140] = {name = "[q2]빨라진 길의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 소생 강화 룬을 새깁니다.\n\n\n소생 부여 시 즉시 한 번 더 생명력을 회복시킵니다. 또한 시전자의 추가 치유 효과로 생명력을 회복할 때마다 효과가 15%만큼 증가합니다.\n\n 추가로 다른 사제의 소생에 영향을 받는 대상에게 소생을 걸 수 있습니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[213141] = {name = "[q2]희망의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 새로운 희망 룬을 새깁니다.\n\n\n약화된 영혼이 부여된 대상에게 순간 치유, 하급 치유, 치유, 상급 치유, 회개 시전 시 치유 효과가 20%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213142] = {name = "[q2]감금된 악의의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장화에 분산 룬을 새깁니다.\n\n\n순수한 암흑의 에너지로 흩어져, 받는 모든 피해를 90%만큼 감소시킵니다. 이 동안에는 공격하거나 주문을 시전할 수 없습니다. 매 1초마다 6%의 마나를 회복합니다. 6초 동안 지속됩니다. 기절, 공포, 침묵 효과에 걸려 있는 동안 시전할 수 있고 모든 이동 방해 효과와 감속 효과를 제거하며 활성화되어 있는 동안 해당 효과에 면역이 됩니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[213143] = {name = "[q2]불분명한 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장화에 고통 억제 룬을 새깁니다.\n\n\n아군 대상이 받는 모든 피해를 즉시 40%만큼 감소시키고 8초 동안 무효화에 대한 저항력을 65%만큼 증가시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213144] = {name = "[q2]영롱한 직관", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]장화에 구원자의 영혼 룬을 새깁니다.\n\n\n활성화 시 10초 동안 구원의 영혼으로 변신합니다. 이 형상일 때 모든 치유 주문을 자원 소모 없이 시전할 수 있지만 이동 및 공격이 불가능하며, 공격을 당하거나 주문 또는 효과의 대상으로 지정되지도 않습니다. 사용하려면 구원의 영혼 특성이 필요합니다. 사망 시 구원의 영혼 상태에 돌입하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[213165] = {name = "바실리스크: 과연 석화를 두려워해야 하는가?", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"바실리스크 신체 부위를 재료로 활용하는 방법에 관한 연구록입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[213168] = {name = "[q2]구리 핏빛 주화", additional_info = "획득 시 귀속\n[q2]사용 효과: 구리 핏빛 주화 100개를 은 핏빛 주화 1개로 변환합니다.\n[q]\"피의 로아에 대한 소소한 헌신을 증명하는 징표입니다.\""},
[213169] = {name = "[q3]은 핏빛 주화", additional_info = "획득 시 귀속\n[q2]사용 효과: 은 핏빛 주화 100개를 황금 핏빛 주화 1개로 변환합니다.\n[q]\"피의 로아에 대한 헌신을 증명하는 징표입니다.\""},
[213170] = {name = "[q4]황금 핏빛 주화", additional_info = "획득 시 귀속\n[q]\"피의 로아에 대한 지고한 헌신을 증명하는 징표입니다.\""},
[213278] = {name = "[q3]강타 지휘자의 손보호대", additional_info = "획득 시 귀속\n{손} {가죽}\n방어도 84\n민첩성 +10\n체력 +11\n내구도 35 / 35\n요구 레벨 40\n[q2]착용 효과: 장착 무기류 숙련도가 3만큼 증가합니다.\n[q2]착용 효과: 한손 둔기류 숙련도 +3"},
[213279] = {name = "[q3]반사성 해골모자", additional_info = "획득 시 귀속\n{머리} {사슬}\n방어도 222\n체력 +11\n지능 +13\n정신력 +8\n내구도 70 / 70\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 13만큼 증가합니다."},
[213280] = {name = "[q3]명사수의 조준 안경", additional_info = "획득 시 귀속\n{머리} {사슬}\n방어도 222\n민첩성 +9\n체력 +13\n지능 +8\n내구도 70 / 70\n요구 레벨 40\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다."},
[213281] = {name = "[q3]기가볼트 초유동 전자반응기", additional_info = "획득 시 귀속\n{머리} {천}\n방어도 55\n지능 +15\n정신력 +12\n내구도 50 / 50\n요구 레벨 40\n[q2]사용 효과: 벼락을 유도해 전방의 모든 적을 향해 발사하여 152 에서 172의 자연 피해를 입힙니다. 시전자는 10분 동안 전기장으로 둘러 쌓입니다. (30 분 재사용 대기시간)\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 16만큼 증가합니다."},
[213282] = {name = "[q4]초충전된 혁신의 톱니바퀴", additional_info = "획득 시 귀속\n고유 장착 아이템: [Hypercharged Gear] (1)\n손가락\n지능 +5\n정신력 +8\n비전 저항력 +5\n자연 저항력 +5\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 13만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 3의 마나가 회복됩니다."},
