[213417] = {name = "[q3]진은 전선 코이프", additional_info = "획득 시 귀속\n{머리} {판금}\n방어도 390\n체력 +8\n지능 +12\n내구도 80 / 80\n요구 레벨 40\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 5의 마나가 회복됩니다."},
[213418] = {name = "[q3]용접된 진은 고리", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {판금}\n방어도 210\n체력 +6\n지능 +5\n내구도 45 / 45\n요구 레벨 40\n[q2]착용 효과: 신성 계열의 주문과 효과의 공격력이 최대 14만큼 증가합니다."},
[213419] = {name = "[q3]9-60 수리 설명서", additional_info = "획득 시 귀속\n보조장비\n체력 +6\n지능 +6\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 22만큼 증가합니다."},
[213421] = {name = "그슬린 쪽지", additional_info = "획득 시 귀속\n직업: 마법사\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[213426] = {name = "오우거 피뢰침", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 부드러운 흙에 꽂습니다."},
[213427] = {name = "[q2]꼬질꼬질한 인양품", additional_info = nil},
[213442] = {name = "[q3]톱니대장의 발톱", additional_info = "획득 시 귀속\n{보조장비} {장착 무기}\n{공격력 60 - 111 } {속도 2.80}\n(초당 공격력 30.54)\n힘 +6\n민첩성 +6\n체력 +5\n내구도 90 / 90\n요구 레벨 40"},
[213443] = {name = "들썩거리는 선물상자", additional_info = "획득 시 귀속\n[q2]<열려면 마우스 오른쪽 클릭>"},
[213452] = {name = "[q2]잠든 신성 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q]\"우선 타인을 위해 스스로의 목숨을 내려놓은 뒤, 자신의 영혼이 떠나가기 전에 구원을 받아야 합니다.\""},
[213513] = {name = "[q2]구원의 성서", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {고서}\n직업: 성기사\n요구 레벨 18\n[q2]장화에 성스러운 보호막 룬을 새깁니다.\n\n\n대상이 피해를 받을 때마다 [36 * (38.258376 + 0.904195 * 60 + 0.161311 * 60 * 60) / 100]의 피해를 흡수하고 최대 6초 동안 빛의 섬광 주문이 극대화 효과를 발휘할 확률을 50%만큼 증가시키는 성스러운 보호막 효과를 얻습니다. 추가로 빛의 섬광 시전 시 성스러운 보호막이 부여된 대상을 12초에 걸쳐 100%만큼 추가로 치유합니다. 이 효과는 최대 6초마다 한 번씩만 발동됩니다. 1분 동안 지속됩니다. 이 주문은 동시에 하나의 대상에만 사용할 수 있습니다.\n[q]\"다른 이에게 자유의 축복을 부여해 이동 방해 효과를 5회 해제하면 새로운 능력을 배웁니다.\""},
[213526] = {name = "뒤섞인 허벅지 고기", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"소고기 맛과 닭고기 맛이 *함께* 납니다.\""},
[213527] = {name = "밀수업자의 향신료 혼합물", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"어느 배의 조리실에 갖다 놓아도 보물 취급을 받을 만한 물건입니다. 장화에 맛있는 맛을 가미합니다.\""},
[213528] = {name = "향유 혼합물", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"엄밀히 말해서 '시원한' 느낌이 들진 않습니다.\""},
[213529] = {name = "끈적거리는 맹독", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"늪지 동물을 게걸스럽게 먹어 치웁니다. 양념장 만들기에 딱 좋습니다!\""},
