[213548] = {name = "경계 통행의 두루마리", additional_info = "직업: 마법사\n요구 레벨 6\n[q2]사용 효과: 파티원에게 순간이동합니다. 자신과 대상 둘 다 여관이나 도시에서 휴식 상태여야 합니다."},
