[213552] = {name = "테라드라스의 눈물", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"겔키스 켄타우로스 부족이 철통같이 지키던 물건입니다. 대지의 정령이 주인을 지켜준다는 이야기가 전해집니다.\""},
[213553] = {name = "테라드라스의 눈물", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"겔키스 켄타우로스 부족이 철통같이 지키던 물건입니다. 대지의 정령이 주인을 지켜준다는 이야기가 전해집니다.\""},
[213554] = {name = "결정수가 든 병", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 테라드라스의 눈물과 혼합하여 타락을 정화하는 정기의 연고를 만듭니다.\n[q]\"물이 얼마나 투명하고 맑은지, 병이 빈 것처럼 보입니다.\""},
[213558] = {name = "정기의 연고", additional_info = "[q2]사용 효과: 타락에 물든 물건에 부어 정화합니다.\n[q]\"뿌리 깊은 타락을 정화하는 강력한 연고입니다.\""},
[213559] = {name = "[q3]기계타조 변속기", additional_info = "획득 시 귀속\n{원거리 장비} {마법봉}\n{비전계 공격력 44 - 83 } {속도 1.50}\n(초당 공격력 42.33)\n내구도 65 / 65\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 9만큼 증가합니다.\n[q]\"수동식 변속 기계타조의 존재를 암시하는 물건입니다.\""},
[213560] = {name = "[q3]기계타조 소음 완화 장치", additional_info = "획득 시 귀속\n{한손 장비} {둔기}\n{공격력 51 - 95 } {속도 2.40}\n(초당 공격력 30.42)\n체력 +7\n내구도 90 / 90\n요구 레벨 40\n[q2]착용 효과: 전투력 +16"},
[213563] = {name = "현장 안내서", additional_info = "획득 시 귀속\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[213564] = {name = "하급 환기의 두루마리", additional_info = "직업: 마법사\n[q2]사용 효과: 마나를 회복합니다. (8 분 재사용 대기시간)"},
[213565] = {name = "초보 곤충학자의 도구", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼 , 드루이드\n[q2]<열려면 마우스 오른쪽 클릭>"},
[213583] = {name = "[q2]유황 조각품", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"전 주인이 불장난을 너무 많이 친 모양입니다.\""},
[213594] = {name = "[q2]훼방꾼의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n요구 레벨 28\n[q2]허리띠에 광폭화 룬을 새깁니다.\n\n\n활성화되면 짓이기기 (곰) 및 가르기 기술이 최대 3명의 대상을 공격하며, 가르기가 분노를 소모하지 않고, 짓이기기 (곰)의 재사용 대기시간이 발생하지 않습니다. 또한 표범 변신 상태에서 기술 사용 시 소모되는 기력이 50%만큼 감소합니다. 15초 동안 지속됩니다. 곰 변신, 표범 변신, 광포한 곰 변신 상태일 때 활성화할 수 있습니다.\n\n 광포화되면 즉시 공포 효과에서 벗어나고 효과가 지속되는 동안 공포에 면역이 됩니다.\n[q]\"도전의 포효로 2명 이상의 적을 도발한 후, 그중 1명 이상의 적을 처치해야 합니다. 이 방식으로 적 5명을 처치한 후 우상을 사용하면 새로운 능력을 배웁니다.\""},
[213599] = {name = "[q2]불길한 환영", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]허리띠에 새로운 희망 룬을 새깁니다.\n\n\n약화된 영혼이 부여된 대상에게 순간 치유, 하급 치유, 치유, 상급 치유, 회개 시전 시 치유 효과가 20%만큼 증가합니다.\n[q2]사용 효과: 환영에 집중해 새로운 주문을 배웁니다. 타락한 지식의 편린이 필요합니다."},
[213632] = {name = "[q2]부분적인 주문 기록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 수집한 부분적인 주문 기록을 결합해 새로운 각인술 주문을 배울 수 있는 두루마리를 만듭니다.\n[q]\"조각술 능력을 배울 수 있는 두루마리와 비슷하게 생긴 미완의 책장입니다. 세 조각 중 두 조각이 없습니다.\""},
[213633] = {name = "[q2]부분적인 주문 기록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 수집한 부분적인 주문 기록을 결합해 새로운 각인술 주문을 배울 수 있는 두루마리를 만듭니다.\n[q]\"조각술 능력을 배울 수 있는 두루마리와 비슷하게 생긴 미완의 책장입니다. 세 조각 중 두 조각이 없습니다.\""},
[213634] = {name = "[q2]부분적인 주문 기록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 수집한 부분적인 주문 기록을 결합해 새로운 각인술 주문을 배울 수 있는 두루마리를 만듭니다.\n[q]\"조각술 능력을 배울 수 있는 두루마리와 비슷하게 생긴 미완의 책장입니다. 세 조각 중 두 조각이 없습니다.\""},
[213641] = {name = "[q3]놈리건 인양품 상자", additional_info = "획득 시 귀속\n[q]\"이 놈리건 인양품 상자에는 전문 기술에 유용한 물건이 들어 있습니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[213701] = {name = "튼튼한 하피 깃털", additional_info = "획득 시 귀속\n고유 아이템 (10)\n[q2]사용 효과: 튼튼한 하피 깃털 10개와 구름천둥매 송곳니 3개, 비단 실타래 1개를 결합해 바람의 정령에게 바치는 공물을 만듭니다."},
[213709] = {name = "구름천둥매 송곳니", additional_info = "획득 시 귀속\n고유 아이템 (3)\n[q2]사용 효과: 튼튼한 하피 깃털 10개와 구름천둥매 송곳니 3개, 비단 실타래 1개를 결합해 바람의 정령에게 바치는 공물을 만듭니다."},
[213735] = {name = "[q3]온전한 G-7 핵.심. 처리 장치", additional_info = "획득 시 귀속\n[q]\"무려 400만 기가플롭이 넘는 저변수 관계형 코드 덩어리를 연산할 수 있습니다. 우와!\""},
[213736] = {name = "[q2]부식된 G-7 핵.심. 처리 장치", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n[q]\"연산 핵입니다. 부식이 극심한 데다, 끈쩍거리는 검은색 물질로 뒤덮여 있습니다. 그래도 잘 살펴보면 일종의 일련번호와 단어 같은 게 보입니다. 복원하려면 전문가의 실력이 필요할 듯합니다.\""},
[213737] = {name = "바람의 정령에게 바치는 공물", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 바람의 정령에게 공물을 바쳐 믿음을 증명합니다."},
[214435] = {name = "퓨마 우리 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]사용 효과: 퓨마 우리를 엽니다."},
[215111] = {name = "[q4]노움 신경 연결 비전 전선 단안경", additional_info = "획득 시 귀속\n{머리} {천}\n방어도 58\n체력 +10\n지능 +11\n내구도 60 / 60\n요구 레벨 40\n재봉술 (225) 필요\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 22만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 4의 마나가 회복됩니다.\n[q2]사용 효과: 공기 중의 비전 마력을 활용해 충만한 영감을 얻습니다. 12초 동안 모든 주문의 마나 소모량이 50%만큼 감소하고 공격력과 치유량이 최대 50만큼 증가합니다. (10 분 재사용 대기시간)"},
[215114] = {name = "[q4]빛나는 초전도성 비늘 코이프", additional_info = "획득 시 귀속\n{머리} {사슬}\n방어도 242\n체력 +14\n지능 +15\n내구도 85 / 85\n요구 레벨 40\n가죽 세공 (225) 필요\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 21만큼 증가합니다.\n[q2]사용 효과: 초전도성 감전을 가해 즉시 자신에게 312 에서 688의 피해를 입히고 10초 동안 주문 시전 속도를 20%만큼 증가시킵니다. (10 분 재사용 대기시간)"},
[215115] = {name = "[q4]초전도성 금빛 허리싸개", additional_info = "획득 시 귀속\n{허리} {천}\n방어도 40\n체력 +9\n내구도 35 / 35\n요구 레벨 40\n기계공학 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]사용 효과: 허리띠에서 초전도성 동전을 꺼내 튕깁니다. 앞면이 나오면 30초 동안 모든 주문과 공격의 치명타 및 극대화율이 3%만큼 증가합니다. 뒷면이 나오면 30초 동안 이동 속도가 10%만큼 증가합니다. (15 분 재사용 대기시간)\n[q]\"움직일 때마다 희미한 딸깍 소리가 납니다.\""},
[215127] = {name = "[q2]고농도 방사능 폭탄", additional_info = "요구 레벨 35\n기계공학 (200) 필요\n[q2]사용 효과: 폭발 반경 내의 대상에게 150 에서 250의 화염 피해를 입히고 추가로 10초 동안 매 2초마다 25의 추가 자연 피해를 입힙니다. 또한 활성화되어 있는 동안 영향을 받는 대상의 이동 속도를 25%만큼 감소시킵니다. (1 분 재사용 대기시간)"},
[215129] = {name = "[q4]주문식: 무기 마법부여 - 분해", additional_info = "획득 시 귀속\n마법부여 (225) 필요\n[q2]사용 효과: 무기에 영구적으로 마법을 부여해 모든 주문 시전 및 공격 시 일정 확률로 기계 생명체에게 60 에서 90의 추가 피해를 입힙니다."},
[215138] = {name = "[q4]주문식: 가슴보호구 마법부여 - 응징의 집행자", additional_info = "획득 시 귀속\n마법부여 (225) 필요\n[q2]사용 효과: 가슴보호구에 영구적으로 마법을 부여해 착용자가 근접 공격을 받으면 공격자에게 9의 피해를 반사하게 하는 법을 배웁니다."},
[215141] = {name = "[q2]마력 깃든 인장: 혁신", additional_info = "획득 시 귀속\n마법부여 (225) 필요\n[q2]사용 효과: 혁신의 인장 만드는 법을 배웁니다.\n[q2]마력 깃든 인장: 혁신\n획득 시 귀속\n고유 아이템 (5)\n요구 레벨 40\n마법부여 (225) 필요\n[q2]사용 효과: 마력 깃든 혁신의 인장이 부여되어 30분 동안 주문의 공격력과 치유량이 최대 20만큼, 전투력이 20만큼 증가합니다. 이 효과는 전투 중이 아닐 때만 부여할 수 있습니다. (30 분 재사용 대기시간)\n환상 가루 (5) 필요"},
[215149] = {name = "[q4]도안: 노움 신경 연결 비전 전선 단안경", additional_info = "획득 시 귀속\n재봉술 (225) 필요\n[q2]사용 효과: 노움 신경 연결 비전 전선 단안경 만드는 법을 배웁니다.\n[q4]노움 신경 연결 비전 전선 단안경\n획득 시 귀속\n{머리} {천}\n방어도 58\n체력 +10\n지능 +11\n내구도 60 / 60\n요구 레벨 40\n재봉술 (225) 필요\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 22만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 4의 마나가 회복됩니다.\n[q2]사용 효과: 공기 중의 비전 마력을 활용해 충만한 영감을 얻습니다. 12초 동안 모든 주문의 마나 소모량이 50%만큼 감소하고 공격력과 치유량이 최대 50만큼 증가합니다. (10 분 재사용 대기시간)\n초전도성 비전 전선 (5), 희미하게 빛나는 가죽 , 차폐성 노움오딘 , 환상 가루 (10), 마법 두루마리 (10) 필요"},
[215152] = {name = "[q4]도안: 빛나는 노움 신경 연결 수도두건", additional_info = "획득 시 귀속\n가죽 세공 (225) 필요\n[q2]사용 효과: 빛나는 노움 신경 연결 수도두건 만드는 법을 배웁니다.\n[q4]빛나는 노움 신경 연결 수도두건\n획득 시 귀속\n{머리} {가죽}\n방어도 118\n민첩성 +14\n체력 +14\n내구도 70 / 70\n요구 레벨 40\n가죽 세공 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]착용 효과: 무기 공격력이 3만큼 증가합니다.\n[q2]사용 효과: 노움 신경 논리 충격을 가하여 즉시 자신에게 343 에서 757의 피해를 입히고 10초 동안 근접 및 원거리 공격 속도를 20%만큼 증가시킵니다. (10 분 재사용 대기시간)\n초전도성 비전 전선 , 두꺼운 경화 가죽 (5), 비단 실타래 (2), 희미하게 빛나는 가죽 (5) 필요"},
[215153] = {name = "[q4]설계도: 휘도는 진은 톱니장벽", additional_info = "획득 시 귀속\n기계공학 (225) 필요\n[q2]사용 효과: 휘도는 진은 톱니장벽 만드는 법을 배웁니다.\n[q4]휘도는 진은 톱니장벽\n획득 시 귀속\n{보조장비} {방패}\n방어도 1760\n29의 피해 방어\n힘 +9\n체력 +10\n내구도 120 / 120\n요구 레벨 40\n기계공학 (225) 필요\n[q2]착용 효과: 방패로 적의 공격을 방어할 확률이 1%만큼 증가합니다.\n[q2]착용 효과: 방패 막기 성공 시 방패에 부착된 서슬 칼날 톱니바퀴가 소용돌이치며 공격자에게 5 에서 10의 물리 피해를, 착용자에게 2 에서 10의 물리 피해를 입힙니다.\n[q]\"방패 테두리 부분이 회전하는데, 놀라울 정도로 날카롭습니다. 공격자는 물론이고 착용자에게도 위험한 물건입니다.\"\n저복사 진은 판금 (3), 광택을 낸 진은 톱니바퀴 (5), 희미하게 빛나는 가죽 (2), 미스릴 형틀 (2), 태엽장치 (2), 미스릴 주괴 (15) 필요"},
[215155] = {name = "[q4]도면: 강화된 간섭 무효화 보호모", additional_info = "획득 시 귀속\n대장기술 (225) 필요\n[q2]사용 효과: 강화된 간섭 무효화 보호모 만드는 법을 배웁니다.\n[q4]강화된 간섭 무효화 보호모\n획득 시 귀속\n{머리} {판금}\n방어도 426\n힘 +20\n체력 +14\n내구도 100 / 100\n요구 레벨 40\n대장기술 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]사용 효과: 강렬한 집중력을 얻어 이동 속도가 20%만큼 감소하지만 10초 동안 모든 계열에 대한 주문 저항력이 50만큼, 근접 공격 속도가 20%만큼 증가합니다. (10 분 재사용 대기시간)\n[q]\"착용자의 두뇌를 모든 위협으로부터 보호합니다. 물리적인 상해는 물론, 다른 위협까지 모두 말이죠!\"\n미스릴 주괴 (25), 저복사 진은 판금 (4), 초전도성 비전 전선 , 희미하게 빛나는 가죽 (2) 필요"},
[215156] = {name = "[q4]설계도: 초전도성 금빛 허리싸개", additional_info = "획득 시 귀속\n기계공학 (225) 필요\n[q2]사용 효과: 초전도성 금빛 허리싸개 만드는 법을 배웁니다.\n[q4]초전도성 금빛 허리싸개\n획득 시 귀속\n{허리} {천}\n방어도 40\n체력 +9\n내구도 35 / 35\n요구 레벨 40\n기계공학 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]사용 효과: 허리띠에서 초전도성 동전을 꺼내 튕깁니다. 앞면이 나오면 30초 동안 모든 주문과 공격의 치명타 및 극대화율이 3%만큼 증가합니다. 뒷면이 나오면 30초 동안 이동 속도가 10%만큼 증가합니다. (15 분 재사용 대기시간)\n[q]\"움직일 때마다 희미한 딸깍 소리가 납니다.\"\n광택을 낸 진은 톱니바퀴 (3), 초전도성 비전 전선 (3), 희미하게 빛나는 가죽 , 금괴 (10) 필요"},
[215161] = {name = "[q4]강화된 간섭 무효화 보호모", additional_info = "획득 시 귀속\n{머리} {판금}\n방어도 426\n힘 +20\n체력 +14\n내구도 100 / 100\n요구 레벨 40\n대장기술 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]사용 효과: 강렬한 집중력을 얻어 이동 속도가 20%만큼 감소하지만 10초 동안 모든 계열에 대한 주문 저항력이 50만큼, 근접 공격 속도가 20%만큼 증가합니다. (10 분 재사용 대기시간)\n[q]\"착용자의 두뇌를 모든 위협으로부터 보호합니다. 물리적인 상해는 물론, 다른 위협까지 모두 말이죠!\""},
[215162] = {name = "미약한 방사능 오염 회복 물약", additional_info = "요구 레벨 35\n[q2]사용 효과: 262 에서 438의 마나와 340 에서 460의 생명력을 회복합니다. 또한 20초 동안 전투력이 40만큼, 모든 주문의 공격력이 35만큼 증가합니다. (2 분 재사용 대기시간)\n[q]\"현기증, 입술 건조증, 피로, 식욕 감퇴, 급성 방사능 중독, 돌연변이, 사망과 같은 부작용이 발생할 수 있으니 유념해 주시기 바랍니다. 지시한 대로만 사용하십시오.\""},
[215163] = {name = "[q4]조제법: 미약한 방사능 오염 회복 물약", additional_info = "획득 시 귀속\n연금술 (225) 필요\n[q2]사용 효과: 미약한 방사능 오염 회복 물약 조제법을 배웁니다.\n미약한 방사능 오염 회복 물약\n요구 레벨 35\n[q2]사용 효과: 262 에서 438의 마나와 340 에서 460의 생명력을 회복합니다. 또한 20초 동안 전투력이 40만큼, 모든 주문의 공격력이 35만큼 증가합니다. (2 분 재사용 대기시간)\n[q]\"현기증, 입술 건조증, 피로, 식욕 감퇴, 급성 방사능 중독, 돌연변이, 사망과 같은 부작용이 발생할 수 있으니 유념해 주시기 바랍니다. 지시한 대로만 사용하십시오.\"\n오염된 니오다인 용액 상자 , 최하급 회복 물약 , 놈리건 낙진 (3), 수정 약병 (5) 필요"},
[215166] = {name = "[q4]빛나는 노움 신경 연결 수도두건", additional_info = "획득 시 귀속\n{머리} {가죽}\n방어도 118\n민첩성 +14\n체력 +14\n내구도 70 / 70\n요구 레벨 40\n가죽 세공 (225) 필요\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]착용 효과: 무기 공격력이 3만큼 증가합니다.\n[q2]사용 효과: 노움 신경 논리 충격을 가하여 즉시 자신에게 343 에서 757의 피해를 입히고 10초 동안 근접 및 원거리 공격 속도를 20%만큼 증가시킵니다. (10 분 재사용 대기시간)"},
[215167] = {name = "[q4]반사성 진은 뇌우리", additional_info = "획득 시 귀속\n{머리} {판금}\n방어도 426\n체력 +14\n지능 +15\n내구도 100 / 100\n요구 레벨 40\n대장기술 (225) 필요\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 21만큼 증가합니다.\n[q2]사용 효과: 강화된 의지력을 얻어 10초 동안 침묵 효과와 주문 방해 효과, 시전 밀림을 방지합니다. (10 분 재사용 대기시간)"},
[215168] = {name = "[q2]초보자용 방사능 폭탄", additional_info = "요구 레벨 40\n[q2]사용 효과: 폭발 반경 내의 대상에게 112 에서 188의 화염 피해를 입히고 추가로 10초 동안 매 2초마다 10의 추가 자연 피해를 입힙니다. 또한 10초 동안 영향을 받는 대상의 이동 속도를 25%만큼 감소시킵니다. (1 분 재사용 대기시간)\n[q]\"원본에서 위력을 낮춘 열화판입니다. 그럼에도 치명적인 건 여전합니다. 역량은 뒤떨어지지만 자신감은 넘쳐나는 이들을 위하여 제작되었습니다.\""},
[215257] = {name = "이해의 두루마리", additional_info = "직업: 마법사\n[q2]사용 효과: 이해의 부적 2개를 만듭니다. 여관이나 도시에서 휴식 중일 경우 4개를 만듭니다."},
[215365] = {name = "[q2]기원사의 어깨덧옷", additional_info = "착용 시 귀속\n{어깨} {천}\n방어도 32\n지능 +5\n내구도 45 / 45\n요구 레벨 25\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 7만큼 증가합니다."},
