[216635] = {name = "[q2]소진된 공허핵", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 적절한 동력원과 결합하여 충전된 공허핵을 만듭니다. (3 초 재사용 대기시간)\n[q]\"위르달이 말한 공허핵의 설명과 일치합니다만, 완전히 힘을 잃은 상태로 보입니다. 어떻게 충전할 방법이 있을 텐데요...\""},
[216636] = {name = "충전된 공허핵", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"주변의 모든 빛과 온기를 흡수하는 것 같습니다. 무척이나 차갑습니다.\""},
[216637] = {name = "무작위 부품 더미", additional_info = "[q]\"누군가에겐 쓸 만한 게 있을지도 모르지만, 당신에게는 고철로만 보일 뿐입니다.\""},
[216645] = {name = "[q2]암흑의 티끌", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"이 작은 마력의 티끌에서 어둠의 힘이 뿜어져 나옵니다. 이 힘으로 어떤 놀라운 마법을 부릴 수 있을지 누가 알겠습니까?\""},
[216646] = {name = "[q2]지리의 수수께끼 상자", additional_info = "획득 시 귀속\n[q]\"누군가는 유용하게 쓸 만한 물건이 들어 있습니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[216661] = {name = "꼬질꼬질한 반지", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 40"},
[216662] = {name = "[q2]반짝이는 금반지", additional_info = "획득 시 귀속\n고유 아이템\n손가락\n체력 +6\n정신력 +6"},
[216673] = {name = "[q3]탈바쉬의 반짝이는 금반지", additional_info = "획득 시 귀속\n고유 아이템\n손가락\n방어도 70\n체력 +16"},
[216674] = {name = "[q3]노그의 반짝이는 금반지", additional_info = "획득 시 귀속\n고유 아이템\n손가락\n방어도 70\n체력 +16"},
