[216676] = {name = "[q3]민첩한 출장용 작업복", additional_info = "획득 시 귀속\n{다리} {가죽}\n방어도 117\n힘 +5\n민첩성 +21\n체력 +8\n내구도 75 / 75"},
[216678] = {name = "[q3]삼중 강화 다리보호구", additional_info = "획득 시 귀속\n{다리} {사슬}\n[q2]방어도 460\n내구도 90 / 90\n[q2]착용 효과: 방어 숙련도 +6"},
[216679] = {name = "[q3]쇼니의 작업용 연장", additional_info = "획득 시 귀속\n{보조장비} {도끼}\n{공격력 37 - 68 } {속도 1.90}\n(초당 공격력 27.63)\n내구도 90 / 90\n[q2]발동 효과: 5초 동안 적을 무장 해제시킵니다."},
[216680] = {name = "[q3]망설임의 장갑", additional_info = "획득 시 귀속\n{손} {천}\n방어도 41\n지능 +12\n정신력 +11\n내구도 30 / 30"},
[216698] = {name = "[q3]하급기사의 용가죽 팔보호구", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {가죽}\n방어도 64\n체력 +8\n지능 +4\n내구도 35 / 35\n직업: 드루이드\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 6만큼 증가합니다."},
[216699] = {name = "[q3]하급기사의 사슬 손목보호대", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {사슬}\n방어도 131\n민첩성 +5\n체력 +12\n내구도 40 / 40\n직업: 사냥꾼\n요구 레벨 40"},
[216700] = {name = "[q3]하급기사의 가죽 팔보호구", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {가죽}\n방어도 64\n민첩성 +5\n체력 +12\n내구도 35 / 35\n직업: 도적\n요구 레벨 40"},
[216701] = {name = "[q3]하급기사의 판금 손목보호구", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {판금}\n방어도 231\n힘 +5\n체력 +12\n내구도 45 / 45\n직업: 전사 , 성기사\n요구 레벨 40"},
[216702] = {name = "[q3]하급기사의 비단 소매장식", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {천}\n방어도 31\n체력 +6\n지능 +3\n내구도 30 / 30\n직업: 사제 , 마법사 , 흑마법사\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 8만큼 증가합니다."},
[216703] = {name = "[q3]하급투사의 쇠사슬 손목보호구", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {사슬}\n방어도 131\n민첩성 +5\n체력 +10\n지능 +7\n내구도 40 / 40\n직업: 사냥꾼 , 주술사\n요구 레벨 40"},
[216704] = {name = "[q3]하급투사의 용가죽 손목보호대", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {가죽}\n방어도 64\n체력 +8\n지능 +4\n내구도 35 / 35\n직업: 드루이드\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 6만큼 증가합니다."},
[216705] = {name = "[q3]하급투사의 판금 팔보호구", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {판금}\n방어도 231\n힘 +5\n체력 +12\n내구도 45 / 45\n직업: 전사\n요구 레벨 40"},
[216706] = {name = "[q3]하급투사의 가죽 손목보호대", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {가죽}\n방어도 64\n민첩성 +5\n체력 +12\n내구도 35 / 35\n직업: 도적\n요구 레벨 40"},
[216707] = {name = "[q3]하급투사의 비단 소매장식", additional_info = "획득 시 귀속\n고유 아이템\n{손목} {천}\n방어도 31\n체력 +6\n지능 +3\n내구도 30 / 30\n직업: 사제 , 마법사 , 흑마법사\n요구 레벨 40\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 8만큼 증가합니다."},
[216738] = {name = "[q2]되돌리기 설명서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]대상에게 축적된 연계 점수를 모두 제거하고 최대 15초 동안 저장합니다. 저장한 연계 점수는 다음 근접 또는 원거리 능력을 적중시키는 NPC 적에게로 옮겨집니다.\n[q]\"되돌리기를 배웁니다.\""},
[216740] = {name = "[q2]확장된 지능의 고서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]신비한 지능의 마나 소모량이 50%만큼 감소하고 지속시간은 50%만큼 증가합니다.\n[q]\"확장된 지능을 배웁니다.\""},
[216744] = {name = "[q2]증가한 인내의 두루마리", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]신의 권능: 인내의 마나 소모량이 50%만큼 감소하고 지속시간은 50%만큼 증가합니다.\n[q]\"증가한 인내를 배웁니다.\""},
[216745] = {name = "[q2]어둠의 마귀의 두루마리", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]어둠의 마귀를 창조하여 대상을 공격하도록 합니다. 시전자는 어둠의 마귀가 공격할 때마다 5%의 마나를 회복합니다. 15초 동안 지속됩니다.\n[q]\"어둠의 마귀를 배웁니다.\""},
[216746] = {name = "[q2]지휘의 외침 안내서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]전사의 외침으로 주위 30미터 반경에 있는 모든 파티원의 체력이 2만큼 증가됩니다. 5분 동안 지속됩니다.\n[q]\"지휘의 외침을 배웁니다.\""},
[216747] = {name = "[q2]흑마법서: 영혼 수확", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]영혼 흡수로 피해를 입힐 때마다 일정 확률로 추가 영혼의 조각을 얻습니다. 영혼의 조각을 얻지 못할 때마다 획득 확률이 증가합니다.\n[q]\"영혼 수확을 배웁니다.\""},
[216748] = {name = "[q2]흑마법서: 소환의 차원문", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]파티원 혹은 공격대원 2명이 대상 파티원 혹은 공격대원을 소환할 수 있는 소환의 문을 만드는 의식을 시작합니다. 의식을 수행하려면 흑마법사를 제외하고 파티원 혹은 공격대원 2명이 필요합니다. 의식에 참가하려는 플레이어는 비전투 상태여야 하며 소환의 문에 오른쪽 클릭을 한 뒤 의식이 완료될 때까지 절대로 움직이면 안됩니다.\n[q]\"소환의 차원문을 배웁니다.\""},
[216764] = {name = "[q2]깊은 야생의 전언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]야생의 징표의 마나 소모량이 50%만큼 감소하고 지속시간은 50%만큼 증가합니다.\n[q]\"깊은 야생을 배웁니다.\""},
[216767] = {name = "[q2]되살리기의 전언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]죽은 플레이어를 되살립니다. 대상은 15%의 생명력과 마나를 지닌 채로 되살아납니다. 전투 중에는 사용할 수 없습니다.\n[q]\"되살리기를 배웁니다.\""},
[216768] = {name = "[q2]강화된 축복의 증언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]힘의 축복, 지혜의 축복, 구원의 축복, 성역의 축복, 빛의 축복, 왕의 축복의 지속시간이 100%만큼 증가하고 마나 소모량은 50%만큼 감소합니다.\n[q]\"강화된 축복을 배웁니다.\""},
[216769] = {name = "[q2]토템 재배치 계시록", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]활성화된 토템을 지정된 위치로 재배치합니다.\n[q]\"토템 재배치를 배웁니다.\""},
[216770] = {name = "[q2]독사의 상 논문", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n{[q2]사냥꾼이 독사의 상을 취합니다. 이 동안에는 원거리 및 근접 자동 공격 시 마나를 회복하지만 전체 공격력}이 10%만큼 감소합니다. 추가로 사냥꾼은 매 3초마다 전체 마나의 10%에 해당하는 마나를 얻습니다. 무기의 공격 {속도가 빠를 수록 회복되는 마나가 증가합니다. 한 번에 한 상만 취할 수 있습니다.}\n[q]\"독사의 상을 배웁니다.\""},
[216771] = {name = "[q2]강화된 회복의 전언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]다른 드루이드의 회복 또는 재생에 영향을 받는 대상에게 회복 및 재생을 걸 수 있습니다.\n[q]\"강화된 회복을 배웁니다.\""},
[216879] = {name = "수수께끼의 트롤 두루마리", additional_info = "고유 아이템\n직업: 마법사\n[q2]사용 효과: 이해의 부적으로 주문 기록을 해석합니다. 어떤 마법이 담겨 있을지 누가 알겠습니까?"},
[216880] = {name = "해독한 트롤 두루마리", additional_info = "고유 아이템\n퀘스트 시작 아이템\n직업: 사제"},
[216884] = {name = "[q4]피에 굶주린 칼날", additional_info = "획득 시 귀속\n고유 아이템: (알 수 없음 #636) (0)\n{양손 장비} {검}\n{공격력 649 - 764 } {속도 4.20}\n(초당 공격력 168.21)\n힘 +333\n내구도 120 / 120\n요구 레벨 125\n[q2]발동 효과: 계약에 의해 영혼을 소유합니다."},
