[219223] = {name = "[q3]검귀의 격노", additional_info = "획득 시 귀속\n{양손 장비} {검}\n{공격력 104 - 157 } {속도 3.00}\n(초당 공격력 43.50)\n힘 +17\n체력 +10\n내구도 100 / 100\n요구 레벨 50\n[q2]사용 효과: 8미터 내에 있는 최대 4명의 적을 공격합니다. 각각의 적에게 무기 공격력에 해당하는 피해를 입히고 소용돌이 능력의 재사용 대기시간을 초기화합니다. (2 분 재사용 대기시간)"},
[219326] = {name = "[q3]소생의 씨앗", additional_info = "획득 시 귀속\n장신구\n요구 레벨 50\n[q2]착용 효과: 적 인간형, 야수 또는 용족에게 능력 및 주문 적중 시 일정 확률로 씨앗을 심습니다. 씨앗을 심은 후 30초 내로 대상이 죽으면 시체에서 치유의 꽃이 자라납니다. (효과 발동 확률: 40%, 2분 재사용 대기시간)"},
[219343] = {name = "[q3]좀도둑의 수도두건", additional_info = "획득 시 귀속\n등\n방어도 36\n민첩성 +11\n요구 레벨 50\n[q2]착용 효과: 은신 효과 레벨이 3만큼 증가합니다. 함정 해제와 훔치기의 사정거리가 2미터만큼, 혼란의 사정거리가 5미터만큼 증가합니다."},
[219345] = {name = "[q3]불지옥 올가미", additional_info = "획득 시 귀속\n장신구\n요구 레벨 50\n[q2]사용 효과: 대상 악마 또는 야수를 한 곳에서 움직이지 못하게 하여 24초에 걸쳐 총 200의 화염 피해를 입힙니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다. 올가미에 걸린 심장부 사냥개를 길들일 수 있습니다. (1 분 재사용 대기시간)"},
