[220164] = {name = "[q2]검투사의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]장화에 검투사 태세 룬을 새깁니다.\n\n\n공격적인 태세입니다. 방패를 착용한 동안 공격력이 10%만큼, 방패 막기 확률이 10%만큼 증가하지만 방어도가 30%만큼, 위협 생성 수준이 30%만큼 감소합니다. 또한 자신을 대상으로 지정하지 않은 적에게 자동 공격으로 피해를 입히면 50%의 분노를 추가로 생성합니다.\n\n 검투사 태세로 방패를 착용하고 있는 동안에는 다른 태세로 제한되는 능력을 모두 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220165] = {name = "[q2]천벌의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]투구에 천벌 룬을 새깁니다.\n\n\n신성화 피해가 극대화 효과를 발휘할 수 있습니다. 또한 퇴마술, 신성 충격, 햇살, 신의 격노, 신성화 주문으로 피해를 입히면 치명타 및 극대화율이 근접 치명타 및 극대화율만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220166] = {name = "이글거리는 지옥핵", additional_info = "퀘스트 아이템"},
[220167] = {name = "일렁이는 무덤 가루", additional_info = "퀘스트 아이템\n[q]\"가장 사랑하는 이에게 살해당한 사람의 무덤에서 채취한 무덤 가루...\""},
[220168] = {name = "세 번 증류한 용암 맥주", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"흔들림 없는 손길과 불안정한 정신으로 만들어 낸 화염의 비약입니다.\""},
[220169] = {name = "신앙의 상징", additional_info = "퀘스트 아이템\n[q]\"새로운 목적을 찾아낸 이에게 선물로 받은 신앙의 상징...\""},
[220173] = {name = "[q4]반응소실증", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{양손 장비} {검}\n{공격력 142 - 213 } {속도 3.40}\n(초당 공격력 52.21)\n힘 +15\n민첩성 +11\n체력 +28\n내구도 120 / 120\n직업: 전사 , 성기사\n요구 레벨 50\n[q2]발동 효과: 대상에게 반응소실증을 걸어 최대 2초 동안 방황하게 만듭니다.\n[q]\"악몽에서 탄생했습니다.\""},
[220213] = {name = "지옥 마력 혈액", additional_info = "획득 시 귀속\n고유 아이템"},
[220214] = {name = "불지옥 사슬", additional_info = "획득 시 귀속\n고유 아이템 (5)"},
[220216] = {name = "지옥불 올가미", additional_info = "획득 시 귀속\n[q2]사용 효과: 해방된 칼레팩투스를 약화시킵니다. (30 초 재사용 대기시간)"},
[220217] = {name = "[q2]굶주림의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n{[q2]투구에 신속한 사냥 룬을 새깁니다.\n\n\n속사의 재사용 대기시간이 80%만큼 감소합니다. 또한 속사 사용 시 근접 공격 {속도가 40%만큼 증가하고 경험치 또는 명예 점수를 제공하는 적 처치 시 20초 동안 다음 사격 능력의 공격력}이 20%만큼 증가합니다.}\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220345] = {name = "핏빛 마술", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"온갖 강력한 피의 의식에 대한 개요가 담겨 있습니다. 도서관 수집품으로 삼기엔 논란의 여지가 있을 듯합니다.\""},
[220346] = {name = "파도현자의 전설", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"알아보기 어려운 기록과 도표로 뒤덮여 있습니다. 떨리는 손으로 쓴 모양입니다. 그래도 도서관 수집품으로 나쁘지 않습니다.\""},
[220347] = {name = "경계와 비전", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"책장의 글자가 읽히기를 거부하듯 이리저리 움직입니다. 도서관 수집품으로 삼기엔 의문이 들긴 합니다.\""},
[220348] = {name = "일상 예의", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"엄격한 명가 사회에서 기초 마법의 역할을 알려주는 안내서입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[220349] = {name = "바위의 설계", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"재앙 수준을 제외한 거의 모든 재해를 견뎌낼 수 있는 튼튼한 건축학 기법서입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[220350] = {name = "지독한 여정", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"정신을 개조하는 독소와 맹독에 관한 기록입니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[220351] = {name = "탁한 바람의 정기", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 이것을 마시면 주술사가 자연의 정령들을 볼 수 있습니다."},
[220352] = {name = "금속 정신", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"야금술에 마법을 접목하는 방법과 노천채굴, 중공업에 관한 드워프 기술서입니다. 투박하지만 유익합니다. 도서관 수집품으로 손색이 없습니다.\""},
[220353] = {name = "창조술사의 전서", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"전쟁 전 주문과 비전 이론을 모아놓은 책입니다. 현대에는 대부분 사용되지 않습니다. 도서관 수집품으로 손색없는 훌륭한 물품입니다.\""},
[220360] = {name = "[q2]꽃피우기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]팔보호구에 꽃피우기 룬을 새깁니다.\n\n\n신속한 치유가 추가로 꽃피우기를 발동시킵니다. 꽃피우기 발동 시 신속한 치유의 대상 지점에서 15미터 내에 있는 모든 파티원을 1초마다 [(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100]만큼 치유합니다. 15초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220375] = {name = "바람의 파편", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 바람의 파편과 정기의 정수를 결합합니다. 타락에 물든 사당을 찾는 데 도움이 됩니다."},
[220379] = {name = "찢어진 주술사의 기록", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n직업: 주술사\n[q]\"너무 급하게 휘갈겨 알아보기가 불가능에 가까운 기록입니다. 책장이 무언가에 감싸여 있는 듯합니다.\""},
[220446] = {name = "[q2]이계의 보물", additional_info = "획득 시 귀속\n[q2]<열려면 마우스 오른쪽 클릭>"},
