[220610] = {name = "[q2]교묘한 정신의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]투구에 교묘한 정신 룬을 새깁니다.\n\n\n폭풍의 일격으로 피해를 입히면 전투력이 지능의 150%만큼 증가합니다. 또한 30초 동안 주문 공격력이 총 전투력의 35%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220611] = {name = "[q3]후쿠의 사술 단망토", additional_info = "획득 시 귀속\n등\n방어도 39\n지능 +10\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 15만큼 증가합니다."},
[220612] = {name = "[q2]굽이치는 물결의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]투구에 굽이치는 물결 룬을 새깁니다.\n\n\n연쇄 치유 또는 성난 해일 시전 시 굽이치는 물결 2중첩을 얻습니다. 이 중첩은 치유의 물결의 시전 시간을 30%만큼, 연쇄 치유의 시전 시간을 15%만큼 감소시키고 하급 치유의 물결의 치명타 및 극대화 확률을 25%만큼 증가시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220613] = {name = "[q2]구르는 천둥의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]팔보호구에 구르는 천둥 룬을 새깁니다.\n\n\n번개 화살 및 연쇄 번개 시전 시 50%의 확률로 활성화된 번개 보호막에 중첩을 얻습니다. 최대 9번까지 중첩됩니다.\n\n 대지 충격 시전 시 3개를 초과하는 모든 번개 보호막 중첩을 방출해 대상에게 피해를 입히고 방출한 중첩 하나당 최대 마나의 2%를 회복합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220614] = {name = "[q2]전하 충격의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]팔보호구에 전하 충격 룬을 새깁니다.\n\n\n번개 보호막이 9회 중첩됩니다. 또한 근접 공격 시 12%의 확률로 중첩이 하나 발동해 대상에게 즉시 피해를 입힙니다. 쌍수 무기 사용 시에는 6%의 확률로 발동합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220615] = {name = "[q3]퓨마 털가죽 망토", additional_info = "획득 시 귀속\n등\n방어도 39\n힘 +6\n민첩성 +15\n요구 레벨 50"},
[220616] = {name = "[q2]과충전의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]팔보호구에 과충전 룬을 새깁니다.\n\n\n번개 보호막의 중첩이 소모되지 않으며, 3초의 재사용 대기시간이 적용됩니다. 또한 8미터 내의 모든 적에게 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220617] = {name = "[q2]병균 확산의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]투구에 병균 확산 룬을 새깁니다.\n\n\n부패, 불안정한 고통, 고통의 저주, 제물, 파멸의 저주, 생명력 착취 능력의 주기적인 피해가 치명타 및 극대화 효과를 발휘할 수 있도록 합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220618] = {name = "[q2]제물의 오라의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]팔보호구에 제물의 오라 룬을 새깁니다.\n\n\n적에게 근접 공격을 받을 때마다 주위의 적을 불태워 [(6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) * 20 / 100]의 피해를 입힙니다. 1초에 한 번씩만 발동합니다. 또한 받는 모든 마법 피해가 10%만큼 감소하고 화염 공격력은 10%만큼 증가합니다. 활성화되어 있는 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[220619] = {name = "[q4]아탈라이 피의 의식", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 고대 아탈라이 피의 의식 경구가 새겨진 제례용 단검입니다. (35 초 재사용 대기시간)\n[q]\"피의 로아는 가치 있는 자만을 간택합니다.\""},
[220620] = {name = "[q4]천둥매 해골", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 천둥매를 소환하거나 소환 해제합니다."},
[220621] = {name = "[q4]악몽 공명 수정", additional_info = "획득 시 귀속\n장신구\n요구 레벨 50\n에메랄드 감시자\n- 확고한 동맹 필요\n[q2]사용 효과: 수정이 악몽에 반응하여 공명합니다.\n[q]\"결정화된 악몽의 정수입니다. 꿈에 반응하여 진동하고 있습니다. 마치... 타락을 갈망하는 듯합니다.\""},
[220622] = {name = "[q4]완벽하게 보존된 용의 눈", additional_info = "획득 시 귀속\n목\n체력 +8\n지능 +10\n정신력 +8\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 24만큼 증가합니다."},
[220623] = {name = "[q4]진도의 잃어버린 목걸이", additional_info = "획득 시 귀속\n목\n체력 +9\n지능 +8\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 19만큼 증가합니다."},
[220624] = {name = "[q3]피로 얼룩인 용맹의 부적", additional_info = "획득 시 귀속\n목\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 전투력 +18"},
[220625] = {name = "[q3]추방자의 탄력", additional_info = "획득 시 귀속\n목\n방어도 90\n체력 +8\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다."},
[220626] = {name = "[q4]광전사의 비룡발톱 고리", additional_info = "획득 시 귀속\n손가락\n체력 +13\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]착용 효과: 전투력 +20"},
[220627] = {name = "[q4]추적자의 비룡발톱 고리", additional_info = "획득 시 귀속\n손가락\n체력 +10\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]착용 효과: 원거리 전투력 +31"},
[220628] = {name = "[q4]전령의 비룡발톱 고리", additional_info = "획득 시 귀속\n손가락\n지능 +11\n정신력 +12\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 15만큼 증가합니다."},
[220629] = {name = "[q4]핏빛 선지자의 비룡발톱 고리", additional_info = "획득 시 귀속\n손가락\n지능 +12\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 20만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 5의 마나가 회복됩니다."},
[220630] = {name = "[q4]무력의 비룡발톱 고리", additional_info = "획득 시 귀속\n손가락\n[q2]방어도 60\n체력 +16\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다."},
[220632] = {name = "[q4]아탈라이 피의 의식 메달", additional_info = "획득 시 귀속\n고유 아이템\n장신구\n요구 레벨 50\n[q2]사용 효과: 20초 동안 근접 및 원거리 공격력이 20만큼 증가합니다. 매번 대상을 공격할 때마다 보너스 공격력은 1만큼 감소합니다. (2 분 재사용 대기시간)"},
[220633] = {name = "[q4]아탈라이 피의 의식 훈장", additional_info = "획득 시 귀속\n고유 아이템\n장신구\n요구 레벨 50\n[q2]사용 효과: 20초 동안 방어도를 1000만큼, 방어 숙련도를 20만큼 증가시킵니다. 매번 근접이나 원거리 공격을 받을 때마다 100의 방어도와 2의 방어 숙련도 보너스 효과가 감소됩니다. (2 분 재사용 대기시간)"},
[220634] = {name = "[q4]아탈라이 피의 의식 부적", additional_info = "획득 시 귀속\n고유 아이템\n장신구\n요구 레벨 50\n[q2]사용 효과: 20초 동안 주문력이 최대 96만큼, 치유량이 최대 192만큼 증가합니다. 주문을 시전할 때마다 추가 주문 공격력이 8만큼, 추가 치유량이 16만큼 감소합니다. (2 분 재사용 대기시간)"},
[220635] = {name = "[q4]아탈알라리온의 마력 깃든 바위", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 영혼을 아탈알라리온이 총애하는 바위에 집중합니다. 그의 영혼이 남긴 메아리가 깃듭니다. (15 분 재사용 대기시간)"},
[220636] = {name = "[q3]아탈라이 혈기 문장", additional_info = "획득 시 귀속\n직업: 전사 , 성기사 , 사냥꾼 , 도적 , 주술사"},
[220637] = {name = "[q3]아탈라이 의식 징표", additional_info = "획득 시 귀속\n직업: 사제 , 마법사 , 흑마법사 , 드루이드"},
[220638] = {name = "[q4]이질적인 사술 막대", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 자신에게 고대 아탈라이 사술을 겁니다. (15 분 재사용 대기시간)\n[q]\"A test for only the strongest of bonds.\""},
[220639] = {name = "[q4]렐드라의 행동 불가 장치", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 이동 불가 상태가 됩니다. (3 초 재사용 대기시간)"},
[220642] = {name = "[q3]추방당한 순교자의 판금 방어구", additional_info = "획득 시 귀속\n{가슴} {판금}\n방어도 577\n힘 +5\n민첩성 +9\n체력 +18\n내구도 135 / 135\n직업: 전사 , 성기사\n요구 레벨 50\n[q2]착용 효과: 방패의 피해 방어량이 24만큼 증가합니다.\n\n[q]추방당한 순교자의 온전한 갑옷 (0/3)\n[q0]추방당한 순교자의 판금 방어구\n추방당한 순교자의 판금 다리보호대\n추방당한 순교자의 판금 장화\n[q0](2) 세트 : 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n(3) 세트 : 방패로 공격을 방어하면 6초 동안 피해 방어량이 50만큼 증가합니다."},
[220643] = {name = "[q3]추방당한 순교자의 판금 다리보호대", additional_info = "획득 시 귀속\n{다리} {판금}\n방어도 505\n힘 +11\n체력 +18\n내구도 100 / 100\n직업: 전사 , 성기사\n요구 레벨 50\n[q2]착용 효과: 방패의 피해 방어량이 23만큼 증가합니다.\n\n[q]추방당한 순교자의 온전한 갑옷 (0/3)\n[q0]추방당한 순교자의 판금 방어구\n추방당한 순교자의 판금 다리보호대\n추방당한 순교자의 판금 장화\n[q0](2) 세트 : 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n(3) 세트 : 방패로 공격을 방어하면 6초 동안 피해 방어량이 50만큼 증가합니다."},
[220648] = {name = "[q0]추방당한 순교자의 판금 장화", additional_info = "획득 시 귀속\n{발} {판금}\n방어도 397\n힘 +7\n체력 +19\n내구도 65 / 65\n직업: 전사 , 성기사\n요구 레벨 50\n[q2]착용 효과: 방패로 적의 공격을 방어할 확률이 1%만큼 증가합니다.\n\n[q]추방당한 순교자의 온전한 갑옷 (0/3)\n[q0]추방당한 순교자의 판금 방어구\n추방당한 순교자의 판금 다리보호대\n추방당한 순교자의 판금 장화\n[q0](2) 세트 : 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n(3) 세트 : 방패로 공격을 방어하면 6초 동안 피해 방어량이 50만큼 증가합니다."},
[220649] = {name = "[q3]메리스라의 유산", additional_info = "획득 시 귀속\n고유 아이템\n{가슴} {천}\n방어도 72\n체력 +20\n비전 저항력 +5\n자연 저항력 +5\n내구도 80 / 80\n요구 레벨 50\n에메랄드 감시자\n- 매우 우호적 필요\n[q2]사용 효과: 적을 최대 30초 동안 잠재웁니다. 대상이 피해를 입으면 깨어납니다. 한 번에 하나의 대상만 잠재울 수 있습니다. (15 분 재사용 대기시간)"},
[220650] = {name = "[q3]집착하는 선지자의 가슴갑옷", additional_info = "획득 시 귀속\n{가슴} {판금}\n방어도 577\n체력 +11\n지능 +10\n내구도 135 / 135\n직업: 성기사\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 37만큼 증가합니다.\n\n[q]집착하는 선지자의 판금 (0/3)\n[q0]집착하는 선지자의 가슴갑옷\n집착하는 선지자의 다리보호대\n집착하는 선지자의 화려한 장화\n[q0](2) 세트 : 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n(3) 세트 : 신성 주문의 치명타 및 극대화율이 3%만큼 증가합니다."},
