[221261] = {name = "[q2]야생의 속삭임 비약", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 아감마간의 혼을 소환합니다. 가시덩굴 구릉의 가시덩굴 소용돌이 꼭대기에서 주위의 적을 모두 처치한 후에만 사용할 수 있습니다. (5 초 재사용 대기시간)"},
[221262] = {name = "[q2]야생의 공물", additional_info = "획득 시 귀속"},
[221267] = {name = "[q2]피의 갈증의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]투구에 피의 맛 룬을 새깁니다.\n\n\n분쇄 능력으로 피해를 입힐 때마다 제압이 9초 동안 혹은 1회의 공격을 사용할 때까지 활성화됩니다. 이 효과는 6초에 한 번씩만 발동합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
