[221339] = {name = "[q2]설계도: 고블린 로켓 장화", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과:\n\n\n[q2]고블린 로켓 장화\n착용 시 귀속\n{발} {천}\n방어도 41\n내구도 35 / 35\n[q2]사용 효과: 20초 동안 달리기 속도를 비약적으로 증가시켜주는 위험해 보이는 장화입니다. 사용 중 폭발할 수 있으니 주의를 요합니다. (5 분 재사용 대기시간)\n검은 마법매듭 장화 , 미스릴관 (2), 질긴 가죽 (4), 고블린 로켓 연료 (2), 유동성 제동장치 필요"},
[221340] = {name = "[q2]설계도: 고블린 폭탄 자판기", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과:\n\n\n고블린 폭탄 자판기\n획득 시 귀속\n장신구\n기계공학 (230) 필요\n[q2]사용 효과: 주위의 적에게 돌진하여 315 에서 385의 화염 피해를 주는 꼬마 폭탄을 만들어 냅니다. (30 분 재사용 대기시간)\n미스릴 형틀 (2), 조밀한 화약 (4), 진은 주괴 (6), 유동성 제동장치 , 정밀한 조준경 (2) 필요"},
[221341] = {name = "[q2]설계도: 왕폭탄", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과:\n\n\n왕폭탄\n기계공학 (225) 필요\n[q2]사용 효과: 10미터 반경에 340 에서 460의 화염 피해를 입히고 대상을 5초 동안 기절시킵니다. 대상이 피해를 입게 되면 효과가 사라집니다. (1 분 재사용 대기시간)\n미스릴 형틀 , 고블린 로켓 연료 , 조밀한 다이너마이트 (6), 유동성 제동장치 필요"},
[221342] = {name = "[q2]설계도: 고블린 용화포", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과:\n\n\n고블린 용기총\n획득 시 귀속\n장신구\n[q2]사용 효과: 사용 중 폭발하지만 않는다면, 사용자 전방의 모든 적에게 10초 동안 61 에서 69의 화염 피해를 입힙니다. (5 분 재사용 대기시간)\n미스릴관 (2), 고블린 로켓 연료 (4), 미스릴 주괴 (6), 진은 주괴 (6), 유동성 제동장치 필요"},
[221343] = {name = "[q2]설계도: 고블린 로켓 헬멧", additional_info = "획득 시 귀속\n기계공학 (205) 필요\n[q2]사용 효과:\n\n\n[q2]고블린 로켓 헬멧\n착용 시 귀속\n{머리} {천}\n방어도 50\n체력 +15\n내구도 45 / 45\n기계공학 (235) 필요\n[q2]사용 효과: 적에게 돌격하여 30초 동안 어리둥절하게 만듭니다. 자신도 짧은 시간 동안 기절 상태가 됩니다. 대상이 피해를 받으면 깨어납니다. (20 분 재사용 대기시간)\n고블린 안전모 , 고블린 로켓 연료 (4), 미스릴 주괴 (4), 유동성 제동장치 필요"},
[221344] = {name = "[q3]전용 마법책", additional_info = "획득 시 귀속\n고유 아이템\n보조장비\n직업: 마법사\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 21만큼 증가합니다.\n[q2]사용 효과: 이해의 부적 5개를 창조합니다. (4 시간 재사용 대기시간)"},
[221345] = {name = "[q3]에라니쿠스의 오염된 피", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 50"},
