[221369] = {name = "[q3]악몽 착취", additional_info = "획득 시 귀속\n장신구\n요구 레벨 20\n에메랄드 감시자\n- 약간 우호적 필요\n[q2]착용 효과: 적을 처치하고 경험치나 명예 점수를 얻으면 150의 생명력과 마나를 회복합니다. 이 효과는 10초마다 최대 1번씩만 발동될 수 있습니다. (10초 재사용 대기시간)"},
[221370] = {name = "소중한 메달", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"뒷면에 '재비 + 에니'라고 새겨져 있습니다.\""},
