[221459] = {name = "[q4]희생양의 인장", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n손가락\n체력 +14\n지능 +6\n직업: 사제\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 20만큼 증가합니다."},
[221460] = {name = "[q4]구루바시 기습용 단검", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{한손 장비} {단검}\n{공격력 51 - 94 } {속도 1.80}\n(초당 공격력 40.28)\n체력 +7\n내구도 75 / 75\n직업: 도적\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다."},
[221461] = {name = "[q2]전쟁의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]팔보호구에 살육자 룬을 새깁니다.\n\n\n능력 사용 시 자신의 출혈 효과에 걸린 대상에게 15%의 추가 피해를 입힙니다. 추가로 파열이 입힌 피해의 40%만큼 생명력을 회복시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221462] = {name = "[q4]피투성이 신속검", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{한손 장비} {검}\n{공격력 48 - 89 } {속도 1.70}\n(초당 공격력 40.29)\n민첩성 +8\n체력 +8\n내구도 105 / 105\n직업: 도적\n요구 레벨 50\n[q2]발동 효과: 10초 동안 달리기 속도가 40%만큼 증가합니다."},
[221463] = {name = "[q4]선조의 부두 인형", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n장신구\n체력 +8\n직업: 주술사\n요구 레벨 50\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 29만큼 증가합니다.\n[q2]착용 효과: 매 5초마다 7의 마나가 회복됩니다."},
[221464] = {name = "[q4]불타는 정확성의 토템", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n성물\n내구도 120 / 120\n직업: 주술사\n요구 레벨 50\n[q2]착용 효과: 화염 충격의 사정거리가 5미터만큼 증가합니다."},
[221465] = {name = "[q4]오염된 난타인도자", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{양손 장비} {둔기}\n{공격력 150 - 226 } {속도 3.60}\n(초당 공격력 52.22)\n힘 +15\n체력 +28\n지능 +6\n내구도 120 / 120\n직업: 주술사\n요구 레벨 50\n[q2]발동 효과: 2초 동안 대상을 기절시킵니다."},
[221466] = {name = "[q4]불타는 피의 실반지", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n손가락\n체력 +14\n지능 +4\n직업: 흑마법사\n요구 레벨 50\n[q2]착용 효과: 화염 계열의 주문과 효과의 공격력이 최대 17만큼 증가합니다."},
[221467] = {name = "[q4]피의 달의 눈", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n손가락\n체력 +14\n지능 +4\n직업: 흑마법사\n요구 레벨 50\n[q2]착용 효과: 암흑 계열의 주문과 효과의 공격력이 최대 17만큼 증가합니다."},
[221468] = {name = "[q4]속삭임의 벽", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{보조장비} {방패}\n방어도 1902\n34의 피해 방어\n체력 +6\n내구도 120 / 120\n직업: 전사\n요구 레벨 50\n[q2]착용 효과: 해로운 주문에 적중 당했을 때 5%의 확률로 해당 주문의 시전자는 3초 동안 침묵에 걸리게 됩니다. (효과 발동 확률: 5%, 20초 재사용 대기시간)"},
[221469] = {name = "[q4]인간사냥꾼의 가시 돋힌 창", additional_info = "획득 시 귀속\n고유 장착 아이템: [Blood Moon] (1)\n{투척} 무기} {투척}\n{공격력 70 - 130 } {속도 3.00}\n(초당 공격력 33.33)\n직업: 전사\n요구 레벨 50\n[q2]사용 효과: 대상에게 창을 던져 5초 동안 이동 불가 상태로 만듭니다. (5 분 재사용 대기시간)"},
[221470] = {name = "[q3]꿈 에메랄드", additional_info = nil},
[221471] = {name = "[q2]에메랄드 감시자 보관함", additional_info = "획득 시 귀속\n[q2]<열려면 마우스 오른쪽 클릭>"},
[221473] = {name = "[q2]망꾼의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]투구에 경계 룬을 새깁니다.\n\n\n파티원이나 공격대원에게 보호의 시선을 집중시켜 대상이 받는 피해를 3%만큼 감소시키고 생성되는 위협 수준의 10%만큼을 자신에게 이전시킵니다. 추가로 대상이 공격을 받을 때마다 도발의 재사용 대기시간이 초기화됩니다. 30분 동안 지속됩니다. 동시에 하나의 대상에게만 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221474] = {name = "[q3]속박된 에라니쿠스의 정수", additional_info = "획득 시 귀속\n장신구\n체력 +10\n자연 저항력 +10\n요구 레벨 50\n[q2]사용 효과: 시전자 주위 8미터 반경 내의 모든 적을 중독시킵니다. 중독된 적은 45초 동안 매 5초마다 50의 자연 피해를 입습니다. (10 분 재사용 대기시간)"},
[221475] = {name = "[q2]에라니쿠스의 정수", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 50\n[q]\"보석 표변을 따라 녹색 안개 같은 것이 흐르고 있습니다.\""},
[221480] = {name = "[q2]주문 기록: 타오르는 갑옷", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]팔보호구에 타오르는 갑옷 룬을 새깁니다.\n\n\n가격 당했을 때 공격자에게 [10 / 100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60)]의 화염 피해를 입히고 주문 극대화율이 5%만큼 증가하며 치명타 공격에 적중 당할 확률이 5%만큼 감소합니다. 마법사의 갑옷 주문은 동시에 한 종류만 사용할 수 있습니다. 30분 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221481] = {name = "[q2]허무주의적 현신", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]팔보호구에 공허의 지대 룬을 새깁니다.\n\n\n대상 지역에 공허의 지대를 소환하여 안에 서 있는 적에게 10초 동안 1초마다 [(9.456667 + 0.635108 * 60 + 0.039063 * 60 * 60) * 51 / 100]의 암흑 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221482] = {name = "[q2]고통의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]팔보호구에 불안정한 고통 룬을 새깁니다.\n\n\n어둠의 기운이 천천히 대상을 파괴하여 18초에 걸쳐 [242 * 6 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100]의 피해를 입힙니다. 추가로, 누군가가 불안정한 고통을 무효화할 경우 해당 시전자는 [242 * 227 / 100 * (6.568597 + 0.672028 * 60 + 0.031721 * 60 * 60) / 100]의 피해를 입고 5초 동안 침묵 상태가 됩니다. 흑마법사마다 한 대상에 하나의 불안정한 고통 또는 제물을 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221483] = {name = "[q2]불사르기의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]투구에 태우기 룬을 새깁니다.\n\n\n화염 충격이 최대 5명의 대상을 가격합니다. 지속시간이 6초만큼, 공격력이 100%만큼 증가합니다. 추가로 장착한 주 무기에 불꽃의 무기가 주입된 동안 주문 공격력이 지능의 150%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221484] = {name = "[q4]의술사의 사술 막대", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 자신에게 사술을 걸어 가라앉은 사원에서 감지하기 어렵게 합니다. (3 초 재사용 대기시간)"},
[221487] = {name = "[q2]주문 기록: 고급 수호물", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]투구에 고급 수호물 룬을 새깁니다.\n\n\n마나 보호막, 냉기계 수호, 화염계 수호 주문을 아군 대상에게 시전할 수 있으며 피해 흡수량이 100%만큼 증가합니다. 또한 마나 보호막이 흡수한 피해당 소모하는 마나가 50%만큼 감소합니다. 추가로 하급 저주 해제가 상급 저주 해제로 대체됩니다.\n\n\n아군 대상에게 걸린 저주 1개와 해로운 마법 효과 1개를 제거합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221488] = {name = "[q2]결의의 현신", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]투구에 신의 보호 룬을 새깁니다.\n\n\n치유 주문이 극대화 효과를 발휘하면 대상에 보호막이 생성되어 치유된 생명력의 30%에 해당하는 피해를 흡수합니다. 12초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221489] = {name = "[q2]복수의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]투구에 복수 룬을 새깁니다.\n\n\n활성화되면 일시적으로 최대 생명력이 30%만큼 증가합니다. 20초 동안 지속되며 지속시간이 끝나면 임시 생명력은 사라집니다. 추가로 탈태 상태일 때 복수의 효과로 날개가 낙하 속도를 감소시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221490] = {name = "[q2]성난 해일의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]팔보호구에 성난 해일 룬을 새깁니다.\n\n\n아군 대상의 생명력을 [57 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]에서 [63 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]만큼 치유하고, 추가로 15초에 걸쳐 [5 * 12 / 100 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60)]의 생명력을 회복시킵니다. 15초 안에 주 대상에게 연쇄 치유 시전 시 연쇄 치유의 치유량이 25%만큼 증가합니다. 추가로 이 주문은 고대의 각성을 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221491] = {name = "[q2]어둠이빨 배낭", additional_info = "획득 시 귀속\n[q]\"무작위 다크문 카드가 들어 있습니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[221497] = {name = "오래된 열쇠", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]사용 효과: 오래된 상자를 엽니다."},
[221498] = {name = "튼튼한 도시락", additional_info = "획득 시 귀속\n12칸 가방"},
[221499] = {name = "[q2]지옥수호병의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]팔보호구에 지옥수호병 소환 룬을 새깁니다.\n\n\n흑마법사의 명령에 복종하는 지옥수호병을 소환합니다.\n\n 지옥수호병은 다른 악마 하수인이 발동시키거나 적용되는 모든 특성 및 이로운 효과를 받습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221510] = {name = "[q2]기사의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]팔보호구에 검과 방패 룬을 새깁니다.\n\n\n압도 및 복수 능력으로 피해를 입혔을 때 30%의 확률로 방패 밀쳐내기의 재사용 대기시간이 초기화되고 5초 동안 분노 소비량이 100%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221511] = {name = "[q2]수호자의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]투구에 방패 숙련 룬을 새깁니다.\n\n\n방패를 착용한 동안 모든 물리 공격력이 10%만큼 증가하고 모든 무장 해제 효과의 지속시간이 50%만큼 감소합니다. 다른 무장 해제 지속시간 감소 효과와 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221512] = {name = "[q2]기민함의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]팔보호구에 신속한 결말 룬을 새깁니다.\n\n\n절개 및 독살 능력 사용 시 난도질 또는 칼춤의 지속시간이 연계 점수 5점을 최대로 사용한 것과 같은 지속시간으로 갱신됩니다. 난도질과 칼춤 모두 활성화되어 있을 경우, 남은 지속시간이 가장 짧은 효과 하나만 갱신됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221513] = {name = "[q2]잠재력의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]투구에 전투 능력 룬을 새깁니다.\n\n\n보조 무기로 근접 피해를 입힐 때마다 20%의 확률로 15의 기력을 생성합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221514] = {name = "[q2]화력의 룬", additional_info = "획득 시 귀속\n직업: 사냥꾼\n[q2]투구에 실탄 장전 룬을 새깁니다.\n\n\n덫을 놓을 때마다 20초 안에 사용하는 분산 사격을 제외한 다음 사격 능력이 마나를 소모하지 않고 재사용 대기시간을 발생시키지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221515] = {name = "[q2]폭파의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]팔보호구에 강력한 폭탄 룬을 새깁니다.\n\n\n폭발 사격과 모든 공격 덫의 공격력이 10%만큼 증가합니다. 추가로 폭발 덫의 최초 피해와 제물의 덫의 총 주기적인 피해가 근접 또는 원거리 전투력의 25%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221516] = {name = "[q2]원시 힘의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]팔보호구에 광포한 재생력 연마 룬을 새깁니다.\n\n\n광포한 재생력을 달빛야수 변신을 제외한 모든 변신 형태에서 혹은 변신 중이지 않을 때도 사용할 수 있습니다. 또한 10초 동안 1초마다 활성화된 자원을 생명력으로 전환합니다. 최대 10의 분노, 10의 기력 또는 20%의 기본 마나가 1초마다 최대 10%의 생명력으로 전환됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221517] = {name = "[q2]유혈의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]투구에 꿰뚫기 룬을 새깁니다.\n\n\n가르기, 휘둘러치기, 후려갈기기로 대상 공격 시 15%의 확률로 짓이기기 (곰)의 재사용 대기시간이 초기화되고 10의 분노를 생성합니다. 짓이기기 (표범) 또는 칼날 발톱으로 대상을 공격하면 15%의 확률로 호랑이의 분노의 재사용 대기시간이 초기화됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[221518] = {name = "[q3]휘파람", additional_info = "획득 시 귀속\n{양손 장비} {둔기}\n{공격력 109 - 163 } {속도 2.60}\n(초당 공격력 52.31)\n힘 +20\n체력 +12\n내구도 100 / 100\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다."},
[221519] = {name = "[q3]만노로크 보주", additional_info = "퀘스트 아이템\n고유 아이템"},
[221544] = {name = "폭풍까마귀 알", additional_info = "획득 시 귀속\n고유 아이템"},
[221545] = {name = "해독된 흑마법사 기록", additional_info = "고유 아이템\n직업: 사제 , 주술사"},
[221547] = {name = "암호화된 흑마법사 기록", additional_info = "고유 아이템\n[q2]사용 효과: 흑마법사의 기록을 이해하려면 암호가 필요합니다. 어떤 마법이 담겨 있을지 누가 알겠습니까?"},
[221549] = {name = "사막유랑단 암호", additional_info = "[q]\"사막유랑단 약탈자가 쓴 문서 번역에 유용하게 사용할 수 있습니다.\""},
[221780] = {name = "[q3]공주 테라드라스의 홀", additional_info = "획득 시 귀속\n{양손 장비} {둔기}\n{공격력 111 - 174 } {속도 3.40}\n(초당 공격력 41.91)\n방어도 90\n힘 +13\n민첩성 +10\n체력 +15\n정신력 +9\n내구도 100 / 100\n요구 레벨 46\n[q2]착용 효과: 표범, 곰, 광포한 곰 변신 상태일 때 전투력이 67만큼 증가합니다."},
[221781] = {name = "[q3]아방가드 투구", additional_info = "획득 시 귀속\n{머리} {판금}\n방어도 469\n힘 +10\n민첩성 +5\n체력 +25\n내구도 80 / 80"},
[221782] = {name = "[q3]추방자의 투구", additional_info = "획득 시 귀속\n{머리} {사슬}\n방어도 266\n민첩성 +11\n지능 +18\n내구도 70 / 70\n[q2]착용 효과: 전투력 +36"},
[221783] = {name = "[q4]집행의 어깨갑옷", additional_info = "획득 시 귀속\n{어깨} {판금}\n방어도 562\n힘 +17\n체력 +15\n화염 저항력 +7\n내구도 100 / 100\n직업: 성기사\n요구 레벨 60\n[q2]착용 효과: 신성 계열의 주문과 효과의 공격력이 최대 21만큼 증가합니다.\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n\n[q]집행의 광휘 (0/8)\n[q0]집행의 전투장화\n집행의 가슴보호갑\n집행의 왕관\n집행의 요대\n집행의 손장갑\n집행의 다리보호구\n집행의 어깨갑옷\n집행의 전투손목띠\n[q0](2) 세트 : 빛의 심판 및 지혜의 심판 시전 시 추가로 성전사의 판결 효과를 부여합니다.\n(4) 세트 : 주문 및 공격의 치명타 및 극대화율이 2%만큼 증가합니다.\n(6) 세트 : 다른 문장을 시전한 후 혹은 세 번째 문장을 시전할 때까지 지휘의 문장과 정의의 문장, 헌신의 문장, 햇살의 공격력이 35%만큼 감소하지만 6초 동안 지속됩니다. 여러 문장이 활성화되어 있을 경우, 심판이 다수의 문장을 발동시킵니다."},
[221785] = {name = "[q0]세나리온 예복", additional_info = "획득 시 귀속\n{가슴} {가죽}\n방어도 200\n체력 +11\n지능 +17\n정신력 +15\n화염 저항력 +10\n내구도 120 / 120\n직업: 드루이드\n요구 레벨 60\n[q2]착용 효과: 모든 주문 및 효과에 의한 치유량이 최대 62만큼 증가합니다.\n\n[q]세나리온 은혜 (0/8)\n[q0]세나리온 허리띠\n세나리온 장화\n세나리온 팔보호구\n세나리온 장갑\n세나리온 투구\n세나리온 다리보호구\n세나리온 어깨갑옷\n세나리온 예복\n[q0](2) 세트 : 다른 플레이어에게 정신 자극 시전 시 자신에게도 시전합니다.\n(4) 세트 : 치유의 손길 또는 육성 시전 시 25%의 확률로 해당 주문 기본 마나 소모량의 35%에 해당하는 마나를 회복합니다. (효과 발동 확률: 25%, 1초 재사용 대기시간)\n(6) 세트 : 평온의 재사용 대기시간이 100%만큼 감소하고 치유량은 100%만큼 증가합니다. (효과 발동 확률: 25%, 1초 재사용 대기시간)"},
[221971] = {name = "[q2]꿈서약 뿔", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 수집한 재료를 결합해 새로운 각인술 주문을 배울 수 있는 룬을 만듭니다.\n[q]\"불의 정수가 깃든 독특한 재료입니다. 다른 비슷한 재료를 찾아 새로운 룬을 만들 수 있습니다.\""},
[221972] = {name = "[q2]꿈장작 불꽃", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 수집한 재료를 결합해 새로운 각인술 주문을 배울 수 있는 룬을 만듭니다.\n[q]\"불의 정수가 깃든 독특한 재료입니다. 다른 비슷한 재료를 찾아 새로운 룬을 만들 수 있습니다.\""},
[221973] = {name = "[q2]꿈사냥꾼 송곳니", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 수집한 재료를 결합해 새로운 각인술 주문을 배울 수 있는 룬을 만듭니다.\n[q]\"불의 정수가 깃든 독특한 재료입니다. 다른 비슷한 재료를 찾아 새로운 룬을 만들 수 있습니다.\""},
[221974] = {name = "[q2]그림토템 목걸이", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 수집한 재료를 결합해 불사의 잠을 끝낼 수 있는 취약한 지팡이를 만듭니다.\n[q]\"감염된 그림토템 주술사에게서 입수한 목걸이입니다.\""},
[221975] = {name = "[q2]부서진 덩굴발일족 지팡이", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 수집한 재료를 결합해 불사의 잠을 끝낼 수 있는 취약한 지팡이를 만듭니다.\n[q]\"감염된 덩굴발 비술사에게서 입수한 지팡이 일부입니다.\""},
[221976] = {name = "[q2]감염된 자연의 지팡이", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 현재 대상을 불사의 잠에서 깨웁니다.\n[q]\"간신히 형체를 유지 중인 지팡이입니다. 그래도 이 안에 깃든 고대 마법이 쓸모가 있을지도 모릅니다.\""},
[221978] = {name = "탐험가의 영혼", additional_info = "획득 시 귀속\n고유 아이템\n[q2]탐험가 임프를 소환합니다. 탐험가 임프는 싸우는 재주는 없지만 다른 세계로 통하는 차원문에 들어가 보물을 가져옵니다.\n[q]\"탐험가 임프 소환하는 법을 배웁니다.\""},
[221979] = {name = "[q2]푸른 겨울의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]투구에 고통과 고뇌 룬을 새깁니다.\n\n\n정신 분열, 정신의 쐐기, 정신의 채찍 시전 시 대상에게 걸린 어둠의 권능: 고통, 공허의 역병 또는 흡혈의 손길 능력의 지속시간이 최대 지속시간으로 갱신됩니다. 남은 지속시간이 가장 짧은 능력이 항상 갱신됩니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[221980] = {name = "[q2]깨어난 혼돈의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]투구에 공허의 눈 룬을 새깁니다.\n\n\n공허의 눈을 불러내 30초 동안 전투를 돕게 합니다. 눈은 대상에게 여러 저주를 겁니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[221981] = {name = "[q2]잊힌 부족의 예언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]팔보호구에 빛의 쇄도 룬을 새깁니다.\n\n\n주문이 치명타 및 극대화 효과를 발휘하면 다음 15초 내로 사용하는 성스러운 일격 또는 순간 치유가 즉시 시전됩니다.\n[q2]사용 효과: 예언에 집중해 새로운 주문을 배웁니다. 아제로스의 두 영적인 수수께끼에 관해 명상해 정신을 집중한 상태여야 합니다."},
[222952] = {name = "[q4]안식 없는 꿈의 영약", additional_info = "획득 시 귀속\n요구 레벨 50\n연금술 (250) 필요\n{[q2]사용 효과: 1시간 동안 주문의 공격력}이 최대 30만큼, 치유량이 최대 45만큼, 마나 회복 {속도가 5초당 마나 12만큼 증가합니다. 이 영약은 악몽의 영향을 받는 지역에서만 효과를 발휘합니다. (30 초 재사용 대기시간)}\n[q]\"아무리 들이켜도 바닥이 보이지 않는 듯합니다.\""},
[222962] = {name = "하이잘의 지혜", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 새로운 각인술 능력을 배웁니다."},
[223073] = {name = "[q0]상급기사의 쇠사슬 견장", additional_info = "획득 시 귀속\n{어깨} {사슬}\n방어도 246\n힘 +9\n체력 +11\n지능 +5\n내구도 70 / 70\n직업: 사냥꾼 , 주술사\n요구 레벨 50\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n\n[q]상급기사의 쇠사슬 방어구 (0/6)\n[q0]기사의 쇠사슬 갑옷\n하급기사의 쇠사슬 발덮개\n하급기사의 쇠사슬 건틀릿\n상급기사의 쇠사슬 보호모\n기사의 쇠사슬 다리갑옷\n상급기사의 쇠사슬 견장\n[q0](3) 세트 : 체력 +15\n(6) 세트 : 전투력 +30"},
