[225675] = {name = "숯검댕이 흑요석 핵", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 검댕을 닦아냅니다."},
[225676] = {name = "불타는 흑요석 핵", additional_info = "획득 시 귀속\n고유 아이템\n지속 시간: 10 분 (현실 시간)\n[q]\"녹기 전에 냉각해야 합니다!\""},
[225686] = {name = "[q2]죽음의 예언의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]장화에 죽음의 예언 룬을 새깁니다.\n\n\n영혼의 불꽃 주문의 재사용 대기시간이 사라집니다. 추가로 어둠의 화살, 어둠의 회전베기, 소각 또는 영혼의 불꽃으로 생명력이 35% 이하인 대상에게 적중하면 10초 동안 영혼의 불꽃 주문의 시전 시간이 40%만큼 감소합니다. 죽음의 예언 효과가 활성화되어 있는 동안에는 영혼의 불꽃 시전 시 영혼의 조각을 소모하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225687] = {name = "[q2]지옥불 갑옷의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]망토에 지옥불 갑옷 룬을 새깁니다\n\n\n영혼에 악마의 마력이 주입되어 받는 모든 마법 피해가 방어도에 따른 받는 물리 피해 감소 효과의 60%만큼 감소합니다. 10초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225688] = {name = "[q2]혼돈의 징표의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]망토에 혼돈의 징표 룬을 새깁니다.\n\n\n어둠의 저주 및 원소의 저주를 제외한 모든 저주 주문이 혼돈의 징표를 부여해 대상의 비전, 화염, 냉기, 자연, 암흑 저항력을 [최대(최소( 56 + 19, 75), 27)]만큼 감소시키고 저주가 지속되는 동안 해당 계열 주문으로 받는 피해를 [최대(최소(( 56 - 8) * 0.125 + 4, 10), 4)]%만큼 증가시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225689] = {name = "[q2]주문 기록: 비전 탄막", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]망토에 비전 탄막 룬을 새깁니다.\n\n\n적 대상에게 여러 투사체를 발사하여 [(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 358 / 100]~[(13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) * 438 / 100]의 비전 피해를 입힙니다. 이 주문은 추가로 25%의 확률로 화살 탄막을 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225690] = {name = "[q2]주문 기록: 얼어붙은 구슬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]망토에 얼어붙은 구슬\n 룬을 새깁니다\n\n\n16초에 걸쳐 빠르게 전방으로 이동하는 휘몰아치는 얼음의 보주를 발사합니다. 보주는 이동하는 동안 1초마다 통과하는 모든 적에게 [90 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ]의 냉기 피해를 입히고 한기를 부여해 이동 속도를 30%만큼 감소시킵니다. 처음으로 적에게 피해를 입히면 보주의 이동 속도가 감소하고 100%의 확률로 서리의 손가락 룬을 발동시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225691] = {name = "[q2]주문 기록: 과열", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]망토에 과열 룬을 새깁니다.\n\n\n화염 작렬이 항상 극대화 효과를 발휘하고 다른 주문을 시전할 때 시전 가능합니다. 전역 재사용 대기시간에 영향을 받지 않지만, 재사용 대기시간이 15초로 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225740] = {name = "[q2]평정의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]망토에 일관성 룬을 새깁니다.\n\n\n연쇄 치유의 효과가 전달될 때마다 35%만큼만, 연쇄 번개의 효과는 전달될 때마다 20%만큼만 감소합니다. 또한 추가로 1명의 대상에게 전달됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225838] = {name = "[q2]전압의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {토템}\n직업: 주술사\n[q2]망토에 폭풍과 대지와 불 룬을 새깁니다\n\n\n연쇄 번개의 재사용 대기시간이 25%만큼 감소하고, 속박의 토템 시전 시 5초 동안 대상을 이동 불가 상태로 만들며 화염 충격의 주기적인 피해가 60%만큼 증가합니다.\n[q]\"연쇄 번개를 한 번 시전하여 적 3명을 처치하면 새로운 능력을 배웁니다.\""},
[225893] = {name = "[q4]시대의 끝", additional_info = "획득 시 귀속\n고유 아이템: (알 수 없음 #636) (0)\n{양손 장비} {검}\n{공격력 300 - 415 } {속도 4.20}\n(초당 공격력 85.12)\n체력 -322\n내구도 120 / 120\n요구 레벨 77"},
[225914] = {name = "[q2]속박된 영혼의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]망토에 야수 정령 룬을 새깁니다\n\n\n주술사가 부릴 수 있는 늑대 정령 2마리를 소환합니다. 45초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[225929] = {name = "역병에 물든 영혼의 조각", additional_info = "획득 시 귀속\n고유 아이템 (3)"},
