[225942] = {name = "오염된 멧돼지 고기", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 수액으로 뒤덮였습니다.\n[q]\"소스가 필요하겠네요.\""},
[225943] = {name = "톡 쏘는 살덩어리", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: ???\n[q]\"아무리 저열한 청소부라도 토하게 만듭니다.\""},
[225954] = {name = "[q2]그슬린 주문 기록", additional_info = "획득 시 귀속\n직업: 마법사\n[q]\"찢기고 불에 그슬린 책장입니다. 원래는 각인술 능력에 관한 신비한 비밀이 적혀 있었지만, 이젠 불타서 사용이 불가능할 지경입니다.\""},
[225955] = {name = "[q2]수완의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]망토에 뛰어난 계략 룬을 새깁니다\n\n\n덫의 마나 소모량이 100%만큼, 재사용 대기시간이 40%만큼 감소합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226122] = {name = "[q3]돌턴의 뿔피리", additional_info = "획득 시 귀속\n고유 아이템\n성물\n요구 레벨 50\n[q2]사용 효과: 돌턴의 뿔피리를 불러 종자를 소환합니다. 종자는 전투를 도우며, 함께 모험을 하면서 성장합니다. (효과 발동 확률: 3%) (15 초 재사용 대기시간)\n[q]\"야자는 따로 구해야 합니다.\""},
[226201] = {name = "종자 쿠스베르트의 검", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"찌그러지고 이가 빠졌지만 균형감이 좋은 검입니다.\""},
