[226252] = {name = "[q2]유격전의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]망토에 치고 빠지기 룬을 새깁니다\n\n\n랩터의 일격 사용 후 15초 동안 이동 속도가 30%만큼 증가합니다.\n\n 야수의 공격 능력이 대상을 광기 증폭 상태로 만들어 2분 동안 근접 전투력을 91만큼 증가시키지만 방어도를 640만큼 감소시킵니다. 광기 증폭에 걸린 적은 도망치지 않으며 겁이나 공포 효과를 무시합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226374] = {name = "사술 독 I", additional_info = "직업: 도적\n요구 레벨 54\n[q2]사용 효과: 무기에 30분 동안 유지되는 독을 바릅니다. 매 공격 시 30%의 확률로 적을 중독시켜 12초에 걸쳐 108의 자연 피해를 입히고 비전, 화염, 냉기, 자연, 암흑 공격으로 받는 피해를 4%만큼 증가시킵니다. 효과는 대상마다 최대 5번까지 중첩됩니다.\n\n 사술 독은 맹독으로 간주되며 맹독으로 발동하거나 맹독의 효과를 변경하는 모든 특성 및 효과가 적용됩니다. (효과 발동 확률: 30%)"},
[226394] = {name = "[q2]위축의 독 설명서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]무기에 30분 동안 유지되는 독을 바릅니다.\n 매 공격 시 30%의 확률로 적을 중독시켜 15초 동안 적의 근접 전투력을 205만큼 감소시킵니다. 105회 사용 가능.\n[q]\"위축의 독을 배웁니다.\""},
[226395] = {name = "[q2]마취 독 설명서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]무기에 30분 동안 유지되는 독을 바릅니다.\n 매 공격 시 30%의 확률로 적을 중독시켜 15초 동안 적의 근접 공격 간격을 20%만큼 증가시킵니다. 105회 사용 가능.\n[q]\"마취 독을 배웁니다.\""},
[226396] = {name = "[q2]사술 독 설명서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]무기에 30분 동안 유지되는 독을 바릅니다.\n 매 공격 시 30%의 확률로 적을 중독시켜 12초에 걸쳐 108의 자연 피해를 입히고 비전, 화염, 냉기, 자연, 암흑 공격으로 받는 피해를 4%만큼 증가시킵니다. 효과는 대상마다 최대 5번까지 중첩됩니다.\n\n 사술 독은 맹독으로 간주되며 맹독으로 발동하거나 맹독의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"사술 독을 배웁니다.\""},
[226397] = {name = "[q2]피지선 독 설명서", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]무기에 30분 동안 유지되는 독을 바릅니다.\n 매 공격 시 30%의 확률로 적을 중독시켜 15초 동안 방어도를 1700만큼 감소시킵니다. 105회 사용 가능.\n\n 피부 독은 약점 노출 연마 특성의 이로운 효과를 받습니다.\n[q]\"피지선 독을 배웁니다.\""},
[226398] = {name = "[q2]헌신의 증언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]30초 동안 성령으로 충만해져 근접 공격 시 대상에게 무기 공격력의 50%에 해당하는 피해를 입히지만, 입힌 피해의 10%에 해당하는 생명력을 잃습니다. 이 문장이 활성화된 동안 40미터 내의 파티원과 공격대원은 시전자가 이 문장으로 받은 피해의 65%에 해당하는 마나를 회복합니다.\n\n 문장의 마력을 방출하면 적을 심판하여 즉시 85%의 무기 피해를 입히고, 입힌 피해의 10%에 해당하는 생명력을 대가로 잃습니다.\n\n 이 능력으로 발동하는 문장 및 심판 효과에는 정의의 문장 또는 정의의 심판의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"헌신의 문장을 배웁니다.\""},
[226399] = {name = "[q2]응징의 격노의 증언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n요구 레벨 25\n[q2]20초 동안 모든 공격력과 치유량이 20%만큼 증가합니다. 참을성이 발동하며 참을성이 활성화된 동안에는 사용할 수 없습니다.\n[q]\"응징의 격노를 배웁니다.\""},
[226400] = {name = "[q2]퇴마사의 증언", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]퇴마를 모든 대상에게 시전할 수 있습니다. 또한 언데드와 악마에게 치명타 및 극대화 효과를 발휘할 확률이 100%만큼 증가합니다.\n[q]\"퇴마사를 배웁니다.\""},
[226401] = {name = "[q2]사자의 심장 논문", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사냥꾼\n[q2]사냥꾼이 사자의 심장을 일깨웁니다. 주위 모든 아군의 총 능력치가 10%만큼, 전투력은 200만큼, 사냥꾼의 총 능력치는 추가로 10%만큼 증가합니다.\n[q]\"사자의 심장을 배웁니다.\""},
[226402] = {name = "[q2]주술의 분노의 계시", additional_info = "획득 시 귀속\n고유 아이템\n직업: 주술사\n[q2]받는 모든 피해가 20%만큼 감소하고 15초 동안 1초마다 최대 마나의 5%에 해당하는 마나를 회복합니다. 이 방식으로 마나를 회복할 때 자신의 40미터 내에 있는 파티원과 공격대원도 18%만큼 마나를 회복합니다.\n[q]\"주술의 분노를 배웁니다.\""},
[226403] = {name = "[q2]살덩이갈고리 교본", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]갈고리 사슬을 던져 대상을 속박하고 자신에게로 끌어당깁니다. ( 60 + 1) 레벨을 넘거나 우두머리로 지정된 적에게는 사용할 수 없습니다.\n[q]\"살덩이갈고리를 배웁니다.\""},
[226404] = {name = "[q2]빛바랜 언더마인화", additional_info = "획득 시 귀속\n고유 아이템 (250)\n[q]\"점점 유통량이 줄어들고 있는 잃어버린 섬 통화입니다. 그래도 동부 왕국과 칼림도어에서 제법 괜찮은 환율을 자랑합니다.\""},
[226405] = {name = "[q2]손상된 언더마인 보급품 상자", additional_info = "획득 시 귀속\n고유 아이템 (10)\n[q]\"이 찌그러지고 손상된 상자는 말 그대로 비행선에서 떨어진 것처럼 보입니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[226406] = {name = "[q2]도검류 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 성기사 , 사냥꾼 , 도적 , 마법사 , 흑마법사\n[q2]반지에 도검류 전문화 룬을 새깁니다.\n\n\n도검류 및 양손 도검류 숙련도가 5만큼 증가합니다. 이 효과는 종족 추가 효과 또는 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226407] = {name = "[q2]도끼류 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 성기사 , 사냥꾼 , 주술사\n[q2]반지에 도끼류 전문화 룬을 새깁니다.\n\n\n도끼류 및 양손 도끼류 숙련도가 5만큼 증가합니다. 이 효과는 종족 추가 효과 또는 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226408] = {name = "[q2]둔기류 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 성기사 , 도적 , 사제 , 주술사 , 드루이드\n[q2]반지에 둔기류 전문화 룬을 새깁니다.\n\n\n둔기류 및 양손 둔기류 숙련도가 5만큼 증가합니다. 이 효과는 종족 추가 효과 또는 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226409] = {name = "[q2]단검류 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 사냥꾼 , 도적 , 사제 , 주술사 , 마법사 , 흑마법사 , 드루이드\n[q2]반지에 단검류 전문화 룬을 새깁니다.\n\n\n단검류 숙련도가 5만큼 증가합니다. 이 효과는 종족 추가 효과 또는 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226410] = {name = "[q2]원거리 무기류 전문화의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사 , 사냥꾼 , 도적\n[q2]반지에 원거리 무기 전문화 룬을 새깁니다.\n\n\n활류, 총기류, 석궁류, 투척 무기류 숙련도가 5만큼 증가합니다. 이 효과는 종족 추가 효과 또는 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
