[226472] = {name = "스트라솔름 어둠 단지", additional_info = "획득 시 귀속\n고유 아이템\n[q2]사용 효과: 강력한 스트라솔름 주민의 메아리를 사로잡습니다. 시체에만 사용할 수 있습니다."},
