[226678] = {name = "[q4]흉조 및 전투 선견지명", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]망토에 충격파\n 룬을 새깁니다\n\n\n충격의 파장을 내보내 전방 10미터 안에 있는 일정한 반경 내의 모든 적 대상에게 (50 / 100 * 전투력)의 피해를 입히고 4초 동안 기절시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226679] = {name = "[q3]영원한 방랑자의 통찰", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]망토에 급살 룬을 새깁니다\n\n\n근접 공격 적중 시 10%의 확률로 급살을 부여합니다. 급살은 대상의 생명력 상태에 상관없이 한 번 마무리 일격을 사용할 수 있도록 합니다. 급살로 마무리 일격이 활성화되면 마무리 일격 사용 후 10의 분노를 유지합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226680] = {name = "[q3]첫 번째 전사의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 전사\n[q2]망토에 신선한 고기\n 룬을 새깁니다\n\n\n피의 갈증, 필사의 일격 또는 방패 밀쳐내기로 대상에게 피해를 입히면 처음에는 100%의 확률로, 이후에는 10%의 확률로 격노하고 격노 상태를 요구하는 능력을 활성화합니다. 또한 12초 동안 물리 공격력이 10%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226694] = {name = "[q2]방어 전문화의 룬", additional_info = "계정 귀속\n고유 아이템\n직업: 전사 , 성기사 , 도적 , 주술사 , 흑마법사 , 드루이드\n[q2]반지에 방어 전문화 룬을 새깁니다.\n\n\n방어 숙련이 25만큼 증가합니다. 다른 반지 룬과 중복 적용되지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[226698] = {name = "수직 복합 수선기", additional_info = "퀘스트 아이템"},
[226699] = {name = "맞춤형 황동 조작 플랜지", additional_info = "퀘스트 아이템\n[q]\"덮개와 절반 크기 나사도 포함되어 있습니다.\""},
