[227444] = {name = "[q2]여사냥꾼의 우상", additional_info = "획득 시 귀속\n고유 아이템\n{성물} {우상}\n직업: 드루이드\n[q2]망토에 휘둘러치기 연마 룬을 새깁니다\n\n\n표범 변신 상태일 때 휘둘러치기가 휘둘러치기 (표범)으로 변화합니다. 곰 변신 상태일 때 휘둘러치기 사용 시 최대 7명의 추가 적을 가격합니다.\n\n 휘둘러치기 (표범)\n\n주위 적들을 휘둘러 공격하여 무기 공격력의 250%에 해당하는 피해를 입히고 현재 대상에게 연계 점수 1점을 생성합니다.\n[q]\"표범 변신 상태로 잠자는 대상 5명을 처치한 다음, 이 우상을 사용하면 새로운 능력을 배웁니다.\""},
[227451] = {name = "전송의 인장", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"테두리를 따라 ' > v ^ < ' 문양이 새겨져 있습니다.\""},
[227454] = {name = "[q4]해일의 실반지", additional_info = "획득 시 귀속\n손가락\n체력 +8\n화염 저항력 +20\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 13만큼 증가합니다."},
[227455] = {name = "[q4]대양의 바람", additional_info = "획득 시 귀속\n손가락\n체력 +8\n화염 저항력 +20\n[q2]착용 효과: 전투력 +22"},
[227456] = {name = "[q2]혈폭풍의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 도적\n[q2]망토에 혈폭풍 룬을 새깁니다.\n\n\n적에게 마무리 일격을 날립니다. 8미터 내의 모든 적을 베어 지속 출혈 효과를 부여합니다. 연계 점수에 따라 지속시간과 공격력이 증가합니다.\n\n 연계 점수 1점: 4초에 걸쳐 (전투력 * 0.30)의 피해\n 연계 점수 2점: 6초에 걸쳐 (전투력 * 0.45)의 피해\n 연계 점수 3점: 8초에 걸쳐 (전투력 * 0.60)의 피해\n 연계 점수 4점: 10초에 걸쳐 (전투력 * 0.75)의 피해\n 연계 점수 5점: 12초에 걸쳐 (전투력 * 0.90)의 피해\n\n 혈폭풍은 파열로 발동하거나 파열의 효과를 변경하는 모든 특성 및 효과가 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[227530] = {name = "[q4]빛나는 허리띠", additional_info = "획득 시 귀속\n직업: 사제 , 마법사 , 흑마법사\n요구 레벨 60"},
