[227746] = {name = "[q2]세계수의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]망토에 생명의 나무 룬을 새깁니다\n\n\n생명의 나무로 변신합니다. 이 형상으로 변신한 동안에는 45미터 내 모든 파티원이 받는 치유 효과가 10%만큼 증가하고, 급속 성장의 치유량이 60%만큼 증가합니다. 또한 지속 치유 주문의 자원 소모량이 20%만큼 감소하며, 정신력이 25%만큼, 방어도가 200%만큼 증가하고 해로운 주문을 시전하지 못하게 됩니다.\n\n 변신을 하면 변이와 이동 방해 효과에서 벗어날 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[227747] = {name = "가족 기록", additional_info = "획득 시 귀속\n고유 아이템"},
[227748] = {name = "생존자 일지", additional_info = "퀘스트 아이템\n고유 아이템\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[227749] = {name = "[q2]별똥별의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 드루이드\n[q2]망토에 별똥별\n 룬을 새깁니다\n\n\n10초에 걸쳐 하늘에서 질풍과 같은 별똥별을 불러내어 시전자 주위 30미터 이내의 대상을 공격합니다. 별똥별은 각각 대상에게 [46 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]에서 [54 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 비전 피해를 입히고 5미터 내의 다른 모든 적에게는 [8 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100]의 비전 피해를 입힙니다. 최대 20개의 별똥별을 소환합니다.\n\n 동물 형태로 변신을 하거나 탈것에 오르면 효과가 취소됩니다. 제어 불가 효과에 걸리면 별똥별 효과가 중지됩니다.\n\n\n 별똥별은 달빛 섬광에 이롭거나, 해당 주문이 발동시키는 특성 및 효과 대부분이 적용됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
