[232454] = {name = "[q7]야생 신의 문장", additional_info = "계정 귀속\n[q]\"어둠이빨 사절을 도왔음을 입증하는 증거입니다. 대도시 룬 중개상을 찾아가 교환할 수 있습니다.\""},
[232455] = {name = "[q7]불명예의 문장", additional_info = "계정 귀속\n[q]\"일라리 더스크페더와 결판을 냈음을 입증하는 증거입니다. 대도시 룬 중개상을 찾아가 교환할 수 있습니다.\""},
[232456] = {name = "[q7]보랏빛 눈의 문장", additional_info = "계정 귀속\n[q]\"암흑 기수를 상대로 승리를 거두었음을 입증하는 증거입니다. 대도시 룬 중개상을 찾아가 교환할 수 있습니다.\""},
[232457] = {name = "[q7]세계핵의 문장", additional_info = "계정 귀속\n[q]\"지맥 합일점과 동화했음을 입증하는 증거입니다. 대도시 룬 중개상을 찾아가 교환할 수 있습니다.\""},
[232458] = {name = "[q2]성역 연마의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]투구에 성역 연마 룬을 새깁니다.\n\n\n성역의 축복이 방지하는 피해가 100%만큼 증가합니다. 또한 성역의 축복의 공격력이 방패 막기의 20%만큼 증가합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[232459] = {name = "[q2]역류의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]투구에 역류 룬을 새깁니다.\n\n\n점화 능력 사용 시 15초 동안 주문 시전 가속이 30%만큼 증가하고 더는 제물을 소모하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[232460] = {name = "[q2]변위의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]팔보호구에 변위 룬을 새깁니다.\n\n\n점멸을 사용한 출발점으로 다시 돌아가고, 점멸의 재사용 대기시간을 초기화시킵니다. 점멸 시전 후 10초 동안만 사용할 수 있습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[232461] = {name = "[q2]절망의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 사제\n[q2]팔보호구에 절망 룬을 새깁니다.\n\n\n주문으로 인한 주기적인 피해가 치명타 및 극대화 효과를 발휘할 수 있게 되며, 모든 공격 주문이 치명타 및 극대화 효과를 발휘할 때 200%의 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[232462] = {name = "[q2]정화하는 힘의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]팔보호구에 정화의 힘 룬을 새깁니다.\n\n\n퇴마술과 신의 격노의 재사용 대기시간이 50%만큼 감소합니다. 또한 신의 격노를 아무 대상에게 시전할 수 있으며 언데드와 악마 대상을 2초 동안 기절시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
