[232608] = {name = "[q4]용숨결 손대포", additional_info = "암흑불길\n획득 시 귀속\n{원거리 장비} {총}\n{공격력 92 - 172 } {속도 3.00}\n(초당 공격력 44.00)\n민첩성 +14\n체력 +7\n내구도 90 / 90\n요구 레벨 60\n[q2]사용 효과: 손대포를 2.5초 동안 충전해 전방 부채꼴 범위 내의 적에게 500의 화염 피해를 입힙니다. 상당한 위협 수준을 생성합니다. (30 초 재사용 대기시간)"},
[232610] = {name = "주문식: 환상의 트롤광채", additional_info = "획득 시 귀속\n마법부여 (300) 필요\n잔달라 부족\n- 우호적 필요\n[q2]사용 효과: 환상의 트롤광채 만드는 법을 배웁니다.\n환상의 트롤광채\n요구 레벨 45\n[q2]사용 효과: 방패에 부여 시 주문 공격력과 치유량이 최대 36만큼, 주문 치명타 및 극대화율이 1%만큼 증가합니다. 30분 동안 지속됩니다.\n5회 사용 가능\n모조 물약 (3), 왕모조 물약 (3), 눈부신 큰 결정 (2), 마법 약병 필요"},
[232611] = {name = "환상의 트롤광채", additional_info = "요구 레벨 45\n[q2]사용 효과: 방패에 부여 시 주문 공격력과 치유량이 최대 36만큼, 주문 치명타 및 극대화율이 1%만큼 증가합니다. 30분 동안 지속됩니다.\n5회 사용 가능"},
[232652] = {name = "[q4]질라 아마네모다스", additional_info = "획득 시 귀속\n고유 아이템\n직업: 흑마법사\n[q2]사용 효과: 마음속 어둠과 동조하여 내면의 악마를 좀 더 잘 통제할 수 있도록 합니다."},
[233197] = {name = "[q3]은빛 여명회 훈련 교범", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 교범을 사용해 은빛십자군 종자를 불러내 실리시드와의 전투 훈련을 진행합니다. 종자와 함께하는 동안 실리시드를 처치하면 은빛 여명회에 대한 평판이 증가합니다. (5 분 재사용 대기시간)\n3회 사용 가능"},
[233198] = {name = "[q3]여명회의 뿔피리", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 주위의 파티원 또는 공격대원을 결집시켜 주문 극대화율을 10%만큼, 근접 및 원거리 공격 치명타율을 5%만큼, 전투력을 140만큼 증가시킵니다. 2시간 동안 지속됩니다. 비슷한 전역 효과와 겸용해서 사용할 수 없으며 시간축복에 영향을 받지 않습니다. (30 초 재사용 대기시간)"},
[233200] = {name = "[q3]노래꽃 씨앗", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 노래꽃을 소환해 모든 파티원 또는 공격대원의 근접 공격과 원거리 공격, 주문의 치명타 및 극대화율을 5%만큼, 능력치를 15만큼 증가시킵니다. 1시간 동안 지속됩니다. 비슷한 전역 효과와 겸용해서 사용할 수 없습니다. 시간축복에 영향을 받지 않습니다. (30 초 재사용 대기시간)"},
[233201] = {name = "[q3]미명 구체", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 2시간 동안 주위 모든 파티원 또는 공격대원의 전투력을 200만큼, 체력을 15%만큼, 주문 극대화율을 3%만큼 증가시킵니다. 비슷한 전역 효과와 겸용해서 사용할 수 없습니다. 시간축복에 영향을 받지 않습니다. (30 초 재사용 대기시간)"},
[233206] = {name = "[q3]감독관의 모루", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 생명력이 300만큼, 근접 공격 속도가 15%만큼 증가합니다. 매 5초마다 10의 마나가 회복됩니다. 1시간 동안 지속됩니다. (30 초 재사용 대기시간)"},
[233208] = {name = "[q3]\"결함투성이\" 마법의 수정구", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 2시간 동안 모든 파티원 또는 공격대원의 공격력을 10%만큼 증가시킵니다. (30 초 재사용 대기시간)\n[q]\"아무리 세차게 흔들어도 매번 \"고통스러운 죽음\"이라는 불길한 점괘만 나옵니다.\""},
[233209] = {name = "[q3]화주 가마솥", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 10분 동안 화주 가마솥을 소환합니다. 모든 파티원 또는 공격대원이 사용할 수 있으며, 사용 시 1시간 동안 근접 전투력이 35만큼 증가하고 크기가 커집니다. (30 초 재사용 대기시간)"},
[233211] = {name = "[q3]정신의 고둥", additional_info = "획득 시 귀속\n요구 레벨 50\n[q2]사용 효과: 2시간 동안 모든 파티원 또는 공격대원의 이동 속도를 10%만큼, 능력치는 15%만큼 증가시킵니다. (30 초 재사용 대기시간)"},
