[235526] = {name = "[q3]주문식: 손목보호구 마법부여 - 주문 강화", additional_info = "획득 시 귀속\n마법부여 (300) 필요\n[q2]손목보호구에 영구적으로 마법을 부여해 주문의 공격력을 12만큼 증가시킵니다.\n[q]\"손목보호구에 영구적으로 마법을 부여해 주문의 공격력을 12만큼 증가시키는 법을 배웁니다.\""},
[235528] = {name = "[q3]주문식: 손목보호구 마법부여 - 민첩성", additional_info = "획득 시 귀속\n마법부여 (300) 필요\n[q2]손목보호구에 영구적으로 마법을 부여해 민첩성을 9만큼 증가시킵니다.\n[q]\"손목보호구에 영구적으로 마법을 부여해 민첩성을 9만큼 증가시킵니다.\""},
[235529] = {name = "[q3]흑요석 조준경", additional_info = "요구 레벨 60\n[q2]사용 효과: 활이나 총에 영구적으로 장착하여 공격력을 10만큼 증가시킵니다."},
[235530] = {name = "[q3]설계도: 흑요석 조준경", additional_info = "획득 시 귀속\n기계공학 (300) 필요\n[q]\"흑요석 조준경 만드는 법을 배웁니다.\""},
[235597] = {name = "[q2]주문 기록: 동결", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]투구에 동결 룬을 새깁니다.\n\n\n5초 동안 대상을 기절시킵니다. 얼어붙은 대상에게만 사용할 수 있습니다. 기절에 면역인 대상에게는 [462 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ]에서 [538 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100 * ( 1 ) ]의 피해를 입힙니다. 이 공격력은 빙하 작용의 효과를 받지만 중첩을 소모하지 않습니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235598] = {name = "[q2]주문 기록: 얼음 핏줄", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]바지에 얼음 핏줄 룬을 새깁니다.\n\n\n주문 시전을 빠르게 하여, 주문 시전 속도를 20%만큼 증가시키고 주문 시전 중 피해로 인한 시전 밀림 효과를 100%만큼 감소시킵니다. 20초 동안 지속됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235599] = {name = "[q2]주문 기록: 시간 변칙", additional_info = "획득 시 귀속\n고유 아이템\n직업: 마법사\n[q2]투구에 시간 변칙 룬을 새깁니다.\n\n\n시간 마력의 구슬을 발사합니다. 구슬은 전방으로 천천히 이동하며 매 2초마다 주위 모든 파티원에게 15초 동안 [100 * (13.828124 + 0.018012 * 60 + 0.044141 * 60 * 60) / 100]의 피해 흡수 보호막을 부여합니다. 파티원이 구슬 주위에 있으면 보호막의 피해 흡수량이 축적됩니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235600] = {name = "[q2]천상의 폭풍의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]가슴보호구에 천상의 폭풍 룬을 새깁니다.\n\n\n즉시 무기로 공격하여 8미터 반경 내에 있는 최대 4명의 적에게 무기 공격력의 110%에 해당하는 피해를 입힙니다. 또한 입힌 피해의 최대 25%만큼 최대 3명의 파티원 혹은 공격대원의 생명력을 회복시킵니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235601] = {name = "[q2]광신의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]투구에 광신 룬을 새깁니다.\n\n\n신성 주문의 치명타 및 극대화율이 18%만큼 증가합니다. 추가로 치유 주문이 극대화 효과를 발휘하면 12초에 걸쳐 치유량의 60%만큼 치유합니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235602] = {name = "[q2]정의의 망치의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]팔보호구에 정의의 망치 룬을 새깁니다.\n\n\n대상과 주위 최대 3명의 대상에게 주장비 초당 공격력의 4배에 해당하는 신성 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235603] = {name = "[q2]정의의 복수의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]망토에 정의로운 복수 룬을 새깁니다\n\n\n천상의 폭풍, 성전사의 일격, 심판이 치명타로 적중하면 활성화되어 있는 동안 대상에게 30%의 추가 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235604] = {name = "[q2]정의의 방패의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]망토에 정의의 방패 룬을 새깁니다\n\n\n적을 방패로 가격합니다. 방패의 피해 방어량에 따라 증가하는 신성 피해와 [179 * (9.046514 + 0.676562 * 60 + 0.019349 * 60 * 60) / 100]의 추가 신성 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235605] = {name = "[q2]충격과 공포의 룬", additional_info = "획득 시 귀속\n고유 아이템\n직업: 성기사\n[q2]망토에 충격과 공포 룬을 새깁니다.\n\n\n정의의 격노가 활성화되지 않은 동안 신성 충격 피해를 입히면 1분 동안 주문 공격력이 지능의 200%만큼 증가하고 생성하는 위협 수준은 30%만큼 감소합니다.\n\n 빛 주입을 각인했을 경우, 10초 동안 햇살이 부여됩니다.\n\n\n NPC 대상에게 천상의 폭풍과 성전사의 일격, 근접 공격 사용 시 햇살이 신성 주문력의 60%에 해당하는 추가 신성 피해를 입힙니다.\n[q]\"새로운 각인술 능력을 배웁니다.\""},
[235785] = {name = "죽음의 고개 우리 \"열쇠\"", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"당신은 냉철한 관찰력을 발휘해 이 \"열쇠\"가 실제로는 테두리가 날카로운 돌멩이에 지나지 않는다는 결론에 곧바로 도달했습니다. 요컨대 이걸로 자물쇠를 후려치면 우리가 열릴 것입니다.\""},
[235786] = {name = "[q2]카라잔 수집품", additional_info = "획득 시 귀속\n고유 아이템 (99)"},
[235787] = {name = "고대 강철나무 가지", additional_info = "퀘스트 아이템\n고유 아이템"},
