[235789] = {name = "생명의 불꽃", additional_info = "퀘스트 아이템\n고유 아이템"},
[235790] = {name = "[q2]마력 깃든 횃불", additional_info = "퀘스트 아이템\n고유 아이템\n[q2]사용 효과: 마력 깃든 횃불을 높이 들어 카라잔 납골당 주위의 어둠을 무효화합니다. (15 초 재사용 대기시간)"},
[235825] = {name = "모래의 비약", additional_info = "획득 시 귀속\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 실리더스, 안퀴라즈, 동부 역병지대, 낙스라마스에서 대상에 대한 모든 공격력이 2%만큼, 치명타 및 극대화 피해는 추가로 2%만큼 증가합니다. (3 초 재사용 대기시간)"},
[235852] = {name = "[q2]보랏빛 주머니", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n[q]\"달라란 키린 토의 징표가 새겨진 작은 주머니입니다. 작은 물건이 몇 개 들어 있는 듯한데, 특이하게도 도저히 열리지 않습니다.\""},
[235867] = {name = "양피지 조각", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"큰 포스터나 전단에서 찢겨 나온 듯한 양피지 조각입니다. 그나마 알아볼 수 있는 단어라곤... 대마법사 타르시스 키르몰디르라는 이름뿐입니다.\""},
[235868] = {name = "[q4]노여움의 보루", additional_info = "획득 시 귀속\n{보조장비} {방패}\n방어도 3177\n61의 피해 방어\n체력 +14\n내구도 120 / 120\n요구 레벨 60\n[q2]착용 효과: 근접 공격자에게 100의 암흑 피해를 입힙니다. 입힌 피해의 2배에 해당하는 위협 수준을 생성합니다.\n[q2]착용 효과: 방패로 적의 공격을 방어할 확률이 3%만큼 증가합니다.\n[q2]착용 효과: 방어 숙련도 +10"},
[235869] = {name = "[q4]지배자의 수도두건", additional_info = "축성\n획득 시 귀속\n{머리} {가죽}\n방어도 198\n체력 +10\n지능 +14\n정신력 +10\n내구도 70 / 70\n요구 레벨 60\n[q2]착용 효과: 모든 주문 및 효과에 의한 피해와 치유량이 최대 59만큼 증가합니다."},
