[236444] = {name = "[q3]검객의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 검객의 영혼을 주입합니다.\n\n단검으로 치명타를 적중시킬 확률이 5%만큼 증가합니다."},
[236445] = {name = "[q3]추적자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 추적자의 영혼을 주입합니다.\n\n매복으로 치명타를 성공시킬 확률이 30%만큼 증가합니다."},
[236446] = {name = "[q3]효율의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 효율의 영혼을 주입합니다.\n\n마무리 일격의 기력 소모량이 50%만큼 감소합니다."},
[236447] = {name = "[q3]단검 곡예사의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 단검 곡예사의 영혼을 주입합니다.\n\n얕은 상처일 뿐 및 칼춤이 활성화된 동안 혈폭풍, 나팔총, 칼날 부채의 기력 소모량이 20만큼 감소하고 위협 수준을 추가로 100%만큼 생성합니다."},
[236448] = {name = "[q3]그림자 달인의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 그림자 달인의 영혼을 주입합니다.\n\n소멸이 지속시간 동안 받는 마법 피해를 50%만큼 감소시키지만 더는 은신을 부여하거나 이동 방해 효과를 해제하지 않습니다."},
[236449] = {name = "[q3]곡예사의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 곡예사의 영혼을 주입합니다.\n\n마무리 일격 사용 시 소모한 연계 점수당 20%의 확률로 다음 10초 안에 근접 공격에 적중당할 때 받는 물리 피해가 20%만큼 감소합니다."},
[236450] = {name = "[q3]준비된 싸움꾼의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 준비된 싸움꾼의 영혼을 주입합니다.\n\n충격 완화가 연계 점수를 얻을 때마다 활성화됩니다."},
[236451] = {name = "[q3]검은띠의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 검은띠의 영혼을 주입합니다.\n\n충격 완화가 중첩당 아이템으로 증가하는 방어도를 20%만큼 추가로 증가시킵니다. 최대 100%까지 증가합니다."},
[236452] = {name = "[q3]장물아비의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 장물아비의 영혼을 주입합니다.\n\n대상이 회피하거나 무기 막기에 성공할 때마다 맹고쉬의 재사용 대기시간이 초기화됩니다."},
[236453] = {name = "[q3]칼잡이의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 칼잡이의 영혼을 주입합니다.\n\n맹고쉬가 주위에 있는 1명의 추가 대상을 공격하며, 10초 동안 사악한 일격이 주위에 있는 1명의 추가 대상을 공격합니다. 이 추가 공격은 폭풍의 칼날로 복제되지 않습니다."},
[236454] = {name = "[q3]피의 갈증의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 도적\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 피의 갈증의 영혼을 주입합니다.\n\n활성화된 동안 맹고쉬가 추가로 사악한 일격으로 입힌 모든 피해의 15%만큼 생명력을 회복시킵니다. 초과 치유량은 피의 방벽으로 전환되어 시전자 최대 생명력의 최대 20%에 해당하는 피해를 흡수합니다."},
[236455] = {name = "[q3]수혈자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 수혈자의 영혼을 주입합니다.\n\n생명력 전환이 마나를 50%만큼 추가로, 위협 수준은 100%만큼 덜 생성합니다."},
[236456] = {name = "[q3]제련된 자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 제련된 자의 영혼을 주입합니다.\n\n주문 및 공격의 치명타 및 극대화율이 2%만큼 증가합니다."},
[236457] = {name = "[q3]척살의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 척살의 영혼을 주입합니다.\n\n일몰 특성의 발동 확률이 4%만큼 증가합니다. 소각이 4%의 확률로 대상의 생명력에 상관없이 죽음의 예언을 발동시킵니다."},
[236458] = {name = "[q3]부패인도자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 부패인도자의 영혼을 주입합니다.\n\n주기적인 주문 및 지옥수호병의 공격력이 10 + (5 * 연계 점수)%만큼 증가합니다."},
[236459] = {name = "[q3]악인의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 악인의 영혼을 주입합니다.\n\n암흑불길과 불안정한 고통, 고통의 저주 주문으로 주기적인 피해를 입히거나 지옥수호병이 피해를 입히면 4%의 확률로 어둠의 무아지경이 부여됩니다."},
[236460] = {name = "[q3]흑마술사의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 흑마술사의 영혼을 주입합니다.\n\n어둠의 화살이 대상에게 걸린 효과 하나당 10 + (5 * 연계 점수)%만큼, 최대 30 + (5 * 연계 점수)%의 추가 피해를 입힙니다."},
[236461] = {name = "[q3]혼돈의 전령의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 혼돈의 전령의 영혼을 주입합니다.\n\n혼돈의 화살의 재사용 대기시간이 50%만큼 감소하며, 혼돈의 화살과 어둠의 화살의 공격력은 10%만큼 증가합니다. 추가로 혼돈의 화살이 어둠의 화살 연마 특성을 발동시킵니다. 추가로 26회 충전되며, 암흑불길의 추가 충전 횟수와 중첩되지 않습니다."},
[236462] = {name = "[q3]방화자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 방화자의 영혼을 주입합니다.\n\n대상에게 점화를 적중시킬 때마다 20초 동안 화염 공격력이 5%만큼 증가합니다. 최대 2번까지 중첩됩니다."},
[236463] = {name = "[q3]불지옥 안내자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 불지옥 안내자의 영혼을 주입합니다.\n\n악마 소환수가 흑마법사의 능력치로 증가하는 전투력과 주문 공격력이 20%만큼 증가합니다."},
[236464] = {name = "[q3]악마군주의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 악마군주의 영혼을 주입합니다.\n\n악마학의 대가 특성의 이로운 효과가 50%만큼 증가합니다."},
[236465] = {name = "[q3]악마 퇴치자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 악마 퇴치자의 영혼을 주입합니다.\n\n추방이 즉시 시전됩니다. 또한 악마 상태일 때 자신에게 시전할 수 있습니다. 참을성에 걸린 동안에는 자신에게 추방을 시전할 수 없으며 시전 시 1분 동안 참을성이 부여됩니다."},
[236466] = {name = "[q3]고통받는 자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 고통받는 자의 영혼을 주입합니다.\n\n피해를 받을 때마다 흑마법사와 소환수가 받은 피해에 해당하는 마나를 회복합니다. 공격받을 때마다 최대 420의 마나를 회복합니다. 몇 초에 한 번씩만 발동합니다."},
[236467] = {name = "[q3]화염망령의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 화염망령의 영혼을 주입합니다.\n\n어둠의 회전베기 적중 시 20%의 확률로 영혼의 조각이 생성되고 영혼의 불꽃의 재사용 대기시간이 초기화되며, 다음 10초 안에 사용하는 영혼의 불꽃이 즉시 시전됩니다."},
[236468] = {name = "[q3]살점포식자의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 살점포식자의 영혼을 주입합니다.\n\n30미터 내의 적을 대상으로 지정하면 생명력 전환이 대상의 생명력을 대가로 마나를 회복시키지만 입히는 피해가 50 + (5 * 연계 점수)%만큼 감소합니다. 마나 획득량은 동일하게 유지됩니다."},
[236469] = {name = "[q3]심연의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 심연의 영혼을 주입합니다.\n\n탈태가 활성화된 동안 공격 능력 및 악마 소환이 영혼의 조각을 소모하지 않습니다. 추가로 어둠의 연소로 대상에게 피해를 입히면 최대 생명력의 15%만큼 생명력을 회복합니다."},
[236470] = {name = "[q3]공허살이의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 공허살이의 영혼을 주입합니다.\n\n자신에 대한 초과 치유량이 피해를 흡수하는 보호막으로 전환됩니다. 이 피해 흡수 보호막은 최대 생명력의 30 + (5 * 연계 점수)%에 해당하는 피해를 흡수할 수 있으며, 여러 치유 효과로 중첩됩니다."},
[236471] = {name = "[q3]암영 칼날의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 암영 칼날의 영혼을 주입합니다.\n\n어둠의 회전베기의 재사용 대기시간이 1.5초만큼 감소합니다."},
[236472] = {name = "[q3]의식술사의 영혼", additional_info = "획득 시 귀속\n고유 아이템 (20)\n직업: 흑마법사\n요구 레벨 55\n[q2]사용 효과: 어깨보호구에 영구적으로 의식술사의 영혼을 주입합니다.\n\n악마 소환수가 활성화된 동안에도 악의 제물 효과가 지속됩니다. 단, 제물로 바친 악마를 다시 소환하지 말아야 합니다. 악의 제물 효과는 한 번에 하나만 활성화됩니다."},
