[239013] = {name = "[q5]수정 도끼", additional_info = "획득 시 귀속\n[q]\"이것도 날이 빛나긴 하네요.\""},
[239016] = {name = "신성한 소금", additional_info = "제작 재료\n\"보통 십자군 성전사들 사이에서 액막이 부적으로 쓰입니다. 편리하게도 요리용으로도 쓸 만합니다.\""},
[239017] = {name = "[q2]이색 향신료", additional_info = "제작 재료\n\"강도 높은 규제를 받는 상품입니다. 직접 사고파는 건 현명한 생각이 아닙니다. 잔칫상을 만드는 요리사들 사이에서 큰 인기를 구가합니다.\""},
[239021] = {name = "캐리의 요리책", additional_info = "획득 시 귀속\n요리 (280) 필요\n사용 효과: 캐리 하스파이어가 가장 아끼는 잔칫상 요리하는 법을 배웁니다."},
[239060] = {name = "[q4]산의 의지", additional_info = "획득 시 귀속\n{주장비} {둔기}\n{공격력 169 - 316 } {속도 2.90}\n(초당 공격력 83.62)\n힘 +17\n체력 +5\n내구도 105 / 105\n요구 레벨 60\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 공격이 회피당하거나 무기 막기에 막힐 확률이 1%만큼 감소합니다.\n[q2]발동 효과: 산의 의지를 일깨워 15초 동안 물리 공격력이 5%만큼, 방어도가 500만큼, 크기가 20%만큼 증가합니다.\n[q]\"한때 위대한 대장장이의 망치였습니다. 이 걸작을 손에 쥐기만 해도 영감이 샘솟습니다.\""},
[239092] = {name = "터무니없이 장황한 편지", additional_info = "퀘스트 아이템\n고유 아이템\n퀘스트 시작 아이템"},
[239097] = {name = "[q3]대성당 열쇠", additional_info = "창조 아이템\n획득 시 귀속\n고유 아이템"},
[239117] = {name = "[q4]십자군의 성배", additional_info = "획득 시 귀속\n[q]\"적절한 붉은십자군 성전사 제작 세트 아이템과 함께 신 아발론의 브라이온 스틸블레이드에게 가져가면 직업 세트 아이템으로 교환할 수 있습니다.\""},
[239119] = {name = "신성한 화살", additional_info = "퀘스트 아이템\n[q]\"적을 징치하는 화살에 축복 있으라.\""},
[239123] = {name = "[q0]몬스터 - 활_1H_표준_C_01 - 붉은색", additional_info = "획득 시 귀속\n{원거리 장비} {활}\n{공격력 1 - 2 } {속도 2.00}\n(초당 공격력 0.75)\n내구도 18 / 18"},
[239147] = {name = "[q3]십자군 성전사의 배낭", additional_info = "착용 시 귀속\n24칸 가방"},
[239148] = {name = "[q4]붉은십자군 여명매듭 가방", additional_info = "착용 시 귀속\n30칸 가방"},
[239149] = {name = "[q3]도안: 십자군 성전사의 배낭", additional_info = "획득 시 귀속\n재봉술 (250) 필요\n[q]\"십자군 성전사의 배낭 만드는 법을 배웁니다.\""},
[239150] = {name = "[q4]도안: 붉은십자군 여명매듭 가방", additional_info = "획득 시 귀속\n재봉술 (290) 필요\n[q]\"붉은십자군 여명매듭 가방 만드는 법을 배웁니다.\""},
[239159] = {name = "[q2]S03 - 붉은십자군 초소 - 대장 방패", additional_info = "착용 시 귀속\n{보조장비} {방패}\n방어도 1861\n35의 피해 방어\n힘 +3\n체력 +14\n내구도 85 / 85\n요구 레벨 56"},
[239196] = {name = "[q5]훼손된 빛벼림 칼날", additional_info = "획득 시 귀속\n퀘스트 시작 아이템\n직업: 전사 , 성기사 , 사냥꾼"},
[239197] = {name = "[q4]다시 벼려낸 파멸의 인도자의 칼날", additional_info = "획득 시 귀속"},
[239215] = {name = "[q4]그을린 문장", additional_info = "획득 시 귀속\n고유 아이템\n퀘스트 시작 아이템\n요구 레벨 60"},
[239216] = {name = "[q5]빛벼림 철", additional_info = "획득 시 귀속\n직업: 전사 , 성기사 , 사냥꾼"},
[239218] = {name = "[q5]바위구체자의 기록", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"어설픈 글씨체로 괴발개발 쓰여 있지만, 내용을 자세히 살펴보면 진정한 천재가 만든 도면이자 기획서임을 알 수 있습니다.\""},
[239219] = {name = "[q4]파멸의 인도자의 문장", additional_info = "획득 시 귀속\n고유 아이템\n요구 레벨 60\n[q2]사용 효과: 파멸의 인도자의 문장과 다시 벼려낸 파멸의 인도자의 칼날, 파멸의 인도자의 자루를 결합합니다."},
[239221] = {name = "[q0]몬스터 - 도검1H, 기본", additional_info = "{주장비} {검}\n{공격력 1 - 2 } {속도 2.00}\n(초당 공격력 0.75)\n내구도 20 / 20"},
[239222] = {name = "[q3]설계도: 접이식 덤불", additional_info = "획득 시 귀속\n기계공학 (250) 필요\n[q]\"접이식 덤불 만드는 법을 배웁니다.\""},
[239223] = {name = "가정 집기", additional_info = "퀘스트 아이템\n[q]\"오페라나 연극에서는 꽤 그럴싸할 것 같습니다.\""},
[239225] = {name = "세련된 깃펜", additional_info = "퀘스트 아이템\n[q]\"이걸로 본인의 서명을 써 내려갈 때 얼마나 짜릿할지 상상만 해도 즐겁습니다.\""},
[239246] = {name = "피즐퓨즈의 구매 목록", additional_info = "획득 시 귀속\n고유 아이템\n[q]\"글쓴이가 되는대로 떠오른 생각을 끄적인 목록입니다.\"\n[q2]<읽으려면 마우스 오른쪽 클릭>"},
[239248] = {name = "[q4]붉은십자군 폐품함", additional_info = "획득 시 귀속\n[q]\"주변에 굴러다니던 고물이 들어 있습니다. 종종 무모한 모험가가 남긴 귀중품이 나오기도 합니다.\"\n[q2]<열려면 마우스 오른쪽 클릭>"},
[239292] = {name = "포지라이트의 기록", additional_info = "퀘스트 아이템\n고유 아이템\n[q]\"프랑클론 포지라이트의 여러 생각과 저작이 정리되어 있습니다.\""},
[239301] = {name = "[q5]타락한 파멸의 인도자", additional_info = "축성\n획득 시 귀속\n고유 아이템\n{양손 장비} {검}\n{공격력 357 - 536 } {속도 3.80}\n(초당 공격력 117.50)\n힘 +53\n체력 -30\n내구도 145 / 145\n요구 레벨 60\n[q2]착용 효과: 파멸의 인도자의 의지를 착용자에게 주입시킵니다.\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 3%만큼 증가합니다.\n[q2]착용 효과: 공격이 회피당하거나 무기 막기에 막힐 확률이 2%만큼 감소합니다.\n[q2]발동 효과: 최대 5명의 적에게서 475 에서 525의 생명력을 훔쳐내, 흡수한 적 하나당 힘 또는 민첩성이 30만큼 증가합니다. 최대 5번까지 중첩됩니다.\n[q]\"붉은십자군 대영주의 검\""},
[239302] = {name = "붉은십자군 제복 허리띠", additional_info = "퀘스트 아이템\n[q]\"튼튼한 강철 죔쇠로 고정한 굵은 가죽끈입니다. 진정한 걸작 허리띠로, 무분별한 땜질에 처참하게 훼손될 일만 남았습니다.\""},
[239316] = {name = "삼각측량 사모플랜지", additional_info = "퀘스트 아이템\n기계공학 (1) 필요\n[q2]사용 효과: 지정된 삼각측량 지점에서 장치를 사용해 피즐퓨즈의 순간이동기 조정을 돕습니다. (10 초 재사용 대기시간)"},
[239512] = {name = "[q4]빛파괴자 손목보호구", additional_info = "축성\n획득 시 귀속\n{손목} {판금}\n방어도 477\n힘 +29\n민첩성 +10\n체력 +13\n내구도 55 / 55\n직업: 전사\n요구 레벨 60\n[q2]착용 효과: 모든 주문과 공격의 적중률이 1%만큼 증가합니다.\n[q2]착용 효과: 공격 속도가 1%만큼 증가합니다.\n\n[q]빛파괴자의 전쟁판금 장비 (0/8)\n[q0]빛파괴자 철갑투구\n빛파괴자 어깨보호구\n빛파괴자 흉갑\n빛파괴자 허리띠\n빛파괴자 허벅지 보호구\n빛파괴자 경갑\n빛파괴자 손목보호구\n빛파괴자 손장갑\n[q0](2) 세트 : 전투 태세 또는 광폭 태세일 때 영웅의 일격, 회전베기, 속전속결의 공격력이 20%만큼 증가합니다. 회전베기가 1명의 추가 적에게 적중하고 피 분출을 발동시킵니다.\n(4) 세트 : 대상에게 소용돌이, 영웅의 일격, 속전속결 또는 회전베기를 적중시킬 때마다 다음 격돌의 공격력이 20%만큼 증가하며, 최대 5번까지 중첩됩니다.\n(6) 세트 : 치명상이 피해를 입힐 때마다 소용돌이의 남은 재사용 대기시간이 3초만큼 감소합니다. 소용돌이가 치명상에 걸린 대상에게 100%의 추가 피해를 입힙니다."},
[239513] = {name = "[q4]빛파괴자 허리띠", additional_info = "축성\n획득 시 귀속\n{허리} {판금}\n방어도 613\n힘 +36\n민첩성 +10\n체력 +18\n내구도 55 / 55\n직업: 전사\n요구 레벨 60\n[q2]착용 효과: 모든 주문과 공격의 주문 극대화 확률과 치명타 적중도가 1%만큼 증가합니다.\n[q2]착용 효과: 공격 속도가 2%만큼 증가합니다.\n\n[q]빛파괴자의 전쟁판금 장비 (0/8)\n[q0]빛파괴자 철갑투구\n빛파괴자 어깨보호구\n빛파괴자 흉갑\n빛파괴자 허리띠\n빛파괴자 허벅지 보호구\n빛파괴자 경갑\n빛파괴자 손목보호구\n빛파괴자 손장갑\n[q0](2) 세트 : 전투 태세 또는 광폭 태세일 때 영웅의 일격, 회전베기, 속전속결의 공격력이 20%만큼 증가합니다. 회전베기가 1명의 추가 적에게 적중하고 피 분출을 발동시킵니다.\n(4) 세트 : 대상에게 소용돌이, 영웅의 일격, 속전속결 또는 회전베기를 적중시킬 때마다 다음 격돌의 공격력이 20%만큼 증가하며, 최대 5번까지 중첩됩니다.\n(6) 세트 : 치명상이 피해를 입힐 때마다 소용돌이의 남은 재사용 대기시간이 3초만큼 감소합니다. 소용돌이가 치명상에 걸린 대상에게 100%의 추가 피해를 입힙니다."},
